#pragma intrinsic(_ReturnAddress)

/* MSVC references this marker whenever a translation unit uses floating-point
 * constants.  The no-CRT module supplies it directly instead of importing the
 * C runtime only to position and size the InfoPanel text element. */
int _fltused = 0;

/*
 * Chrome Engine's exported ILevel UI methods and object identifiers take
 * ttl::string_base<char> by reference.  Visible UI text uses the otherwise
 * identical ttl::string_base<wchar_t> value.  This distinction is observable
 * in the exact DevTools build: MenuSteamWorkshop::FillMaps allocates and
 * copies two bytes per code unit before calling UIListBox::AddItem.  All
 * strings remain alive for the complete call.
 */
typedef struct DlumaTtlString
{
    const char *data;
    unsigned int size;
    unsigned int capacity;
} DlumaTtlString;

typedef struct DlumaTtlWideString
{
    const WCHAR *data;
    unsigned int size;
    unsigned int capacity;
} DlumaTtlWideString;

typedef struct DlumaUiVec3
{
    float x;
    float y;
    float z;
} DlumaUiVec3;

typedef struct DlumaUiVec4
{
    float x;
    float y;
    float z;
    float w;
} DlumaUiVec4;

typedef char DlumaTtlStringSizeMustBe16[(sizeof(DlumaTtlString) == 16) ? 1 : -1];
typedef char DlumaTtlWideStringSizeMustBe16[(sizeof(DlumaTtlWideString) == 16) ? 1 : -1];

