#define DLUMA_UI_MOD_DETAILS_VISIBLE_ROWS 9U
#define DLUMA_UI_MOD_DETAILS_HINT_COLUMNS 64U
#define DLUMA_UI_MOD_DETAILS_HINT_CAPACITY (DLUMA_UI_WIDE_ROW_CAPACITY + 512U)
/* The runtime deliberately bounds copied presentation records to this same
 * capacity.  Keep the UI cache equal to that bound so a script's tracked
 * quest cannot disappear merely because it was reported after row 64. */
#define DLUMA_UI_MAX_QUESTS DLUMA_LUA_QUEST_UI_MAX_SNAPSHOTS
#define DLUMA_UI_SETTINGS_VISIBLE_ROWS 6U
#define DLUMA_UI_WIDE_LABEL_CAPACITY 128U
#define DLUMA_UI_SOURCE_OPTION_CODE_UNIT_LIMIT 34U
#define DLUMA_UI_WIDE_POPUP_CAPACITY 4096U
#define DLUMA_UI_WIDE_ROW_CAPACITY 4096U
#define DLUMA_UI_SETTING_VALUE_CAPACITY 4096U
#define DLUMA_UI_EDIT_TEXT_OFFSET 0x00A0UL
#define DLUMA_UI_EDIT_TEXT_MAX_CODE_UNITS 512U
#define DLUMA_UI_QUEST_REFRESH_MS 250UL
#define DLUMA_UI_LOGS_REFRESH_MS 250UL
#define DLUMA_UI_LOGS_VISIBLE_ROWS 9U
#define DLUMA_UI_QUEST_FIELD_TEXT_LIMIT 1024U
/* Keep the complete escaped HTML row within its fixed UTF-16 staging buffer.
 * These are rendered-byte budgets, not source-string limits. */
#define DLUMA_UI_QUEST_ROW_TITLE_RENDER_LIMIT 320U
#define DLUMA_UI_QUEST_ROW_IDENTIFIER_RENDER_LIMIT 128U
#define DLUMA_UI_QUEST_ROW_PHASE_RENDER_LIMIT 320U
#define DLUMA_UI_QUEST_ROW_OBJECTIVES_RENDER_LIMIT 1536U
/* There is no fingerprinted HUD-child attachment point in the supported
 * build.  Keep the public tracker contract explicitly disabled rather than
 * mounting a loose HUD XUI or guessing a HUD vtable. */
#define DLUMA_UI_QUEST_HUD_TRACKER_AVAILABLE 0

