static int dluma_ui_loader_setting_visible(
    const DlumaLoaderSettingDefinition* definition)
{
    DlumaHostKind kind;
    if (!definition) return 0;
    if (dluma_wstricmp(definition->section, L"GameFixes") == 0 &&
        dluma_wstricmp(definition->key, L"CustomMapAssetIsolation") == 0)
        return g_dluma.config.developer_mode != 0;
    if (dluma_wstricmp(
            definition->key, L"steam_rich_presence_enabled") != 0)
        return 1;
    kind = dluma_dual_host_runtime_kind();
    return kind == DLUMA_HOST_PLAYER_STANDALONE ||
           kind == DLUMA_HOST_PLAYER_EDITOR_PLAYTEST;
}
