static void dluma_ui_localize_text(const char *key, const char *fallback,
                                 char *out, unsigned int capacity)
{
    if (!out || !capacity) return;
    (void)dluma_text_get_utf8(key, fallback, out, capacity);
}

static DWORD dluma_ui_read_u32(const void *memory)
{
    const BYTE *bytes = (const BYTE *)memory;
    return (DWORD)bytes[0] | ((DWORD)bytes[1] << 8) |
           ((DWORD)bytes[2] << 16) | ((DWORD)bytes[3] << 24);
}

static int dluma_ui_get_pe_identity(HMODULE module, DWORD *timestamp, DWORD *image_size)
{
    BYTE *base = (BYTE *)module;
    DWORD nt_offset;
    if (!base || !dluma_is_readable(base, 0x100))
        return 0;
    if (base[0] != 'M' || base[1] != 'Z')
        return 0;
    nt_offset = dluma_ui_read_u32(base + 0x3C);
    if (nt_offset > 0x100000 || !dluma_is_readable(base + nt_offset, 0x58))
        return 0;
    if (memcmp(base + nt_offset, "PE\0\0", 4) != 0)
        return 0;
    *timestamp = dluma_ui_read_u32(base + nt_offset + 8);
    *image_size = dluma_ui_read_u32(base + nt_offset + 0x50);
    return 1;
}

static int dluma_ui_prepare_xui_filename_redirect(
    DWORD target_rva,
    const char *original_name,
    const char *redirected_name,
    size_t original_size,
    size_t redirected_size,
    BYTE **address_state,
    unsigned char *applied_state,
    unsigned char *owned_state,
    const char *original_log_label,
    const char *redirect_log_label,
    const char *status_log_label)
{
    BYTE *base;
    BYTE *address;
    DWORD timestamp;
    DWORD image_size;
    DWORD old_protect;
    DWORD restored_protect;
    DlumaXuiRedirectDecision decision;

    if (*applied_state)
        return 1;
    dluma_log_pair("INFO", original_log_label, original_name);
    dluma_log_pair("INFO", redirect_log_label, redirected_name);
    if (!dluma_xui_redirect_names_same_size(original_size, redirected_size))
    {
        dluma_log_pair("ERROR", status_log_label, "name_length_mismatch");
        return 0;
    }

    g_dluma_menu_gamedll = GetModuleHandleW(L"gamedll_x64_rwdi.dll");
    if (!g_dluma_menu_gamedll ||
        !dluma_ui_get_pe_identity(g_dluma_menu_gamedll, &timestamp, &image_size))
    {
        dluma_log_pair("WARN", status_log_label, "gamedll_identity_unavailable");
        return 0;
    }
    if (!dluma_xui_redirect_identity_matches(
            timestamp, image_size,
            DLUMA_DEVTOOLS_GAMEDLL_TIMESTAMP,
            DLUMA_DEVTOOLS_GAMEDLL_IMAGE_SIZE))
    {
        dluma_log_pair("WARN", status_log_label, "unsupported_gamedll_identity");
        return 0;
    }
    if (target_rva > image_size || original_size > image_size - target_rva)
    {
        dluma_log_pair("WARN", status_log_label, "target_outside_image");
        return 0;
    }

    base = (BYTE *)g_dluma_menu_gamedll;
    address = base + target_rva;
    if (!dluma_is_readable(address, original_size))
    {
        dluma_log_pair("WARN", status_log_label, "target_unreadable");
        return 0;
    }
    decision = dluma_xui_redirect_decide(
        address, original_size, original_name, redirected_name, original_size);
    if (decision == DLUMA_XUI_REDIRECT_ALREADY_PRESENT)
    {
        *address_state = address;
        *applied_state = 1;
        *owned_state = 0;
        dluma_log_pair("INFO", status_log_label, "already_present_not_owned");
        return 1;
    }
    if (decision != DLUMA_XUI_REDIRECT_APPLY)
    {
        dluma_log_pair("WARN", status_log_label,
                     decision == DLUMA_XUI_REDIRECT_MISMATCH
                         ? "target_bytes_mismatch"
                         : "target_validation_failed");
        return 0;
    }
    if (!VirtualProtect(address, original_size, PAGE_READWRITE, &old_protect))
    {
        dluma_log_pair("WARN", status_log_label, "protection_change_failed");
        return 0;
    }
    memcpy(address, redirected_name, redirected_size);
    if (!VirtualProtect(address, original_size, old_protect,
                        &restored_protect))
    {
        memcpy(address, original_name, original_size);
        (void)VirtualProtect(address, original_size, old_protect,
                             &restored_protect);
        FlushInstructionCache(GetCurrentProcess(), address, original_size);
        dluma_log_pair("ERROR", status_log_label,
                     "protection_restore_failed_rolled_back");
        return 0;
    }
    FlushInstructionCache(GetCurrentProcess(), address, original_size);
    *address_state = address;
    *applied_state = 1;
    *owned_state = 1;
    dluma_log_pair("INFO", status_log_label, "applied");
    return 1;
}

static void dluma_ui_restore_xui_filename_redirect(
    BYTE **address_state,
    unsigned char *applied_state,
    unsigned char *owned_state,
    const char *original_name,
    const char *redirected_name,
    size_t name_size,
    const char *status_log_label)
{
    DWORD old_protect;
    DWORD restored_protect;

    if (!*applied_state || !*address_state)
        return;
    if (!*owned_state)
    {
        dluma_log_pair("INFO", status_log_label, "not_restored_not_owned");
    }
    else if (!dluma_is_readable(*address_state, name_size))
    {
        dluma_log_pair("WARN", status_log_label, "restore_target_unreadable");
    }
    else if (!dluma_xui_redirect_should_restore(
                 1, *address_state, name_size,
                 redirected_name, name_size))
    {
        dluma_log_pair("WARN", status_log_label,
                     "not_restored_modified_after_install");
    }
    else if (!VirtualProtect(*address_state, name_size, PAGE_READWRITE,
                             &old_protect))
    {
        dluma_log_pair("WARN", status_log_label,
                     "restore_protection_change_failed");
    }
    else
    {
        memcpy(*address_state, original_name, name_size);
        if (!VirtualProtect(*address_state, name_size, old_protect,
                            &restored_protect))
            dluma_log_pair("WARN", status_log_label,
                         "restored_protection_restore_failed");
        else
            dluma_log_pair("INFO", status_log_label, "restored");
        FlushInstructionCache(GetCurrentProcess(), *address_state, name_size);
    }
    *address_state = 0;
    *applied_state = 0;
    *owned_state = 0;
}

int dluma_ui_prepare_main_menu_redirect(void)
{
    static const char original_name[] = "MenuMain_PC_workshop.xui";
    static const char loader_name[] = "DLM_Main_PC_workshop.xui";
    if (!dluma_custom_main_menu_selected_main_xui_alias(
            g_dluma_main_menu_redirect_name,
            DLUMA_ARRAY_COUNT(g_dluma_main_menu_redirect_name)))
        dluma_str_copy(
            g_dluma_main_menu_redirect_name,
            DLUMA_ARRAY_COUNT(g_dluma_main_menu_redirect_name), loader_name);
    if (strlen(g_dluma_main_menu_redirect_name) !=
        strlen(original_name))
    {
        dluma_log_pair(
            "WARN", "main_menu_xui_redirect_status",
            "selected_redirect_name_length_invalid");
        return 0;
    }
    return dluma_ui_prepare_xui_filename_redirect(
        DLUMA_DEVTOOLS_MAIN_MENU_NAME_RVA,
        original_name, g_dluma_main_menu_redirect_name,
        sizeof(original_name), sizeof(original_name),
        &g_dluma_main_menu_name_address,
        &g_dluma_main_menu_redirect_applied,
        &g_dluma_main_menu_redirect_owned,
        "main_menu_xui_original",
        "main_menu_xui_redirect",
        "main_menu_xui_redirect_status");
}

void dluma_ui_restore_main_menu_redirect(void)
{
    static const char original_name[] = "MenuMain_PC_workshop.xui";
    dluma_ui_restore_xui_filename_redirect(
        &g_dluma_main_menu_name_address,
        &g_dluma_main_menu_redirect_applied,
        &g_dluma_main_menu_redirect_owned,
        original_name, g_dluma_main_menu_redirect_name, sizeof(original_name),
        "main_menu_xui_redirect_status");
    g_dluma_main_menu_redirect_name[0] = 0;
    if (!g_dluma_workshop_menu_redirect_applied)
        g_dluma_menu_gamedll = 0;
}

