static int dluma_ui_bind_info_panel(void)
{
    static const BYTE retail_create_signature[16] = {
        0x48, 0x89, 0x5C, 0x24, 0x08, 0x48, 0x89, 0x6C,
        0x24, 0x10, 0x48, 0x89, 0x74, 0x24, 0x18, 0x57};
    static const BYTE retail_show_signature[16] = {
        0x40, 0x56, 0x48, 0x83, 0xEC, 0x50, 0x48, 0x8B,
        0x05, 0xE3, 0x6C, 0xA7, 0x00, 0x33, 0xF6, 0x8B};
    static const BYTE devtools_create_signature[16] = {
        0x48, 0x8B, 0xC4, 0x48, 0x89, 0x58, 0x08, 0x48,
        0x89, 0x70, 0x10, 0x48, 0x89, 0x78, 0x18, 0x55};
    static const BYTE devtools_show_signature[16] = {
        0x40, 0x53, 0x48, 0x83, 0xEC, 0x30, 0x48, 0x8B,
        0x05, 0xA3, 0x0C, 0xBB, 0x00, 0x33, 0xDB, 0x48};
    static const BYTE devtools_destroy_signature[16] = {
        0x40, 0x53, 0x48, 0x83, 0xEC, 0x20, 0x48, 0x8B,
        0x05, 0x93, 0x0E, 0xBB, 0x00, 0x33, 0xDB, 0x48};
    const BYTE *expected_create;
    const BYTE *expected_show;
    const BYTE *expected_destroy;
    BYTE *base;
    BYTE *create_address;
    BYTE *show_address;
    BYTE *destroy_address;
    DWORD timestamp;
    DWORD image_size;

    if (g_dluma_info_create_channel && g_dluma_info_show_text &&
        g_dluma_info_destroy_channel)
        return 1;
    if (g_dluma_info_bind_attempted)
        return 0;
    g_dluma_info_module = GetModuleHandleW(L"gamedll_x64_rwdi.dll");
    /* Module loading is transient; only an inspected image is a binding attempt. */
    if (!g_dluma_info_module) return 0;
    g_dluma_info_bind_attempted = 1;
    if (!dluma_ui_get_pe_identity(g_dluma_info_module, &timestamp, &image_size))
    {
        dluma_log_line("WARN", "Universal Screen binding: gamedll PE identity is unavailable.");
        return 0;
    }
    base = (BYTE *)g_dluma_info_module;
    if (timestamp == DLUMA_DEVTOOLS_GAMEDLL_TIMESTAMP &&
        image_size == DLUMA_DEVTOOLS_GAMEDLL_IMAGE_SIZE)
    {
        create_address = base + DLUMA_DEVTOOLS_INFO_CREATE_RVA;
        show_address = base + DLUMA_DEVTOOLS_INFO_SHOW_RVA;
        destroy_address = base + DLUMA_DEVTOOLS_INFO_DESTROY_RVA;
        expected_create = devtools_create_signature;
        expected_show = devtools_show_signature;
        expected_destroy = devtools_destroy_signature;
        g_dluma_info_panel = 0;
        g_dluma_info_abi = DLUMA_INFO_PANEL_ABI_DEVTOOLS;
    }
    else if (timestamp == DLUMA_RETAIL_GAMEDLL_TIMESTAMP &&
             image_size == DLUMA_RETAIL_GAMEDLL_IMAGE_SIZE)
    {
        (void)retail_create_signature;
        (void)retail_show_signature;
        dluma_log_line("WARN", "Universal Screen retail InfoPanel binding is disabled: DestroyChanel is not validated for this build.");
        return 0;
    }
    else
    {
        dluma_log_hex("WARN", "Universal Screen unsupported gamedll timestamp", timestamp);
        dluma_log_hex("WARN", "Universal Screen unsupported gamedll image size", image_size);
        return 0;
    }

    if (!dluma_is_readable(create_address, 16) ||
        !dluma_is_readable(show_address, 16) ||
        !dluma_is_readable(destroy_address, 16) ||
        memcmp(create_address, expected_create, 16) != 0 ||
        memcmp(show_address, expected_show, 16) != 0 ||
        memcmp(destroy_address, expected_destroy, 16) != 0)
    {
        g_dluma_info_abi = DLUMA_INFO_PANEL_ABI_NONE;
        dluma_log_line("WARN", "Universal Screen function bytes do not match the validated build; binding disabled.");
        return 0;
    }

    g_dluma_info_create_channel = create_address;
    g_dluma_info_show_text = show_address;
    g_dluma_info_destroy_channel = destroy_address;
    if (g_dluma_info_abi == DLUMA_INFO_PANEL_ABI_DEVTOOLS)
        dluma_log_line("INFO", "Validated DevTools InfoPanel ABI enabled for this exact gamedll build.");
    else
        dluma_log_line("INFO", "Validated retail InfoPanel ABI enabled for this exact gamedll build.");
    return 1;
}

static void dluma_ttl_string_init(DlumaTtlString *value, const char *text)
{
    unsigned int length = (unsigned int)strlen(text);
    value->data = text;
    value->size = length;
    value->capacity = length;
}

static int dluma_ttl_wide_string_init_utf8(DlumaTtlWideString *value,
                                         WCHAR *storage,
                                         unsigned int storage_count,
                                         const char *text)
{
    unsigned int length;
    if (!value || !storage || !storage_count || !text)
        return 0;
    storage[0] = 0;
    value->data = storage;
    value->size = 0;
    value->capacity = 0;
    if (!dluma_utf8_to_wide(text, storage, storage_count))
        return 0;
    length = (unsigned int)wcslen(storage);
    value->size = length;
    value->capacity = length;
    return 1;
}

static void dluma_ui_publish_level_snapshot(
    const char *map_name, void *level, ULONG_PTR validated_vtable,
    ULONGLONG sample_ms)
{
    DlumaGameThreadLevelSnapshot *snapshot =
        &g_dluma.game_thread_level_snapshot;
    LARGE_INTEGER qpc;
    ULONG_PTR live_vtable = 0;
    LONG sequence = dluma_atomic_compare_exchange(
        &snapshot->sequence, 0, 0);
    if (sequence & 1)
        ++sequence;
    if (level && validated_vtable &&
        dluma_is_readable(level, sizeof(live_vtable)))
        memcpy(&live_vtable, level, sizeof(live_vtable));
    if (live_vtable != validated_vtable)
        live_vtable = 0;
    qpc.QuadPart = 0;
    QueryPerformanceCounter(&qpc);
    dluma_atomic_exchange(&snapshot->sequence, sequence + 1);
    snapshot->publisher_thread = (LONG)GetCurrentThreadId();
    snapshot->qpc = qpc.QuadPart > 0 ? (ULONGLONG)qpc.QuadPart : 0;
    snapshot->sample_ms = sample_ms;
    snapshot->level_interface = level;
    snapshot->level_vtable = live_vtable;
    snapshot->query_succeeded =
        map_name && map_name[0] && level && live_vtable;
    snapshot->frontend = map_name &&
        dluma_frontend_level_name_is_frontend(map_name);
    dluma_str_copy(snapshot->normalized_level_name,
                 DLUMA_ARRAY_COUNT(snapshot->normalized_level_name), map_name);
    dluma_atomic_exchange(&snapshot->sequence, sequence + 2);
}

int dluma_read_game_thread_level_snapshot(
    DlumaGameThreadLevelSnapshot *snapshot_out)
{
    unsigned int attempt;
    DlumaGameThreadLevelSnapshot *snapshot =
        &g_dluma.game_thread_level_snapshot;
    if (!snapshot_out) return 0;
    memset(snapshot_out, 0, sizeof(*snapshot_out));
    for (attempt = 0; attempt < 4; ++attempt)
    {
        LONG before = dluma_atomic_compare_exchange(
            &snapshot->sequence, 0, 0);
        LONG after;
        if (before & 1)
            continue;
        snapshot_out->publisher_thread = snapshot->publisher_thread;
        snapshot_out->qpc = snapshot->qpc;
        snapshot_out->sample_ms = snapshot->sample_ms;
        snapshot_out->level_interface = snapshot->level_interface;
        snapshot_out->level_vtable = snapshot->level_vtable;
        snapshot_out->query_succeeded = snapshot->query_succeeded;
        snapshot_out->frontend = snapshot->frontend;
        dluma_str_copy(snapshot_out->normalized_level_name,
                     DLUMA_ARRAY_COUNT(snapshot_out->normalized_level_name),
                     snapshot->normalized_level_name);
        after = dluma_atomic_compare_exchange(
            &snapshot->sequence, 0, 0);
        if (before == after && !(after & 1))
        {
            snapshot_out->sequence = after;
            return after != 0;
        }
    }
    memset(snapshot_out, 0, sizeof(*snapshot_out));
    return 0;
}

int dluma_ui_read_level_snapshot(char *map_out, unsigned int map_capacity,
                               void **level_out, ULONGLONG *sample_ms_out)
{
    DlumaGameThreadLevelSnapshot snapshot;
    if (!map_out || !map_capacity || !level_out || !sample_ms_out)
        return 0;
    map_out[0] = 0;
    *level_out = 0;
    *sample_ms_out = 0;
    if (!dluma_read_game_thread_level_snapshot(&snapshot) ||
        !snapshot.query_succeeded ||
        !snapshot.normalized_level_name[0] || !snapshot.level_interface ||
        !snapshot.sample_ms)
        return 0;
    dluma_str_copy(map_out, map_capacity, snapshot.normalized_level_name);
    *level_out = snapshot.level_interface;
    *sample_ms_out = snapshot.sample_ms;
    return 1;
}

