static DlumaGetUIScreenIdFn dluma_ui_get_screen_lookup(DlumaEngineState *engine)
{
    if (engine && engine->get_ui_screen_id_by_script_name)
        return (DlumaGetUIScreenIdFn)engine->get_ui_screen_id_by_script_name;
    return g_dluma_bridge_get_ui_screen_id;
}

static DlumaRegisterUIScreenFn dluma_ui_get_screen_register(DlumaEngineState *engine)
{
    if (engine && engine->register_ui_screen)
        return (DlumaRegisterUIScreenFn)engine->register_ui_screen;
    return g_dluma_bridge_register_ui_screen;
}

static int dluma_ui_find_screen(DlumaEngineState *engine, void *level,
                              const char *exact_text, const char *base_text)
{
    DlumaGetUIScreenIdFn lookup;
    DlumaTtlString exact_name;
    DlumaTtlString base_name;
    int screen_id;

    lookup = dluma_ui_get_screen_lookup(engine);
    if (!lookup || !level)
        return -1;
    dluma_ttl_string_init(&exact_name, exact_text);
    screen_id = lookup(level, &exact_name);
    if (screen_id >= 0)
        return screen_id;

    /* Some engine paths store the script basename and synthesize the standard
     * data/menu/scr prefix and .xui suffix during lookup. */
    dluma_ttl_string_init(&base_name, base_text);
    return lookup(level, &base_name);
}

/* MainMenuModule stores the RegisterUIScreen result in this exact-build
 * global. The filename lookup is preferred, but the redirect can leave the
 * UI manager's name index keyed differently from the loaded XUI name. Read
 * this value only after matching the current Player PE and its RIP-relative
 * store instruction; no UI object is created or shown by this fallback. */
static int dluma_ui_resolve_devtools_main_menu_screen(
    DlumaEngineState *engine, void *level)
{
    static const BYTE id_store_prefix[6] = {
        0x89, 0x05, 0xAB, 0xD8, 0xAD, 0x00
    };
    HMODULE module;
    BYTE *base;
    BYTE *store;
    BYTE *id_slot;
    LONG relative;
    DWORD timestamp;
    DWORD image_size;
    int screen_id;
    if (!engine || !level)
        return -1;
    module = GetModuleHandleW(L"gamedll_x64_rwdi.dll");
    if (!module || !dluma_ui_get_pe_identity(module, &timestamp, &image_size) ||
        timestamp != DLUMA_DEVTOOLS_GAMEDLL_TIMESTAMP ||
        image_size != DLUMA_DEVTOOLS_GAMEDLL_IMAGE_SIZE ||
        DLUMA_DEVTOOLS_MAIN_MENU_ID_WRITE_RVA > image_size ||
        sizeof(id_store_prefix) >
            image_size - DLUMA_DEVTOOLS_MAIN_MENU_ID_WRITE_RVA ||
        DLUMA_DEVTOOLS_MAIN_MENU_SCREEN_ID_RVA > image_size ||
        sizeof(screen_id) >
            image_size - DLUMA_DEVTOOLS_MAIN_MENU_SCREEN_ID_RVA)
        return -1;
    base = (BYTE *)module;
    store = base + DLUMA_DEVTOOLS_MAIN_MENU_ID_WRITE_RVA;
    if (!dluma_is_readable(store, sizeof(id_store_prefix)) ||
        memcmp(store, id_store_prefix, sizeof(id_store_prefix)) != 0)
        return -1;
    relative = (LONG)dluma_ui_read_u32(store + 2);
    id_slot = store + sizeof(id_store_prefix) + relative;
    if (id_slot != base + DLUMA_DEVTOOLS_MAIN_MENU_SCREEN_ID_RVA ||
        !dluma_is_readable(id_slot, sizeof(screen_id)))
        return -1;
    screen_id = *(const int *)id_slot;
    /* The redirected filename is deliberately absent from the UI manager's
     * script-name index on Player.  MainMenuModule's exact validated slot
     * still contains its RegisterUIScreen result; the caller validates that
     * ID by resolving a MenuMain root with the loader's exact child controls
     * before retaining it.  Requiring
     * IsUIScreenRegistered here was the runtime regression: it returns false
     * for this redirected key even while the real screen is alive. */
    if (screen_id < 0 || screen_id > 0x100000)
        return -1;
    return screen_id;
}

/* The exact-length redirect uses a per-manifest generated name for a selected
 * custom menu.  That prevents the loader PAK's own compatibility XUI from
 * winning an earlier same-path lookup.  Stock and loader names remain useful
 * fallbacks when no custom menu was selected. */
static int dluma_ui_find_main_menu_screen(DlumaEngineState *engine, void *level)
{
    char redirected_stem[DLUMA_CUSTOM_MENU_XUI_NAME_CAPACITY];
    const char *redirected_name = g_dluma_main_menu_redirect_name[0]
        ? g_dluma_main_menu_redirect_name : "DLM_Main_PC_workshop.xui";
    size_t redirected_length;
    int screen_id;
    dluma_str_copy(
        redirected_stem, DLUMA_ARRAY_COUNT(redirected_stem), redirected_name);
    redirected_length = strlen(redirected_stem);
    if (redirected_length > 4U &&
        dluma_stricmp(redirected_stem + redirected_length - 4U, ".xui") == 0)
        redirected_stem[redirected_length - 4U] = 0;
    screen_id = dluma_ui_find_screen(
        engine, level, redirected_name, redirected_stem);
    if (screen_id >= 0)
        return screen_id;
    screen_id = dluma_ui_find_screen(
        engine, level, "DLM_Main_PC_workshop.xui", "DLM_Main_PC_workshop");
    if (screen_id >= 0)
        return screen_id;
    screen_id = dluma_ui_find_screen(
        engine, level, "MenuMain_PC_workshop.xui", "MenuMain_PC_workshop");
    if (screen_id >= 0)
        return screen_id;
    screen_id = dluma_ui_find_screen(
        engine, level, "MenuMain.xui", "MenuMain");
    if (screen_id >= 0)
        return screen_id;
    screen_id = dluma_ui_find_screen(
        engine, level, "data\\menu\\scr\\MenuMain.xui", "MenuMain");
    if (screen_id >= 0)
        return screen_id;
    return dluma_ui_resolve_devtools_main_menu_screen(engine, level);
}

static int dluma_ui_register_mods_screen(DlumaEngineState *engine, void *level)
{
    /* Stock MainMenuModule registers MenuSteamWorkshop.xui by bare filename,
     * not data\menu\scr\....  PressPath performs the same bare-name lookup. */
    static const char script_path_text[] = "MenuDLUMAMods.xui";
    DlumaGetUIScreenIdFn lookup;
    DlumaRegisterUIScreenFn register_screen;
    DlumaTtlString script_path;
    DlumaTtlString empty_skin;
    int screen_id;
    int press_path_id;

    if (!level)
        return -1;
    lookup = dluma_ui_get_screen_lookup(engine);
    register_screen = dluma_ui_get_screen_register(engine);
    if (!lookup || !register_screen)
    {
        dluma_log_line("WARN", "MODS registration bridge is missing the exported ILevel UI functions.");
        return -1;
    }

    screen_id = dluma_ui_find_screen(
        engine, level, "MenuDLUMAMods.xui", "MenuDLUMAMods");
    if (screen_id < 0)
    {
        dluma_ttl_string_init(&script_path, script_path_text);
        dluma_ttl_string_init(&empty_skin, "");
        screen_id = register_screen(
            level,
            &script_path,
            2,
            1,
            0,
            &empty_skin,
            0xFFFFFFFFUL);
        if (screen_id < 0)
        {
            dluma_log_line("WARN", "ILevel::RegisterUIScreen rejected bare MenuDLUMAMods.xui during the B_Mods registration bridge.");
            return -1;
        }
        dluma_log_u64("INFO", "mods_screen_registered_on_demand_id",
                    (ULONGLONG)(unsigned int)screen_id);
        dluma_log_u64("INFO", "mods_screen_registration_layer", 2);
        dluma_log_u64("INFO", "mods_screen_registration_pack_index", 1);
    }
    else
    {
        dluma_log_u64("INFO", "mods_screen_already_registered_id",
                    (ULONGLONG)(unsigned int)screen_id);
    }

    g_dluma_ui_registered_level = level;
    g_dluma_ui_screen_id = screen_id;
    dluma_ttl_string_init(&script_path, "MenuDLUMAMods.xui");
    press_path_id = lookup(level, &script_path);
    if (press_path_id >= 0)
    {
        dluma_log_u64("INFO", "mods_screen_native_presspath_lookup_id",
                    (ULONGLONG)(unsigned int)press_path_id);
    }
    else
    {
        dluma_log_line("WARN", "Bare MenuDLUMAMods.xui registered but PressPath lookup still returned no screen ID.");
    }
    dluma_log_line("INFO", "MenuDLUMAMods.xui uses the exact bare-filename/layer/pack contract of stock MenuSteamWorkshop.xui.");
    return press_path_id;
}

