static int dluma_ui_object_id_equals(void *object, const char *expected)
{
    const DlumaTtlString *id;
    unsigned int expected_length;

    if (!object || !expected || !g_dluma_get_object_id)
        return 0;
    id = g_dluma_get_object_id(object);
    expected_length = (unsigned int)strlen(expected);
    if (!id || !dluma_is_readable(id, sizeof(*id)) ||
        !id->data || id->size != expected_length ||
        !dluma_is_readable(id->data, id->size))
        return 0;
    return memcmp(id->data, expected, expected_length) == 0;
}

static void dluma_ui_log_screen_script(void *ui_screen)
{
    const DlumaTtlString *script_name;
    char text[DLUMA_MAX_TEXT];
    unsigned int i;

    if (!ui_screen || !g_dluma.engine.get_screen_script_name)
        return;
    script_name = (const DlumaTtlString *)
                      g_dluma.engine.get_screen_script_name(ui_screen);
    if (!script_name || !dluma_is_readable(script_name, sizeof(*script_name)) ||
        !script_name->data || script_name->size == 0 ||
        script_name->size >= DLUMA_ARRAY_COUNT(text) ||
        !dluma_is_readable(script_name->data, script_name->size))
    {
        dluma_log_line("WARN", "Loaded MODS screen did not expose a readable XUI script name.");
        return;
    }
    for (i = 0; i < script_name->size; ++i)
        text[i] = script_name->data[i];
    text[script_name->size] = 0;
    dluma_log_pair("INFO", "mods_screen_loaded_script", text);
}

