static int dluma_ui_discord_store_live_frontend_level(void *level)
{
    ULONG_PTR vtable = 0;
    if (!level || !dluma_is_readable(level, sizeof(vtable)))
        return 0;
    __try
    {
        memcpy(&vtable, level, sizeof(vtable));
        if (!vtable ||
            !dluma_is_readable((const void *)vtable, sizeof(void *)))
            return 0;
        g_dluma_discord_live_frontend_level = level;
        g_dluma_discord_live_frontend_vtable = vtable;
        return 1;
    }
    __except (1)
    {
        return 0;
    }
}

static void *dluma_ui_discord_copy_live_frontend_level(void)
{
    void *level = g_dluma_discord_live_frontend_level;
    ULONG_PTR expected_vtable =
        g_dluma_discord_live_frontend_vtable;
    ULONG_PTR live_vtable = 0;
    if (!level || !expected_vtable ||
        !dluma_is_readable(level, sizeof(live_vtable)))
        return 0;
    __try
    {
        memcpy(&live_vtable, level, sizeof(live_vtable));
        if (live_vtable == expected_vtable &&
            dluma_is_readable(
                (const void *)live_vtable, sizeof(void *)))
            return level;
    }
    __except (1)
    {
        live_vtable = 0;
    }
    g_dluma_discord_live_frontend_level = 0;
    g_dluma_discord_live_frontend_vtable = 0;
    return 0;
}

void dluma_ui_note_live_frontend_screen(void *screen)
{
    void *level = 0;
    if (!screen || !g_dluma_get_object_level ||
        g_dluma_ui_stopping || g_dluma.stop_requested)
        return;
    __try
    {
        level = g_dluma_get_object_level(screen);
        (void)dluma_ui_discord_store_live_frontend_level(level);
    }
    __except (1)
    {
        return;
    }
}

static int dluma_ui_discord_owned_screen_visible(
    void *screen, const char *expected_id)
{
    void *level = 0;
    int screen_id = -1;
    if (!screen || !expected_id || !g_dluma_get_object_level ||
        !g_dluma.engine.get_screen_id ||
        !g_dluma.engine.is_ui_screen_visible)
        return 0;
    __try
    {
        if (!dluma_is_readable(screen, sizeof(void *)) ||
            !dluma_ui_object_id_equals(screen, expected_id))
            return 0;
        level = g_dluma_get_object_level(screen);
        screen_id = g_dluma.engine.get_screen_id(screen);
        if (!level || screen_id < 0 ||
            !dluma_is_readable(level, sizeof(void *)) ||
            (g_dluma.engine.is_ui_screen_loaded &&
             !g_dluma.engine.is_ui_screen_loaded(level, screen_id)) ||
            !g_dluma.engine.is_ui_screen_visible(level, screen_id))
            return 0;
        (void)dluma_ui_discord_store_live_frontend_level(level);
        return 1;
    }
    __except (1)
    {
        return 0;
    }
}

static int dluma_ui_discord_script_visible(
    void *level, const char *script_name)
{
    char base_name[128];
    char canonical_name[192];
    static const char canonical_prefix[] = "data\\menu\\scr\\";
    unsigned int length;
    int screen_id;
    if (!level || !script_name ||
        !g_dluma.engine.is_ui_screen_visible)
        return 0;
    length = (unsigned int)strlen(script_name);
    if (!length || length >= DLUMA_ARRAY_COUNT(base_name))
        return 0;
    if (length >= 4U &&
        dluma_stricmp(script_name + length - 4U, ".xui") == 0)
        length -= 4U;
    memcpy(base_name, script_name, length);
    base_name[length] = 0;
    dluma_str_copy(
        canonical_name, DLUMA_ARRAY_COUNT(canonical_name),
        canonical_prefix);
    if (strlen(canonical_name) + strlen(script_name) + 1U >
        DLUMA_ARRAY_COUNT(canonical_name))
        return 0;
    dluma_str_append(
        canonical_name, DLUMA_ARRAY_COUNT(canonical_name),
        script_name);
    __try
    {
        screen_id = dluma_ui_find_screen(
            &g_dluma.engine, level, script_name, base_name);
        if (screen_id < 0)
            screen_id = dluma_ui_find_screen(
                &g_dluma.engine, level, canonical_name, base_name);
        if (screen_id < 0 ||
            (g_dluma.engine.is_ui_screen_loaded &&
             !g_dluma.engine.is_ui_screen_loaded(level, screen_id)))
            return 0;
        return g_dluma.engine.is_ui_screen_visible(
                   level, screen_id) != 0;
    }
    __except (1)
    {
        return 0;
    }
}

static int dluma_ui_discord_any_script_visible(
    void *level, const char *const *screens, unsigned int count)
{
    unsigned int index;
    for (index = 0; index < count; ++index)
        if (dluma_ui_discord_script_visible(level, screens[index]))
            return 1;
    return 0;
}

unsigned int dluma_ui_discord_menu_visibility_snapshot(void)
{
    static const char *const selecting_map[] = {
        "DLM_SteamWorkshop.xui",
        "MenuSteamWorkshop.xui",
        "MenuCustomMap.xui"
    };
    static const char *const configuring_settings[] = {
        "MenuDLUMALoaderSettings.xui",
        "DLUMA_MenuOptions.xui",
        "MenuOptions.xui",
        "MenuOptionsAudio.xui",
        "MenuOptionsControls.xui",
        "MenuOptionsControlsGamepad.xui",
        "MenuOptionsControlsGamepad_Orbis.xui",
        "MenuOptionsControlsKeyboard.xui",
        "MenuOptionsEyeTracking.xui",
        "MenuOptionsGame.xui",
        "MenuOptionsIngame.xui",
        "MenuOptionsOnline.xui",
        "MenuOptionsVideo.xui",
        "MenuOptionsVideoIngame.xui",
        "MenuOptionsVideo_CONSOLE.xui",
        "MenuGamma.xui",
        "MenuDisplayDevice.xui",
        "MenuScreenAdjustment.xui"
    };
    static const char *const credits[] = {
        "MenuCredits.xui",
        "MenuCredits_PC.xui"
    };
    static const char *const statistics[] = {
        "MenuPersonalStatistics.xui"
    };
    void *level;
    unsigned int visibility = 0;

    if (dluma_ui_discord_owned_screen_visible(
            g_dluma_workshop_menu_screen, "MenuSteamWorkshop"))
        visibility |= DLUMA_UI_MENU_VISIBLE_SELECTING_MAP;
    if (dluma_ui_discord_owned_screen_visible(
            g_dluma_ui_settings_screen, "MenuDLUMALoaderSettings"))
        visibility |= DLUMA_UI_MENU_VISIBLE_SETTINGS;
    if (dluma_ui_discord_owned_screen_visible(
            g_dluma_ui_registry_screen, "MenuDLUMAMods") ||
        dluma_ui_discord_owned_screen_visible(
            g_dluma_ui_mod_details_screen, "MenuDLUMAModDetails") ||
        dluma_ui_discord_owned_screen_visible(
            g_dluma_ui_mod_config_screen, "MenuDLUMAModConfig") ||
        dluma_ui_discord_owned_screen_visible(
            g_dluma_ui_custom_menu_screen,
            "MenuDLUMACustomMainMenu"))
        visibility |= DLUMA_UI_MENU_VISIBLE_MODS;

    level = dluma_ui_discord_copy_live_frontend_level();
    if (dluma_ui_discord_any_script_visible(
            level, selecting_map, DLUMA_ARRAY_COUNT(selecting_map)))
        visibility |= DLUMA_UI_MENU_VISIBLE_SELECTING_MAP;
    if (dluma_ui_discord_any_script_visible(
            level, configuring_settings,
            DLUMA_ARRAY_COUNT(configuring_settings)))
        visibility |= DLUMA_UI_MENU_VISIBLE_SETTINGS;
    if (dluma_ui_discord_any_script_visible(
            level, credits, DLUMA_ARRAY_COUNT(credits)))
        visibility |= DLUMA_UI_MENU_VISIBLE_CREDITS;
    if (dluma_ui_discord_any_script_visible(
            level, statistics, DLUMA_ARRAY_COUNT(statistics)))
        visibility |= DLUMA_UI_MENU_VISIBLE_STATISTICS;
    return visibility;
}

static int dluma_ui_is_quest_log_screen(void *screen)
{
    (void)screen;
    return 0;
}

/* MenuDLUMAQuestLog reuses the exact MenuSteamWorkshop controller contract, but
 * it must not merely trust its loader-owned root ID.  The main-menu calls
 * below are only safe for the same exact controller/vtable identity validated
 * by the established MODS route. */
static int dluma_ui_is_validated_quest_log_screen(void *screen)
{
    DWORD vtable_rva = 0;
    int screen_id;

    if (!dluma_ui_is_quest_log_screen(screen))
        return 0;
    if (!dluma_ui_is_expected_workshop_controller(screen, &vtable_rva))
    {
        if (dluma_atomic_compare_exchange(
                &g_dluma_quest_log_controller_failure_logged, 1, 0) == 0)
        {
            dluma_log_hex("WARN", "quest_log_unexpected_controller_vtable_rva",
                        vtable_rva);
            dluma_log_line("WARN", "MenuDLUMAQuestLog did not instantiate the validated MenuSteamWorkshop controller; the page remains inert.");
        }
        return 0;
    }
    if (g_dluma_quest_log_screen_id >= 0 && g_dluma.engine.get_screen_id)
    {
        screen_id = g_dluma.engine.get_screen_id(screen);
        if (screen_id != g_dluma_quest_log_screen_id)
        {
            if (dluma_atomic_compare_exchange(
                    &g_dluma_quest_log_controller_failure_logged, 1, 0) == 0)
            {
                dluma_log_u64("WARN", "quest_log_controller_screen_id_mismatch",
                            (ULONGLONG)(unsigned int)screen_id);
                dluma_log_line("WARN", "MenuDLUMAQuestLog controller screen ID did not match its registered PressPath screen; the page remains inert.");
            }
            return 0;
        }
    }
    return 1;
}

