static void dluma_ui_make_mutation_request(
    DlumaGlobalMutationRequest *request,
    const DlumaLuaMetadata *item,
    ULONGLONG revision)
{
    if (!request)
        return;
    memset(request, 0, sizeof(*request));
    if (!item)
        return;
    dluma_str_copy(request->registry_key,
                 DLUMA_ARRAY_COUNT(request->registry_key),
                 item->registry_key);
    dluma_str_copy(request->metadata_fingerprint,
                 DLUMA_ARRAY_COUNT(request->metadata_fingerprint),
                 item->metadata_fingerprint);
    request->registry_revision = revision;
}

static const char *dluma_ui_review_state_text(const DlumaLuaMetadata *item)
{
    if (!item)
        return "UNAVAILABLE";
    switch ((DlumaGlobalReviewState)item->review_state)
    {
    case DLUMA_GLOBAL_REVIEW_NEW:
        return "NEW - REVIEW REQUIRED";
    case DLUMA_GLOBAL_REVIEW_SEEN:
        return "SEEN - APPROVAL REQUIRED";
    case DLUMA_GLOBAL_REVIEW_APPROVED_DISABLED:
        return "APPROVED - DISABLED";
    case DLUMA_GLOBAL_REVIEW_APPROVED_ENABLED:
        return "APPROVED - ENABLED";
    case DLUMA_GLOBAL_REVIEW_CHANGED_REVIEW_REQUIRED:
        return "CHANGED - REVIEW REQUIRED";
    case DLUMA_GLOBAL_REVIEW_CONFLICT:
        return "CONFLICT";
    default:
        return "INVALID";
    }
}

static void dluma_ui_runtime_state_text(
    const DlumaLuaMetadata *item,
    char *out,
    unsigned int capacity)
{
    const char *key = "DLUMA_Common_Unknown";
    const char *fallback = "UNKNOWN";
    if (!out || !capacity) return;
    if (!item) {
        dluma_ui_localize_text(
            key, fallback, out, capacity);
        return;
    }
    if (item->runtime_transition == DLUMA_GLOBAL_TRANSITION_ENABLING)
    {
        key = "DLUMA_Mods_Status_Enabling";
        fallback = "ENABLING MOD...";
    }
    else if (item->runtime_transition ==
             DLUMA_GLOBAL_TRANSITION_DISABLING)
    {
        key = "DLUMA_Mods_Status_Disabling";
        fallback = "DISABLING MOD...";
    }
    else if (item->runtime_transition ==
             DLUMA_GLOBAL_TRANSITION_ERROR)
    {
        key = "DLUMA_Mods_State_LoadError";
        fallback = "RUNTIME ERROR";
    }
    else if (item->loaded)
    {
        key = "DLUMA_Mods_State_Loaded";
        fallback = "LOADED";
    }
    else
    {
        key = "DLUMA_Common_NotLoaded";
        fallback = "NOT LOADED";
    }
    dluma_ui_localize_text(
        key, fallback, out, capacity);
}

static int dluma_ui_list_get_selection(void *list)
{
    if (!list || !g_dluma_list_get_selection)
        return -1;
    return g_dluma_list_get_selection((BYTE *)list + DLUMA_UI_LIST_INTERFACE_OFFSET);
}

static int dluma_ui_list_get_focused_index(void *list)
{
    int focused;
    if (!list ||
        !dluma_is_readable((BYTE *)list + DLUMA_UI_LIST_FOCUSED_INDEX_OFFSET,
                         sizeof(focused)))
        return -1;
    /* Exact DevTools UIListBox layout: the secondary IUIList interface begins
     * at +0x58, GetSelection reads interface +0x38 (root +0x90), and the
     * adjacent focused index used by OnFocusSetChild is root +0x94. Mouse
     * hover changes this focused index without changing selection. */
    focused = *(volatile int *)((BYTE *)list +
                                DLUMA_UI_LIST_FOCUSED_INDEX_OFFSET);
    return focused >= -1 ? focused : -1;
}

static void dluma_ui_list_set_selection(void *list, int index)
{
    if (!list || index < 0 || !g_dluma_list_set_selection)
        return;
    /* IUIList::SetSelection belongs to the secondary list interface at +0x58.
     * The similarly shaped UIListBox routine at 0x011239E0 only adjusts
     * indices after insertion/removal; calling it for pointer input made
     * selection move in one direction and then become stuck. */
    g_dluma_list_set_selection(
        (BYTE *)list + DLUMA_UI_LIST_INTERFACE_OFFSET, index, 1);
}

static void *dluma_ui_list_get_selected_item(void *list)
{
    if (!list || !g_dluma_list_get_selected_item)
        return 0;
    return g_dluma_list_get_selected_item(
        (BYTE *)list + DLUMA_UI_LIST_INTERFACE_OFFSET);
}

static const char *dluma_ui_registry_key_for_item(void *item)
{
    unsigned int i;
    if (!item)
        return 0;
    for (i = 0; i < g_dluma_ui_registry_row_count; ++i)
    {
        if (g_dluma_ui_registry_rows[i].item == item)
            return g_dluma_ui_registry_rows[i].registry_key;
    }
    return 0;
}

static int dluma_ui_registry_native_index_for_item(void *item)
{
    unsigned int i;
    if (!item)
        return -1;
    /* IUIList::SetSelection consumes the direct returned-item index. */
    for (i = 0; i < g_dluma_ui_registry_row_count; ++i)
    {
        if (g_dluma_ui_registry_rows[i].item == item)
            return g_dluma_ui_registry_rows[i].list_index;
    }
    return -1;
}

static int dluma_ui_registry_select_pointer_item(void *item,
                                               const char *input_path)
{
    const char *clicked_id;
    int native_index;
    clicked_id = dluma_ui_registry_key_for_item(item);
    native_index = dluma_ui_registry_native_index_for_item(item);
    if (!clicked_id || native_index < 0)
        return 0;
    dluma_str_copy(g_dluma_ui_registry_selected_id,
                 DLUMA_ARRAY_COUNT(g_dluma_ui_registry_selected_id),
                 clicked_id);
    dluma_ui_list_set_selection(g_dluma_ui_registry_list, native_index);
    dluma_ui_registry_update_button_labels();
    dluma_log_pair("INFO", "global_mod_registry_mouse_selected_id",
                 clicked_id);
    dluma_log_pair("INFO", "global_mod_registry_mouse_input_path",
                 input_path ? input_path : "unknown");
    return 1;
}

static const char *dluma_ui_registry_current_selected_id(void)
{
    int selection = dluma_ui_list_get_selection(g_dluma_ui_registry_list);
    unsigned int i;
    if (selection < 0) return 0;
    /* GetSelectedItem is not stable for this external HTML row template.
     * The native selection index and returned-item mapping are direct. */
    /* g_dluma_ui_registry_rows[(unsigned int)selection].registry_key is valid
     * only for the old no-divider list. DLL/LUA headings require the explicit
     * list_index lookup below so direct native selection remains correct. */
    (void)dluma_ui_list_get_selected_item(g_dluma_ui_registry_list);
    for (i = 0; i < g_dluma_ui_registry_row_count; ++i)
        if (g_dluma_ui_registry_rows[i].list_index == selection)
            return g_dluma_ui_registry_rows[i].registry_key;
    return 0;
}

static DlumaRegistryRowMap *dluma_ui_registry_current_row(void)
{
    int selection = dluma_ui_list_get_selection(g_dluma_ui_registry_list);
    unsigned int i;
    if (selection < 0) return 0;
    for (i = 0; i < g_dluma_ui_registry_row_count; ++i)
        if (g_dluma_ui_registry_rows[i].list_index == selection)
            return &g_dluma_ui_registry_rows[i];
    return 0;
}

static int dluma_ui_registry_find_metadata(const char *registry_key)
{
    unsigned int i;
    if (!registry_key || !registry_key[0])
        return -1;
    for (i = 0; i < g_dluma_ui_global_mod_count; ++i)
    {
        if (dluma_stricmp(g_dluma_ui_global_mods[i].registry_key,
                        registry_key) == 0)
            return (int)i;
    }
    return -1;
}

static int dluma_ui_registry_find_native_metadata(const char *registry_key)
{
    unsigned int i;
    if (!registry_key || !registry_key[0]) return -1;
    for (i = 0; i < g_dluma_ui_native_mod_count; ++i)
        if (dluma_stricmp(g_dluma_ui_native_mods[i].registry_key,
                        registry_key) == 0)
            return (int)i;
    return -1;
}

static int dluma_ui_registry_find_managed_metadata(const char *registry_key)
{
    unsigned int i;
    if (!registry_key || !registry_key[0]) return -1;
    for (i = 0; i < g_dluma_ui_managed_mod_count; ++i)
        if (dluma_stricmp(g_dluma_ui_managed_mods[i].registry_key,
                        registry_key) == 0)
            return (int)i;
    return -1;
}

static void dluma_ui_html_append_escaped(char *out, unsigned int capacity,
                                       const char *text, const char *field_name)
{
    char one[2];
    unsigned int i;
    unsigned int length;
    one[1] = 0;
    length = text ? (unsigned int)strlen(text) : 0;
    if (length > DLUMA_UI_REGISTRY_FIELD_TEXT_LIMIT)
    {
        dluma_log_pair("WARN", "global_mod_registry_text_truncated",
                     field_name ? field_name : "metadata");
        length = DLUMA_UI_REGISTRY_FIELD_TEXT_LIMIT;
    }
    for (i = 0; text && i < length; ++i)
    {
        switch (text[i])
        {
        case '&':
            dluma_str_append(out, capacity, "&amp;");
            break;
        case '<':
            dluma_str_append(out, capacity, "&lt;");
            break;
        case '>':
            dluma_str_append(out, capacity, "&gt;");
            break;
        case '"':
            dluma_str_append(out, capacity, "&quot;");
            break;
        default:
            one[0] = text[i];
            dluma_str_append(out, capacity, one);
            break;
        }
    }
}

static int dluma_ui_settings_read_value(
    unsigned int setting_index, char *out, unsigned int capacity);

static void *dluma_ui_settings_add_row(
    void *list, const char *label, const char *value)
{
    static const char option_template_text[] = "OptionTextDummy";
    WCHAR row_storage[DLUMA_UI_WIDE_ROW_CAPACITY];
    DlumaTtlWideString row_text;
    DlumaTtlString option_template;
    void *item;

    if (!list || !label || !value || !g_dluma_list_add_item)
        return 0;
    if (!dluma_ttl_wide_string_init_utf8(
            &row_text, row_storage, DLUMA_ARRAY_COUNT(row_storage), label))
    {
        dluma_log_line("WARN", "loader_settings_row_text_conversion_failed");
        return 0;
    }
    dluma_ttl_string_init(&option_template, option_template_text);
    /* ListBoxOptionsV exposes OptionTextDummy specifically for two-column
     * option rows. Its OptionTextSelectSimpleV presenter shows association 1
     * in both Normal and Focus; ButtonDummy hides that value until Focus and
     * supplies the incorrect red/white generic-button highlight. */
    item = g_dluma_list_add_item(
        list, &row_text, 0, &option_template, 1, -1);
    if (item)
    {
        dluma_ui_set_element_text_association(item, value, 1);
        if (g_dluma_set_element_can_focus)
            g_dluma_set_element_can_focus(item, 1);
    }
    else
    {
        dluma_log_line("WARN", "loader_settings_option_row_add_failed");
    }
    return item;
}

static void *dluma_ui_mod_details_add_label_row(
    void *list, const char *label)
{
    static const char option_template_text[] = "OptionTextDummy";
    WCHAR row_storage[DLUMA_UI_WIDE_ROW_CAPACITY];
    DlumaTtlWideString row_text;
    DlumaTtlString option_template;
    void *item;
    void *value_wrap;

    if (!list || !label || !g_dluma_list_add_item)
        return 0;
    if (!dluma_ttl_wide_string_init_utf8(
            &row_text, row_storage, DLUMA_ARRAY_COUNT(row_storage), label))
    {
        dluma_log_line("WARN", "mod_details_row_text_conversion_failed");
        return 0;
    }
    /*
     * OptionTextDummy is the only ListBoxOptionsV template that binds the
     * supplied row text to the native left-hand label in every focus state.
     * Hide its complete value wrap rather than leaving a zero-option selector
     * or using ButtonDummy: ButtonDummy exposes the stock presenter's literal
     * OPTIONTEXTSELECTSIMPLEV placeholder when focused.  The native focus
     * triangle remains outside the hidden wrap and Details values live only
     * in the right-hand pane.
     */
    dluma_ttl_string_init(&option_template, option_template_text);
    item = g_dluma_list_add_item(
        list, &row_text, 0, &option_template, 1, -1);
    value_wrap = item
        ? dluma_ui_find_required_child(item, "wrap")
        : 0;
    if (value_wrap)
        dluma_ui_set_element_visible(value_wrap, 0);
    else if (item)
        dluma_log_line("WARN", "mod_details_label_row_wrap_missing");
    if (item && g_dluma_set_element_can_focus)
        g_dluma_set_element_can_focus(item, 1);
    else if (!item)
        dluma_log_line("WARN", "mod_details_label_row_add_failed");
    return item;
}

static int dluma_ui_settings_add_native_option(
    void *option_control, const char *value)
{
    WCHAR storage[DLUMA_UI_WIDE_LABEL_CAPACITY];
    DlumaTtlWideString text;
    if (!option_control || !value || !g_dluma_option_add_explicit)
        return 0;
    if (!dluma_ttl_wide_string_init_utf8(
            &text, storage, DLUMA_ARRAY_COUNT(storage), value))
        return 0;
    /* UIOptionTextSelect copies the explicit wide string into its own
     * OptionSelectOptionInfo, so the stack-backed ttl string is call-scoped. */
    return g_dluma_option_add_explicit(option_control, &text, 0) != 0;
}

static int dluma_ui_settings_seed_native_options(
    void *option_control, unsigned int setting_index)
{
    const DlumaLoaderSettingDefinition *definition;
    char value[64];
    char number[64];
    unsigned int current;
    unsigned int previous;
    unsigned int next;
    int baseline = -1;

    if (!option_control ||
        setting_index >= DLUMA_ARRAY_COUNT(g_dluma_loader_settings) ||
        !g_dluma_option_add_explicit || !g_dluma_option_set_selection)
        return -1;
    definition = &g_dluma_loader_settings[setting_index];
    if (definition->kind == DLUMA_LOADER_SETTING_TEXT)
        return -1;
    value[0] = 0;
    (void)dluma_ui_settings_read_value(
        setting_index, value, DLUMA_ARRAY_COUNT(value));
    current = dluma_parse_u32(value, definition->minimum);
    if (current < definition->minimum)
        current = definition->minimum;
    if (current > definition->maximum)
        current = definition->maximum;

    if (definition->kind == DLUMA_LOADER_SETTING_BOOL)
    {
        if (!dluma_ui_settings_add_native_option(option_control, "OFF") ||
            !dluma_ui_settings_add_native_option(option_control, "ON"))
            return -1;
        baseline = current ? 1 : 0;
    }
    else
    {
        /* A bounded three-value window gives the native control enough state
         * to color and enable each direction without allocating thousands of
         * entries for large integer ranges. */
        if (current > definition->minimum)
        {
            previous = current - definition->minimum < definition->step
                           ? definition->minimum
                           : current - definition->step;
            dluma_u64_to_text(previous, number, DLUMA_ARRAY_COUNT(number));
            if (!dluma_ui_settings_add_native_option(option_control, number))
                return -1;
            ++baseline;
        }
        dluma_u64_to_text(current, number, DLUMA_ARRAY_COUNT(number));
        if (!dluma_ui_settings_add_native_option(option_control, number))
            return -1;
        ++baseline;
        if (current < definition->maximum)
        {
            next = definition->maximum - current < definition->step
                       ? definition->maximum
                       : current + definition->step;
            dluma_u64_to_text(next, number, DLUMA_ARRAY_COUNT(number));
            if (!dluma_ui_settings_add_native_option(option_control, number))
                return -1;
        }
    }
    g_dluma_option_set_selection(option_control, baseline, 0);
    return baseline;
}

static void dluma_ui_registry_fixed_status(
    const DlumaLuaMetadata *lua,
    const DlumaNativeModSnapshot *native,
    const DlumaManagedModSnapshot *managed,
    char *out,
    unsigned int capacity)
{
    const char *key = "DLUMA_Mods_State_Incompatible";
    const char *fallback = "INVALID";
    if (lua)
    {
        if (!lua->source_selected)
        {
            key = "DLUMA_Mods_SourceRequired";
            fallback = "SOURCE REQUIRED";
        }
        else if (lua->duplicate_id)
        {
            key = "DLUMA_Mods_State_Conflict";
            fallback = "CONFLICT";
        }
        else if (dluma_lua_permission_is_unsupported(lua))
        {
            key = "DLUMA_Mods_State_Incompatible";
            fallback = "UNSUPPORTED";
        }
    }
    else if (native)
    {
        if (!native->source_selected)
        {
            key = "DLUMA_Mods_SourceRequired";
            fallback = "SOURCE REQUIRED";
        }
        else if (native->duplicate_id)
        {
            key = "DLUMA_Mods_State_Conflict";
            fallback = "CONFLICT";
        }
        else
        {
            key = "DLUMA_Mods_State_Incompatible";
            fallback = "INCOMPATIBLE";
        }
    }
    else if (managed)
    {
        if (!managed->source_selected)
        {
            key = "DLUMA_Mods_SourceRequired";
            fallback = "SOURCE REQUIRED";
        }
        else if (managed->duplicate_id)
        {
            key = "DLUMA_Mods_State_Conflict";
            fallback = "CONFLICT";
        }
        else
        {
            key = "DLUMA_Mods_State_Incompatible";
            fallback = "INCOMPATIBLE";
        }
    }
    dluma_ui_localize_text(key, fallback, out, capacity);
}

static void dluma_ui_mod_config_diagnostic_text(
    const char *diagnostic,
    char *out,
    unsigned int capacity)
{
    const char *key = "DLUMA_ModConfig_SchemaInvalid";
    const char *fallback =
        "THIS MOD'S CONFIGURATION SCHEMA IS INVALID.";
    if (!out || !capacity)
        return;
    if (diagnostic &&
        dluma_stricmp(diagnostic, "unsupported_schema_version") == 0)
    {
        key = "DLUMA_ModConfig_UnsupportedVersion";
        fallback =
            "THIS MOD USES AN UNSUPPORTED CONFIGURATION SCHEMA VERSION.";
    }
    else if (diagnostic &&
             dluma_stricmp(diagnostic, "unsupported_scope") == 0)
    {
        key = "DLUMA_ModConfig_GlobalOnly";
        fallback =
            "CONFIGURATION IS AVAILABLE ONLY FOR GLOBAL LUA MODS.";
    }
    else if (diagnostic &&
             dluma_stricmp(diagnostic, "dynamic_or_malformed") == 0)
    {
        key = "DLUMA_ModConfig_StaticOnly";
        fallback =
            "CONFIGURATION MUST USE A STATIC LITERAL SCHEMA.";
    }
    else if (diagnostic &&
             dluma_stricmp(diagnostic, "schema_limits") == 0)
    {
        key = "DLUMA_ModConfig_SchemaLimits";
        fallback =
            "THIS MOD'S CONFIGURATION EXCEEDS THE SUPPORTED LIMITS.";
    }
    else if (diagnostic &&
             dluma_stricmp(diagnostic, "duplicate_identifier") == 0)
    {
        key = "DLUMA_ModConfig_DuplicateIdentifier";
        fallback =
            "THIS MOD'S CONFIGURATION HAS A DUPLICATE ID OR KEY.";
    }
    dluma_ui_localize_text(key, fallback, out, capacity);
}

static int dluma_ui_native_host_abi_compatible(
    const DlumaNativeModSnapshot *item)
{
    if (!item || !item->pe_machine_valid || !item->pe_dll_valid ||
        !item->declared_host_flags)
        return 0;
    if ((item->declared_host_flags & DLUMA_NATIVE_HOST_PLAYER) &&
        item->abi_kind != DLUMA_NATIVE_ABI_V2)
        return 0;
    if ((item->declared_host_flags & DLUMA_NATIVE_HOST_EDITOR) &&
        !item->editor_abi_available)
        return 0;
    return 1;
}

static int dluma_ui_native_hosts_approved(
    const DlumaNativeModSnapshot *item, unsigned int host_flags)
{
    if (!item || host_flags > DLUMA_NATIVE_HOST_BOTH ||
        (host_flags & ~item->declared_host_flags))
        return 0;
    if ((host_flags & DLUMA_NATIVE_HOST_PLAYER) &&
        !item->player_approval_valid)
        return 0;
    if ((host_flags & DLUMA_NATIVE_HOST_EDITOR) &&
        !item->editor_approval_valid)
        return 0;
    return 1;
}

static void dluma_ui_registry_type_text(
    unsigned int kind, int stock_menu,
    char *out, unsigned int capacity)
{
    const char *key = "DLUMA_Mods_Type_Lua";
    const char *fallback = "LUA MOD";
    if (kind == DLUMA_REGISTRY_ROW_KIND_NATIVE)
    {
        key = "DLUMA_Mods_Type_Dll";
        fallback = "DLL MOD";
    }
    else if (kind == DLUMA_REGISTRY_ROW_KIND_MANAGED)
    {
        key = "DLUMA_Mods_Type_CSharp";
        fallback = "C# MOD";
    }
    else if (kind == DLUMA_REGISTRY_ROW_KIND_ASSET)
    {
        key = stock_menu
            ? "DLUMA_Mods_Type_BuiltInMenu"
            : "DLUMA_Mods_Type_Menu";
        fallback = stock_menu ? "BUILT-IN MENU" : "MENU MOD";
    }
    dluma_ui_localize_text(key, fallback, out, capacity);
}

static void dluma_ui_registry_source_text(
    int workshop, int stock, int has_local, int has_steam,
    char *out, unsigned int capacity)
{
    const char *key;
    const char *fallback;
    if (stock)
    {
        key = "DLUMA_Mods_Source_BuiltIn";
        fallback = "BUILT-IN";
    }
    else if (workshop && has_local)
    {
        key = "DLUMA_Mods_Source_SteamLocalAvailable";
        fallback = "STEAM (LOCAL AVAILABLE)";
    }
    else if (!workshop && has_steam)
    {
        key = "DLUMA_Mods_Source_LocalSteamAvailable";
        fallback = "LOCAL (STEAM AVAILABLE)";
    }
    else if (workshop)
    {
        key = "DLUMA_Mods_Source_Steam";
        fallback = "STEAM";
    }
    else
    {
        key = "DLUMA_Mods_Source_Local";
        fallback = "LOCAL";
    }
    dluma_ui_localize_text(key, fallback, out, capacity);
}

