static void dluma_ui_mod_details_source_label(
    int subscribed, const char* name, const char* workshop_id,
    char* output, unsigned int capacity)
{
    char origin[64];
    char unbounded[320];
    WCHAR wide[320];
    unsigned int length = 0;
    unsigned int keep;
    if (!output || !capacity) return;
    output[0] = 0;
    dluma_ui_mod_details_localized(
        subscribed ? "DLUMA_Common_Workshop" : "DLUMA_Common_Local",
        subscribed ? "WORKSHOP" : "LOCAL",
        origin, DLUMA_ARRAY_COUNT(origin));
    dluma_str_copy(unbounded, DLUMA_ARRAY_COUNT(unbounded), origin);
    dluma_str_append(unbounded, DLUMA_ARRAY_COUNT(unbounded), " - ");
    dluma_str_append(unbounded, DLUMA_ARRAY_COUNT(unbounded),
                   name && name[0] ? name : "Unnamed project");
    if (subscribed && workshop_id && workshop_id[0]) {
        dluma_str_append(unbounded, DLUMA_ARRAY_COUNT(unbounded), " (");
        dluma_str_append(unbounded, DLUMA_ARRAY_COUNT(unbounded), workshop_id);
        dluma_str_append(unbounded, DLUMA_ARRAY_COUNT(unbounded), ")");
    }
    if (!dluma_utf8_to_wide(unbounded, wide, DLUMA_ARRAY_COUNT(wide))) {
        dluma_str_copy(output, capacity, origin);
        return;
    }
    while (wide[length]) ++length;
    if (length <= DLUMA_UI_SOURCE_OPTION_CODE_UNIT_LIMIT) {
        dluma_str_copy(output, capacity, unbounded);
        return;
    }
    keep = DLUMA_UI_SOURCE_OPTION_CODE_UNIT_LIMIT - 3U;
    if (keep && wide[keep - 1U] >= 0xD800U &&
        wide[keep - 1U] <= 0xDBFFU)
        --keep;
    wide[keep++] = L'.';
    wide[keep++] = L'.';
    wide[keep++] = L'.';
    wide[keep] = 0;
    if (!dluma_wide_to_utf8(wide, output, capacity)) {
        dluma_str_copy(output, capacity, origin);
    }
}

static void dluma_ui_mod_details_update_for_row(unsigned int row_index);

static int dluma_ui_mod_details_add_source_row(
    int subscribed, const char *name, const char *workshop_id,
    const char *source_identity, int selected)
{
    DlumaModDetailsRowMap *row;
    void *item;
    char label[DLUMA_UI_WIDE_ROW_CAPACITY];
    char state[96];
    char hint[DLUMA_UI_WIDE_ROW_CAPACITY];

    if (!g_dluma_ui_mod_details_list || !source_identity ||
        !source_identity[0] ||
        g_dluma_ui_mod_details_row_count >=
            DLUMA_UI_MOD_DETAILS_VISIBLE_ROWS)
        return 0;

    dluma_ui_mod_details_source_label(
        subscribed, name, workshop_id,
        label, DLUMA_ARRAY_COUNT(label));
    item = dluma_ui_mod_details_add_label_row(
        g_dluma_ui_mod_details_list, label);
    if (!item)
        return 0;

    row = &g_dluma_ui_mod_details_rows[
        g_dluma_ui_mod_details_row_count];
    memset(row, 0, sizeof(*row));
    row->item = item;
    row->list_index = (int)g_dluma_ui_mod_details_row_count;
    row->source_picker = 1;
    row->source_selected = (unsigned char)(selected != 0);
    dluma_str_copy(
        row->source_identity,
        DLUMA_ARRAY_COUNT(row->source_identity), source_identity);
    dluma_str_copy(row->label, DLUMA_ARRAY_COUNT(row->label), label);
    dluma_ui_mod_details_localized(
        selected ? "DLUMA_Common_Selected" : "DLUMA_Common_Select",
        selected ? "SELECTED" : "SELECT",
        state, DLUMA_ARRAY_COUNT(state));
    dluma_ui_mod_details_localized(
        "DLUMA_ModDetails_SourceHint",
        "CHOOSE WHICH LOCAL OR WORKSHOP COPY PROVIDES THIS MOD.",
        hint, DLUMA_ARRAY_COUNT(hint));
    dluma_str_copy(row->value, DLUMA_ARRAY_COUNT(row->value), state);
    dluma_str_append(row->value, DLUMA_ARRAY_COUNT(row->value), "\n\n");
    dluma_str_append(row->value, DLUMA_ARRAY_COUNT(row->value), hint);
    ++g_dluma_ui_mod_details_row_count;
    return 1;
}

static void dluma_ui_mod_details_add_source(void)
{
    unsigned int index;
    int selection_missing = 0;
    const char* id;
    if (!g_dluma_ui_mod_details_list) return;
    if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_ASSET &&
        g_dluma_ui_mod_details_asset_row.asset_kind == DLUMA_ASSET_MOD_KIND_OVERRIDE)
    {
        const DlumaAssetModSnapshot *asset = &g_dluma_ui_mod_details_asset;
        if (asset->has_local && asset->local_source_identity[0])
            (void)dluma_ui_mod_details_add_source_row(0, "Local", "",
                asset->local_source_identity,
                dluma_stricmp(asset->source_identity, asset->local_source_identity) == 0);
        if (asset->has_steam && asset->steam_source_identity[0])
            (void)dluma_ui_mod_details_add_source_row(1, "Steam Workshop", "",
                asset->steam_source_identity,
                dluma_stricmp(asset->source_identity, asset->steam_source_identity) == 0);
        return;
    }
    if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_ASSET)
    {
        const DlumaRegistryRowMap *row =
            &g_dluma_ui_mod_details_asset_row;
        const DlumaCustomMainMenuCandidateSnapshot *item =
            &g_dluma_ui_mod_details_menu;
        char providers[128];
        char project_root[DLUMA_MAX_WPATH * 2];
        project_root[0] = 0;
        if (row->source_has_local && row->source_has_steam)
            dluma_str_copy(
                providers, DLUMA_ARRAY_COUNT(providers),
                "Local and Steam copies available");
        else
            dluma_str_copy(
                providers, DLUMA_ARRAY_COUNT(providers),
                row->display_source);
        if (!row->menu_stock &&
            !dluma_wide_to_utf8(
                item->project_root, project_root,
                DLUMA_ARRAY_COUNT(project_root)))
            dluma_str_copy(
                project_root, DLUMA_ARRAY_COUNT(project_root),
                "Path conversion failed");
        (void)dluma_ui_mod_details_add_field(
            "DLUMA_Common_Source", "EFFECTIVE SOURCE",
            row->display_source);
        (void)dluma_ui_mod_details_add_field(
            "DLUMA_Common_Available", "AVAILABLE PROVIDERS",
            providers);
        (void)dluma_ui_mod_details_add_field(
            "DLUMA_Common_Name", "SOURCE PROJECT",
            row->menu_stock ? "Dying Light" : item->source_name);
        (void)dluma_ui_mod_details_add_field(
            "DLUMA_Common_ID", "SOURCE IDENTITY",
            row->menu_stock ? "built-in" : item->source_identity);
        (void)dluma_ui_mod_details_add_field(
            "DLUMA_Workshop_WorkshopID", "WORKSHOP ID",
            row->menu_stock ? "" : item->workshop_id);
        (void)dluma_ui_mod_details_add_field_kind(
            "DLUMA_Common_FilePath", "PROJECT ROOT", project_root,
            DLUMA_MOD_DETAILS_VALUE_PATH, 0);
        return;
    }
    if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_NATIVE) {
        id = g_dluma_ui_mod_details_native.id;
        selection_missing =
            g_dluma_ui_mod_details_native.source_selection_missing != 0 ||
            !g_dluma_ui_mod_details_native.source_selected;
    } else if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_MANAGED) {
        id = g_dluma_ui_mod_details_managed.id;
        selection_missing =
            g_dluma_ui_mod_details_managed.source_selection_missing != 0 ||
            !g_dluma_ui_mod_details_managed.source_selected;
    } else {
        id = g_dluma_ui_mod_details_lua.id;
        selection_missing =
            g_dluma_ui_mod_details_lua.source_selection_missing != 0 ||
            !g_dluma_ui_mod_details_lua.source_selected;
    }
    if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_NATIVE) {
        for (index = 0; index < g_dluma_ui_native_mod_count;
             ++index) {
            DlumaNativeModSnapshot* source = &g_dluma_ui_native_mods[index];
            if (dluma_stricmp(source->id, id) != 0 ||
                source->duplicate_id)
                continue;
            (void)dluma_ui_mod_details_add_source_row(
                source->source_is_subscribed, source->source_name,
                source->workshop_id, source->source_identity,
                source->source_selected);
        }
    } else if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_MANAGED) {
        for (index = 0; index < g_dluma_ui_managed_mod_count;
             ++index) {
            DlumaManagedModSnapshot* source = &g_dluma_ui_managed_mods[index];
            if (dluma_stricmp(source->id, id) != 0 ||
                source->duplicate_id)
                continue;
            (void)dluma_ui_mod_details_add_source_row(
                source->source_is_subscribed, source->source_name,
                source->workshop_id, source->source_identity,
                source->source_selected);
        }
    } else {
        for (index = 0; index < g_dluma_ui_global_mod_count;
             ++index) {
            DlumaLuaMetadata* source = &g_dluma_ui_global_mods[index];
            /* An invalid copy is still a resolvable alternative. Only a
             * physically ambiguous provider stays out of the picker. */
            if (dluma_stricmp(source->id, id) != 0 ||
                source->duplicate_id)
                continue;
            (void)dluma_ui_mod_details_add_source_row(
                source->source_is_subscribed, source->source_name,
                source->workshop_id, source->source_identity,
                source->source_selected);
        }
    }
    if (!g_dluma_ui_mod_details_row_count) {
        char missing[DLUMA_UI_WIDE_ROW_CAPACITY];
        /* Every remaining copy is a same-source conflict. Saying "open
         * details and choose a source" here would send the player back to
         * this screen, so the fail-closed reason is reported instead. */
        dluma_ui_mod_details_localized(
            "DLUMA_ModDetails_SourceConflict",
            "NO SOURCE CAN BE SELECTED. EVERY DISCOVERED COPY OF THIS MOD "
            "SHARES ONE AMBIGUOUS LOCATION AND STAYS DISABLED.",
            missing, DLUMA_ARRAY_COUNT(missing));
        (void)dluma_ui_mod_details_add_field(
            "DLUMA_Common_Unavailable", "UNAVAILABLE", missing);
    } else if (selection_missing) {
        dluma_log_line(
            "INFO", "mod_details_source_selection_missing_choices_shown");
    }
}

static int dluma_ui_mod_details_select_source(
    void *screen, unsigned int row_index)
{
    DlumaModDetailsRowMap *row;
    const char *declared_id;
    const char *source_identity;
    unsigned int index;
    int changed = 0;
    char status[DLUMA_UI_WIDE_ROW_CAPACITY];
    if (!screen || row_index >= g_dluma_ui_mod_details_row_count)
        return 0;
    row = &g_dluma_ui_mod_details_rows[row_index];
    if (!row->source_picker || !row->source_identity[0])
        return 0;
    if (row->source_selected)
        return 1;
    source_identity = row->source_identity;
    if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_ASSET &&
        g_dluma_ui_mod_details_asset_row.asset_kind == DLUMA_ASSET_MOD_KIND_OVERRIDE)
    {
        char diagnostic[192];
        changed = dluma_asset_mods_select_source(g_dluma_ui_mod_details_asset.id,
            source_identity, diagnostic, DLUMA_ARRAY_COUNT(diagnostic));
        if (!changed)
        {
            dluma_ui_set_text_element_text(g_dluma_ui_mod_details_status, diagnostic);
            return 1;
        }
        dluma_ui_registry_snapshot();
        (void)dluma_ui_mod_details_revalidate();
        dluma_atomic_exchange(&g_dluma_mod_details_deferred_populate, 1);
        return 1;
    }
    if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_NATIVE)
    {
        declared_id = g_dluma_ui_mod_details_native.id;
        changed = dluma_native_mods_request_source(
            declared_id, source_identity,
            g_dluma_ui_native_mod_revision);
    }
    else if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_MANAGED)
    {
        declared_id = g_dluma_ui_mod_details_managed.id;
        changed = dluma_managed_mods_request_source(
            declared_id, source_identity,
            g_dluma_ui_managed_mod_revision);
    }
    else
    {
        declared_id = g_dluma_ui_mod_details_lua.id;
        changed = dluma_lua_request_global_source(
            declared_id, source_identity,
            g_dluma_ui_global_mod_revision);
    }
    if (!changed)
    {
        dluma_ui_mod_details_localized(
            "DLUMA_Mods_SourceSaveFailed",
            "THE MOD SOURCE COULD NOT BE SAVED.",
            status, DLUMA_ARRAY_COUNT(status));
        dluma_ui_set_text_element_text(g_dluma_ui_mod_details_status, status);
        return 1;
    }

    dluma_ui_registry_snapshot();
    if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_NATIVE)
    {
        for (index = 0; index < g_dluma_ui_native_mod_count; ++index)
            if (dluma_stricmp(g_dluma_ui_native_mods[index].id,
                            declared_id) == 0 &&
                dluma_stricmp(g_dluma_ui_native_mods[index].source_identity,
                            source_identity) == 0)
            {
                g_dluma_ui_mod_details_native = g_dluma_ui_native_mods[index];
                dluma_native_mods_make_mutation_request(
                    &g_dluma_ui_mod_details_native_request,
                    &g_dluma_ui_native_mods[index],
                    g_dluma_ui_native_mod_revision);
                break;
            }
    }
    else if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_MANAGED)
    {
        for (index = 0; index < g_dluma_ui_managed_mod_count; ++index)
            if (dluma_stricmp(g_dluma_ui_managed_mods[index].id,
                            declared_id) == 0 &&
                dluma_stricmp(g_dluma_ui_managed_mods[index].source_identity,
                            source_identity) == 0)
            {
                g_dluma_ui_mod_details_managed = g_dluma_ui_managed_mods[index];
                dluma_managed_mods_make_mutation_request(
                    &g_dluma_ui_mod_details_managed_request,
                    &g_dluma_ui_managed_mods[index],
                    g_dluma_ui_managed_mod_revision);
                break;
            }
    }
    else
    {
        for (index = 0; index < g_dluma_ui_global_mod_count; ++index)
            if (dluma_stricmp(g_dluma_ui_global_mods[index].id,
                            declared_id) == 0 &&
                dluma_stricmp(g_dluma_ui_global_mods[index].source_identity,
                            source_identity) == 0)
            {
                g_dluma_ui_mod_details_lua = g_dluma_ui_global_mods[index];
                dluma_ui_make_mutation_request(
                    &g_dluma_ui_mod_details_request,
                    &g_dluma_ui_global_mods[index],
                    g_dluma_ui_global_mod_revision);
                break;
            }
    }
    for (index = 0; index < g_dluma_ui_mod_details_row_count; ++index)
        if (g_dluma_ui_mod_details_rows[index].source_picker)
        {
            DlumaModDetailsRowMap *source_row =
                &g_dluma_ui_mod_details_rows[index];
            char state[96];
            char hint[DLUMA_UI_WIDE_ROW_CAPACITY];
            source_row->source_selected =
                (unsigned char)(index == row_index);
            dluma_ui_mod_details_localized(
                source_row->source_selected
                    ? "DLUMA_Common_Selected" : "DLUMA_Common_Select",
                source_row->source_selected ? "SELECTED" : "SELECT",
                state, DLUMA_ARRAY_COUNT(state));
            dluma_ui_mod_details_localized(
                "DLUMA_ModDetails_SourceHint",
                "CHOOSE WHICH LOCAL OR WORKSHOP COPY PROVIDES THIS MOD.",
                hint, DLUMA_ARRAY_COUNT(hint));
            dluma_str_copy(
                source_row->value, DLUMA_ARRAY_COUNT(source_row->value),
                state);
            dluma_str_append(
                source_row->value, DLUMA_ARRAY_COUNT(source_row->value),
                "\n\n");
            dluma_str_append(
                source_row->value, DLUMA_ARRAY_COUNT(source_row->value),
                hint);
        }
    dluma_ui_mod_details_localized(
        g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_LUA
            ? "DLUMA_Mods_SourceApplied"
            : "DLUMA_Mods_SourceRestart",
        g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_LUA
            ? "SOURCE CHANGED."
            : "SOURCE SAVED. RESTART REQUIRED.",
        status, DLUMA_ARRAY_COUNT(status));
    dluma_ui_set_text_element_text(g_dluma_ui_mod_details_status, status);
    dluma_log_pair("INFO", "mod_source_selected", source_identity);
    dluma_ui_mod_details_update_for_row(row_index);
    return 1;
}

static int dluma_ui_mod_details_append_bytes(
    char *out, unsigned int capacity, unsigned int *length,
    const char *source, unsigned int byte_count)
{
    unsigned int index;
    if (!out || !capacity || !length || !source ||
        *length >= capacity ||
        byte_count >= capacity - *length)
        return 0;
    for (index = 0; index < byte_count; ++index)
        out[(*length)++] = source[index];
    out[*length] = 0;
    return 1;
}

static int dluma_ui_mod_details_append_text(
    char *out, unsigned int capacity, unsigned int *length,
    const char *text)
{
    unsigned int byte_count = 0;
    if (!text)
        return 1;
    while (text[byte_count])
        ++byte_count;
    return dluma_ui_mod_details_append_bytes(
        out, capacity, length, text, byte_count);
}

static unsigned int dluma_ui_mod_details_utf8_sequence(
    const char *source, unsigned int input_index,
    unsigned int *display_columns)
{
    unsigned char lead;
    unsigned int sequence_bytes = 1;
    unsigned int index;
    if (display_columns)
        *display_columns = 1;
    if (!source)
        return 0;
    lead = (unsigned char)source[input_index];
    if ((lead & 0xE0U) == 0xC0U)
        sequence_bytes = 2;
    else if ((lead & 0xF0U) == 0xE0U)
        sequence_bytes = 3;
    else if ((lead & 0xF8U) == 0xF0U)
        sequence_bytes = 4;
    if (sequence_bytes > 1 && display_columns)
        *display_columns = 2;
    for (index = 1; index < sequence_bytes; ++index)
    {
        unsigned char continuation =
            (unsigned char)source[input_index + index];
        if (!continuation ||
            (continuation & 0xC0U) != 0x80U)
        {
            if (display_columns)
                *display_columns = 1;
            return 1;
        }
    }
    return sequence_bytes;
}

static void dluma_ui_wrap_text_columns(
    const char *source, int path_mode, unsigned int maximum_columns,
    char *out, unsigned int capacity)
{
    unsigned int input_index = 0;
    unsigned int output_index = 0;
    unsigned int columns = 0;
    out[0] = 0;
    if (!source)
        return;
    while (source[input_index])
    {
        unsigned char lead = (unsigned char)source[input_index];
        unsigned int display_columns;
        unsigned int sequence_bytes;
        if (lead == '\r' || lead == '\n')
        {
            if (lead == '\r' && source[input_index + 1U] == '\n')
                ++input_index;
            if (!dluma_ui_mod_details_append_bytes(
                    out, capacity, &output_index, "\n", 1))
                break;
            ++input_index;
            columns = 0;
            continue;
        }
        sequence_bytes = dluma_ui_mod_details_utf8_sequence(
            source, input_index, &display_columns);
        if (columns &&
            columns + display_columns >
                maximum_columns)
        {
            if (!dluma_ui_mod_details_append_bytes(
                    out, capacity, &output_index, "\n", 1))
                break;
            columns = 0;
        }
        if (!dluma_ui_mod_details_append_bytes(
                out, capacity, &output_index,
                source + input_index, sequence_bytes))
            break;
        input_index += sequence_bytes;
        columns += display_columns;
        if (source[input_index] &&
            ((path_mode && (lead == '\\' || lead == '/') &&
              columns >= maximum_columns * 5U / 8U) ||
             (!path_mode && lead == ' ' &&
              columns >= maximum_columns * 3U / 4U)))
        {
            if (!dluma_ui_mod_details_append_bytes(
                    out, capacity, &output_index, "\n", 1))
                break;
            columns = 0;
        }
    }
}

static void dluma_ui_mod_details_wrap_text(
    const char *source, int path_mode,
    char *out, unsigned int capacity)
{
    dluma_ui_wrap_text_columns(
        source, path_mode, DLUMA_UI_MOD_DETAILS_HINT_COLUMNS,
        out, capacity);
}

static int dluma_ui_mod_details_append_hash(
    const char *hash, char *out, unsigned int capacity,
    unsigned int *length)
{
    unsigned int index = 0;
    if (!hash || !hash[0])
        return 1;
    while (hash[index])
    {
        if (index && (index % 32U) == 0U &&
            !dluma_ui_mod_details_append_bytes(
                out, capacity, length, "\n", 1))
            return 0;
        if (!dluma_ui_mod_details_append_bytes(
                out, capacity, length, hash + index, 1))
            return 0;
        ++index;
    }
    return 1;
}

static void dluma_ui_mod_details_format_value(
    const DlumaModDetailsRowMap *row,
    char *out, unsigned int capacity)
{
    unsigned int length = 0;
    char permissions_label[128];
    char approval_label[128];
    if (!out || !capacity)
        return;
    out[0] = 0;
    if (!row)
        return;
    switch ((DlumaModDetailsValueKind)row->value_kind)
    {
    case DLUMA_MOD_DETAILS_VALUE_PATH:
        dluma_ui_mod_details_wrap_text(
            row->value, 1, out, capacity);
        break;
    case DLUMA_MOD_DETAILS_VALUE_SHA256:
        (void)dluma_ui_mod_details_append_hash(
            row->value, out, capacity, &length);
        break;
    case DLUMA_MOD_DETAILS_VALUE_FINGERPRINT_PAIR:
        dluma_ui_mod_details_localized(
            "DLUMA_Common_Permissions", "PERMISSIONS",
            permissions_label, DLUMA_ARRAY_COUNT(permissions_label));
        dluma_ui_mod_details_localized(
            "DLUMA_Common_ExactApproval", "EXACT APPROVAL",
            approval_label, DLUMA_ARRAY_COUNT(approval_label));
        if (row->value[0])
        {
            (void)dluma_ui_mod_details_append_text(
                out, capacity, &length, permissions_label);
            (void)dluma_ui_mod_details_append_text(
                out, capacity, &length, "\n");
            (void)dluma_ui_mod_details_append_hash(
                row->value, out, capacity, &length);
        }
        if (row->secondary_value[0])
        {
            if (length)
                (void)dluma_ui_mod_details_append_text(
                    out, capacity, &length, "\n\n");
            (void)dluma_ui_mod_details_append_text(
                out, capacity, &length, approval_label);
            (void)dluma_ui_mod_details_append_text(
                out, capacity, &length, "\n");
            (void)dluma_ui_mod_details_append_hash(
                row->secondary_value, out, capacity, &length);
        }
        break;
    default:
        dluma_ui_mod_details_wrap_text(
            row->value, 0, out, capacity);
        break;
    }
}

static void dluma_ui_mod_details_update_for_row(unsigned int row_index)
{
    char header[DLUMA_UI_WIDE_ROW_CAPACITY];
    char body[DLUMA_UI_MOD_DETAILS_HINT_CAPACITY];
    char action[96];
    int action_disabled = 0;
    if (row_index < g_dluma_ui_mod_details_row_count)
    {
        DlumaModDetailsRowMap *row =
            &g_dluma_ui_mod_details_rows[row_index];
        g_dluma_ui_mod_details_selected_row = row_index;
        dluma_str_copy(
            header, DLUMA_ARRAY_COUNT(header),
            row->label);
        dluma_ui_mod_details_format_value(
            row, body, DLUMA_ARRAY_COUNT(body));
        if (row->source_picker)
        {
            dluma_ui_mod_details_localized(
                row->source_selected
                    ? "DLUMA_Common_Selected" : "DLUMA_Common_Select",
                row->source_selected ? "SELECTED" : "SELECT",
                action, DLUMA_ARRAY_COUNT(action));
            action_disabled = row->source_selected != 0;
        }
        else
            dluma_ui_mod_details_localized(
                "DLUMA_ModDetails_ViewScroll", "VIEW / SCROLL",
                action, DLUMA_ARRAY_COUNT(action));
    }
    else
    {
        g_dluma_ui_mod_details_selected_row = 0xFFFFFFFFUL;
        dluma_ui_mod_details_localized(
            "DLUMA_ModDetails_SelectField", "SELECT A DETAIL",
            header, DLUMA_ARRAY_COUNT(header));
        dluma_ui_mod_details_localized(
            "DLUMA_ModDetails_SelectFieldHint",
            "SELECT A ROW TO VIEW ITS COMPLETE VALUE.",
            body, DLUMA_ARRAY_COUNT(body));
        dluma_ui_mod_details_localized(
            "DLUMA_ModDetails_ViewScroll", "VIEW / SCROLL",
            action, DLUMA_ARRAY_COUNT(action));
        action_disabled = 1;
    }
    dluma_ui_set_text_element_text(
        g_dluma_ui_mod_details_hint_header, header);
    dluma_ui_set_text_element_long(
        g_dluma_ui_mod_details_hint_body, body);
    dluma_ui_set_element_text(
        g_dluma_ui_mod_details_view_button, action);
    dluma_ui_set_element_disabled(
        g_dluma_ui_mod_details_view_button, action_disabled);
    dluma_ui_reset_validated_scroll_view(
        g_dluma_ui_mod_details_value_scroll);
}

static void dluma_ui_mod_details_focus_value(void)
{
    if (!g_dluma_ui_mod_details_value_scroll)
        return;
    if (dluma_ui_workshop_bind_row_interaction_exports())
    {
        g_dluma_set_element_can_focus(
            g_dluma_ui_mod_details_value_scroll, 1);
        g_dluma_process_element_inputs(
            g_dluma_ui_mod_details_value_scroll, 1);
    }
    dluma_ui_focus_element(
        g_dluma_ui_mod_details_value_scroll);
}

static void dluma_ui_mod_details_populate_list(void *screen)
{
    char category[128];
    char status[DLUMA_UI_WIDE_ROW_CAPACITY];
    if (!dluma_ui_mod_details_resolve_controls(screen) ||
        !g_dluma_list_clear)
        return;
    g_dluma_list_clear(
        (BYTE *)g_dluma_ui_mod_details_list +
        DLUMA_UI_LIST_INTERFACE_OFFSET);
    memset(g_dluma_ui_mod_details_rows, 0,
           sizeof(g_dluma_ui_mod_details_rows));
    g_dluma_ui_mod_details_row_count = 0;
    g_dluma_ui_mod_details_selected_row = 0xFFFFFFFFUL;
    if (!dluma_ui_mod_details_revalidate())
    {
        dluma_ui_mod_details_localized(
            "DLUMA_ModDetails_Stale",
            "THE MOD CHANGED OR WAS REMOVED. GO BACK AND OPEN DETAILS AGAIN.",
            status, DLUMA_ARRAY_COUNT(status));
        dluma_ui_set_text_element_text(
            g_dluma_ui_mod_details_status, status);
        (void)dluma_ui_mod_details_add_field(
            "DLUMA_Common_Status", "STATUS", status);
        dluma_ui_set_element_disabled(
            g_dluma_ui_mod_details_category_previous, 1);
        dluma_ui_set_element_disabled(
            g_dluma_ui_mod_details_category_next, 1);
    }
    else
    {
        if (g_dluma_ui_mod_details_category >=
            DLUMA_MOD_DETAILS_CATEGORY_COUNT)
            g_dluma_ui_mod_details_category = DLUMA_MOD_DETAILS_OVERVIEW;
        dluma_ui_set_element_disabled(
            g_dluma_ui_mod_details_category_previous, 0);
        dluma_ui_set_element_disabled(
            g_dluma_ui_mod_details_category_next, 0);
        switch ((DlumaModDetailsCategory)
                    g_dluma_ui_mod_details_category)
        {
        case DLUMA_MOD_DETAILS_SOURCE:
            dluma_ui_mod_details_localized(
                "DLUMA_ModDetails_Category_Source", "SOURCE",
                category, DLUMA_ARRAY_COUNT(category));
            dluma_ui_mod_details_add_source();
            break;
        case DLUMA_MOD_DETAILS_STATE:
            dluma_ui_mod_details_localized(
                "DLUMA_ModDetails_Category_State", "STATE",
                category, DLUMA_ARRAY_COUNT(category));
            dluma_ui_mod_details_add_state();
            break;
        case DLUMA_MOD_DETAILS_SECURITY:
            dluma_ui_mod_details_localized(
                "DLUMA_ModDetails_Category_Security", "SECURITY",
                category, DLUMA_ARRAY_COUNT(category));
            dluma_ui_mod_details_add_security();
            break;
        case DLUMA_MOD_DETAILS_CONFIG:
            dluma_ui_mod_details_localized(
                "DLUMA_ModDetails_Category_Config", "CONFIG",
                category, DLUMA_ARRAY_COUNT(category));
            dluma_ui_mod_details_add_config();
            break;
        default:
            dluma_ui_mod_details_localized(
                "DLUMA_ModDetails_Category_Overview", "OVERVIEW",
                category, DLUMA_ARRAY_COUNT(category));
            dluma_ui_mod_details_add_overview();
            break;
        }
        dluma_ui_set_text_element_text(
            g_dluma_ui_mod_details_category_title, category);
        dluma_str_copy(
            status, DLUMA_ARRAY_COUNT(status),
            g_dluma_ui_mod_details_kind ==
                    DLUMA_REGISTRY_ROW_KIND_ASSET
                ? (g_dluma_ui_mod_details_asset_row.asset_kind == DLUMA_ASSET_MOD_KIND_OVERRIDE
                       ? (g_dluma_ui_mod_details_asset.name[0]
                              ? g_dluma_ui_mod_details_asset.name : g_dluma_ui_mod_details_asset.id)
                       : g_dluma_ui_mod_details_asset_row.menu_stock
                       ? "Stock Menu"
                       : (g_dluma_ui_mod_details_menu.name[0]
                              ? g_dluma_ui_mod_details_menu.name
                              : g_dluma_ui_mod_details_asset_row.script_id))
                : (g_dluma_ui_mod_details_kind ==
                    DLUMA_REGISTRY_ROW_KIND_NATIVE
                ? g_dluma_ui_mod_details_native.name
                : (g_dluma_ui_mod_details_kind ==
                           DLUMA_REGISTRY_ROW_KIND_MANAGED
                       ? g_dluma_ui_mod_details_managed.name
                       : g_dluma_ui_mod_details_lua.name)));
        dluma_ui_set_text_element_text(
            g_dluma_ui_mod_details_status, status);
    }
    if (g_dluma_list_set_capacity)
        (void)g_dluma_list_set_capacity(
            g_dluma_ui_mod_details_list,
            (int)DLUMA_UI_MOD_DETAILS_VISIBLE_ROWS, 1);
    if (g_dluma_ui_mod_details_row_count)
    {
        dluma_ui_list_set_selection(g_dluma_ui_mod_details_list, 0);
        dluma_ui_mod_details_update_for_row(0);
        dluma_ui_focus_element(g_dluma_ui_mod_details_list);
    }
    else
        dluma_ui_mod_details_update_for_row(0xFFFFFFFFUL);
}

static int dluma_ui_mod_details_select_pointer_item(
    void *item, unsigned int *row_out)
{
    unsigned int row;
    if (row_out)
        *row_out = 0xFFFFFFFFUL;
    if (!item || !g_dluma_ui_mod_details_list)
        return 0;
    for (row = 0; row < g_dluma_ui_mod_details_row_count; ++row)
    {
        if (g_dluma_ui_mod_details_rows[row].item != item)
            continue;
        dluma_ui_list_set_selection(
            g_dluma_ui_mod_details_list,
            g_dluma_ui_mod_details_rows[row].list_index);
        if (row_out)
            *row_out = row;
        return 1;
    }
    return 0;
}

static void dluma_ui_mod_details_cycle_category(
    void *screen, int direction)
{
    if (!screen || !dluma_ui_is_mod_details_screen(screen) ||
        g_dluma_ui_mod_details_stale)
        return;
    if (direction < 0)
        g_dluma_ui_mod_details_category =
            g_dluma_ui_mod_details_category == 0
                ? DLUMA_MOD_DETAILS_CATEGORY_COUNT - 1U
                : g_dluma_ui_mod_details_category - 1U;
    else
        g_dluma_ui_mod_details_category =
            (g_dluma_ui_mod_details_category + 1U) %
            DLUMA_MOD_DETAILS_CATEGORY_COUNT;
    dluma_ui_mod_details_populate_list(screen);
}

static int dluma_ui_mod_details_is_visible(void *screen)
{
    void *level;
    int screen_id;
    if (!screen || !g_dluma.engine.is_ui_screen_visible ||
        !g_dluma_get_object_level)
        return 0;
    level = g_dluma_get_object_level(screen);
    if (!level ||
        g_dluma_mod_details_registered_level != level)
        return 0;
    screen_id = g_dluma_mod_details_screen_id;
    return screen_id >= 0 &&
           g_dluma.engine.is_ui_screen_visible(level, screen_id);
}

static void dluma_ui_mod_details_refresh_after_seen(void)
{
    unsigned int total;
    unsigned int index;
    ULONGLONG hash = 0;
    ULONGLONG revision = 0;

    memset(g_dluma_ui_global_mods, 0, sizeof(g_dluma_ui_global_mods));
    total = dluma_lua_snapshot_globals_with_revision(
        g_dluma_ui_global_mods, DLUMA_UI_MAX_GLOBAL_MODS,
        &hash, &revision);
    g_dluma_ui_global_mod_total = total;
    g_dluma_ui_global_mod_count =
        total > DLUMA_UI_MAX_GLOBAL_MODS
            ? DLUMA_UI_MAX_GLOBAL_MODS
            : total;
    g_dluma_ui_global_mod_revision = revision;
    (void)hash;
    for (index = 0; index < g_dluma_ui_global_mod_count; ++index)
    {
        DlumaLuaMetadata *item = &g_dluma_ui_global_mods[index];
        if (dluma_stricmp(
                item->registry_key,
                g_dluma_ui_mod_details_request.registry_key) != 0 ||
            dluma_stricmp(
                item->metadata_fingerprint,
                g_dluma_ui_mod_details_request
                    .metadata_fingerprint) != 0)
            continue;
        g_dluma_ui_mod_details_lua = *item;
        dluma_ui_make_mutation_request(
            &g_dluma_ui_mod_details_request, item, revision);
        return;
    }
    g_dluma_ui_mod_details_stale = 1;
}

static void dluma_ui_mod_details_confirm_visible(void *screen)
{
    char status[DLUMA_UI_WIDE_ROW_CAPACITY];
    if (!g_dluma_ui_mod_details_seen_pending ||
        g_dluma_ui_mod_details_seen_failed ||
        g_dluma_ui_mod_details_stale ||
        g_dluma_ui_mod_details_kind != DLUMA_REGISTRY_ROW_KIND_LUA ||
        !dluma_ui_mod_details_is_visible(screen))
        return;
    if (!dluma_lua_mark_global_seen(&g_dluma_ui_mod_details_request))
    {
        g_dluma_ui_mod_details_seen_failed = 1;
        dluma_ui_mod_details_localized(
            "DLUMA_ModDetails_SeenFailed",
            "DETAILS ARE VISIBLE, BUT THE NEW-MOD REVIEW STATE COULD NOT BE SAVED.",
            status, DLUMA_ARRAY_COUNT(status));
        dluma_ui_set_text_element_text(
            g_dluma_ui_mod_details_status, status);
        dluma_log_pair(
            "WARN", "new_global_details_seen_persist_failed",
            g_dluma_ui_mod_details_request.registry_key);
        return;
    }
    g_dluma_ui_mod_details_seen_pending = 0;
    dluma_ui_mod_details_refresh_after_seen();
    dluma_ui_mod_details_localized(
        "DLUMA_ModDetails_SeenRecorded",
        "DETAILS REVIEW RECORDED.",
        status, DLUMA_ARRAY_COUNT(status));
    dluma_ui_set_text_element_text(
        g_dluma_ui_mod_details_status, status);
}

static void dluma_ui_registry_set_main_controls_visible(int visible)
{
    void *controls[] = {
        g_dluma_ui_registry_list,
        g_dluma_ui_registry_toggle_button,
        g_dluma_ui_registry_details_button,
        g_dluma_ui_registry_configure_button,
        g_dluma_ui_registry_custom_menu_configure_button,
        g_dluma_ui_registry_asset_move_up,
        g_dluma_ui_registry_asset_move_down,
        g_dluma_ui_registry_back_button,
        g_dluma_ui_registry_category_previous,
        g_dluma_ui_registry_category_next
    };
    unsigned int index;
    int input_binding_ready =
        dluma_ui_workshop_bind_row_interaction_exports();
    for (index = 0; index < DLUMA_ARRAY_COUNT(controls); ++index)
    {
        dluma_ui_set_element_visible(controls[index], visible);
        dluma_ui_set_element_disabled(controls[index], visible ? 0 : 1);
        if (input_binding_ready && controls[index])
            g_dluma_process_element_inputs(
                controls[index], (unsigned char)(visible ? 1 : 0));
    }
    dluma_ui_set_element_visible(g_dluma_ui_registry_status, visible);
    dluma_ui_set_element_visible(g_dluma_ui_registry_category_title, visible);
    dluma_ui_set_element_visible(g_dluma_ui_registry_hint_header, visible);
    dluma_ui_set_element_visible(g_dluma_ui_registry_hint_body, visible);
    if (visible)
        dluma_ui_registry_update_button_labels();
}

