static void dluma_ui_registry_confirm_details_visible(void *screen)
{
    int persisted;
    if (!g_dluma_ui_registry_details_mode ||
        !g_dluma_ui_registry_details_seen_pending ||
        g_dluma_ui_registry_details_seen_failed ||
        !dluma_ui_is_element_visible(g_dluma_ui_registry_details_popup))
        return;
    persisted = dluma_lua_mark_global_seen(
        &g_dluma_ui_registry_details_request);
    if (!persisted)
    {
        g_dluma_ui_registry_details_seen_failed = 1;
        dluma_ui_registry_set_popup_field(
            screen, "T_DetailsError", "REVIEW WRITE",
            "FAILED - NEW remains set; reopen details after retrying storage");
        dluma_log_pair("WARN", "new_global_details_seen_persist_failed",
                     g_dluma_ui_registry_details_request.registry_key);
        return;
    }
    g_dluma_ui_registry_details_seen_pending = 0;
    dluma_ui_registry_set_popup_field(
        screen, "T_DetailsReview", "REVIEW STATE",
        "SEEN - APPROVAL REQUIRED");
    dluma_ui_registry_set_popup_field(
        screen, "T_DetailsError", "REVIEW WRITE", "COMMITTED");
}

static void dluma_ui_registry_hide_details_popup(void)
{
    dluma_ui_set_element_visible(g_dluma_ui_registry_details_popup, 0);
    dluma_ui_registry_set_main_controls_visible(1);
    dluma_ui_focus_element(g_dluma_ui_registry_list);
    if (g_dluma_ui_registry_details_popup_close && g_dluma_set_element_can_focus)
        g_dluma_set_element_can_focus(g_dluma_ui_registry_details_popup_close, 0);
    memset(&g_dluma_ui_registry_details_request, 0,
           sizeof(g_dluma_ui_registry_details_request));
    g_dluma_ui_registry_details_seen_pending = 0;
    g_dluma_ui_registry_details_seen_failed = 0;
    g_dluma_ui_registry_details_kind = 0;
}

static int dluma_ui_registry_show_native_details_popup(
    void *screen, const DlumaNativeModSnapshot *item)
{
    char path[DLUMA_MAX_WPATH * 2];
    char fingerprints[DLUMA_UI_WIDE_POPUP_CAPACITY];
    char runtime[DLUMA_UI_WIDE_POPUP_CAPACITY];
    char config_status[DLUMA_UI_WIDE_POPUP_CAPACITY];
    char error_status[64];
    if (!screen || !item || !dluma_ui_registry_resolve_controls(screen)) return 0;
    path[0] = 0;
    if (!dluma_wide_to_utf8(item->final_path, path, DLUMA_ARRAY_COUNT(path)))
        dluma_str_copy(path, DLUMA_ARRAY_COUNT(path), "Path conversion failed");
    fingerprints[0] = 0;
    dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints), "MODULE ");
    dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints), item->module_sha256);
    dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints), " | SIDECAR ");
    dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints),
                   item->sidecar_present ? item->sidecar_sha256 : "ABSENT");
    dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints), " | APPROVAL ");
    dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints),
                   item->approval_fingerprint);
    runtime[0] = 0;
    dluma_str_append(runtime, DLUMA_ARRAY_COUNT(runtime), "LOAD ORDER ");
    dluma_u64_to_text(item->resolved_load_index, runtime + strlen(runtime),
                    DLUMA_ARRAY_COUNT(runtime) - (unsigned int)strlen(runtime));
    dluma_str_append(runtime, DLUMA_ARRAY_COUNT(runtime), " | PRIORITY ");
    dluma_u64_to_text((ULONGLONG)item->load_priority, runtime + strlen(runtime),
                    DLUMA_ARRAY_COUNT(runtime) - (unsigned int)strlen(runtime));
    dluma_str_append(runtime, DLUMA_ARRAY_COUNT(runtime), " | ");
    dluma_str_append(runtime, DLUMA_ARRAY_COUNT(runtime),
                   dluma_native_mods_state_text(item));
    config_status[0] = 0;
    if (item->config_available)
    {
        dluma_str_append(
            config_status, DLUMA_ARRAY_COUNT(config_status), "SCHEMA ");
        dluma_str_append(
            config_status, DLUMA_ARRAY_COUNT(config_status),
            item->config_schema_fingerprint);
        dluma_str_append(
            config_status, DLUMA_ARRAY_COUNT(config_status), " | ");
        dluma_u64_to_text(
            item->config_category_count,
            config_status + strlen(config_status),
            DLUMA_ARRAY_COUNT(config_status) -
                (unsigned int)strlen(config_status));
        dluma_str_append(
            config_status, DLUMA_ARRAY_COUNT(config_status),
            " CATEGORIES / ");
        dluma_u64_to_text(
            item->config_setting_count,
            config_status + strlen(config_status),
            DLUMA_ARRAY_COUNT(config_status) -
                (unsigned int)strlen(config_status));
        dluma_str_append(
            config_status, DLUMA_ARRAY_COUNT(config_status),
            " SETTINGS");
    }
    else if (item->config_declared && item->config_diagnostic[0])
        dluma_str_copy(
            config_status, DLUMA_ARRAY_COUNT(config_status),
            item->config_diagnostic);
    else
        dluma_ui_localize_text(
            "DLUMA_Common_None", "NONE", config_status,
            DLUMA_ARRAY_COUNT(config_status));
    dluma_ui_localize_text(
        item->runtime_error[0]
            ? "DLUMA_Mods_State_LoadError"
            : "DLUMA_Common_None",
        item->runtime_error[0]
            ? "RUNTIME ERROR" : "NONE",
        error_status, DLUMA_ARRAY_COUNT(error_status));
    if (!dluma_ui_registry_set_popup_field(screen, "T_DetailsName", "TYPE",
                                         "DLL MOD") ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsId", "STABLE ID",
                                         item->id) ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsVersion", "VERSION",
                                         item->version) ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsScope", "ABI",
                                         dluma_native_mods_abi_text(item->abi_kind)) ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsStatus", "CURRENT STATE",
                                         dluma_native_mods_state_text(item)) ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsDefault", "RISK",
                                         "FULL NATIVE PROCESS ACCESS - NOT SANDBOXED") ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsOverride", "NEXT-LAUNCH STATE",
                                         item->enabled_requested ? "ENABLED NEXT LAUNCH / RESTART REQUIRED" : "DISABLED") ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsSource", "SOURCE PROJECT",
                                         item->source_name) ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsWorkshop", "WORKSHOP ID",
                                         item->workshop_id[0] ? item->workshop_id : "Local source") ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsPermissions", "RISK DETAILS",
                                         "Can bypass Lua permissions; read/write files and memory; crash or corrupt the game/session") ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsRelativePath", "CANONICAL RELATIVE PATH",
                                         item->canonical_relative_path) ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsPath", "FINAL FILE PATH", path) ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsFingerprint", "SHA-256", fingerprints) ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsReview", "PE / DLL STATUS",
                                         item->pe_machine_valid && item->pe_dll_valid ? "x64 DLL VALIDATED" : "INVALID") ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsApproval", "EXACT APPROVAL",
                                         item->approval_valid ? "VALID" : "REVIEW REQUIRED") ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsChange", "RESTART REQUIRED",
                                         "Menu changes never hot-load or hot-unload DLL MODs") ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsConflict", "DUPLICATE / CONFLICT",
                                         item->duplicate_id ? "DUPLICATE DECLARED ID - BLOCKED" : "None") ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsRuntime", "LOAD / ORDER", runtime) ||
        !dluma_ui_registry_set_popup_field(
            screen, "T_DetailsConfig", "CONFIG",
            config_status) ||
        !dluma_ui_registry_set_popup_field(screen, "T_DetailsError", "LAST LOAD/INIT ERROR",
                                         error_status))
        return 0;
    dluma_ui_registry_set_main_controls_visible(0);
    dluma_ui_set_element_visible(g_dluma_ui_registry_details_popup, 1);
    g_dluma_set_element_can_focus(g_dluma_ui_registry_details_popup_close, 1);
    dluma_ui_focus_element(g_dluma_ui_registry_details_popup_close);
    g_dluma_ui_registry_details_seen_pending = 0;
    g_dluma_ui_registry_details_kind = DLUMA_REGISTRY_ROW_KIND_NATIVE;
    return 1;
}
