static int dluma_ui_registry_prepare_approval_popup(void *screen)
{
    g_dluma_ui_registry_approval_scroll =
        dluma_ui_registry_find_control(screen, "G_ApprovalScroll");
    if (!g_dluma_ui_registry_approval_scroll)
        return 0;
    dluma_ui_reset_validated_scroll_view(g_dluma_ui_registry_approval_scroll);
    if (dluma_ui_workshop_bind_row_interaction_exports())
    {
        g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_scroll, 1);
        g_dluma_process_element_inputs(g_dluma_ui_registry_approval_scroll, 1);
    }
    return 1;
}

static int dluma_ui_registry_show_native_approval_popup(
    void *screen, const DlumaNativeModSnapshot *item,
    unsigned int host_flags)
{
    char source[DLUMA_UI_WIDE_POPUP_CAPACITY];
    char title_text[256];
    char risk_text[256];
    char warning_text[512];
    char effect_text[512];
    char note_text[256];
    char host_text[64];
    char fingerprints[DLUMA_UI_WIDE_POPUP_CAPACITY];
    void *title;
    if (!screen || !item || !dluma_ui_registry_resolve_controls(screen) ||
        item->duplicate_id || !dluma_ui_native_host_abi_compatible(item) ||
        !host_flags || host_flags > DLUMA_NATIVE_HOST_BOTH ||
        (host_flags & ~item->declared_host_flags) ||
        !dluma_ui_registry_prepare_approval_popup(screen)) return 0;
    source[0] = 0;
    dluma_str_append(source, DLUMA_ARRAY_COUNT(source), item->source_name);
    if (item->workshop_id[0]) {
        dluma_str_append(source, DLUMA_ARRAY_COUNT(source), " (Workshop ");
        dluma_str_append(source, DLUMA_ARRAY_COUNT(source), item->workshop_id);
        dluma_str_append(source, DLUMA_ARRAY_COUNT(source), ")");
    }
    dluma_ui_localize_text(
        "DLUMA_Mods_NativeApprovalTitle",
        "Enable DLL mod",
        title_text, DLUMA_ARRAY_COUNT(title_text));
    dluma_ui_localize_text(
        "DLUMA_Mods_NativeRisk",
        "FULL PROCESS ACCESS - NOT SANDBOXED",
        risk_text, DLUMA_ARRAY_COUNT(risk_text));
    dluma_ui_localize_text(
        (host_flags & DLUMA_NATIVE_HOST_EDITOR)
            ? "DLUMA_Mods_NativeEditorWarning"
            : "DLUMA_NewModsPopup_NativeWarning",
        (host_flags & DLUMA_NATIVE_HOST_EDITOR)
            ? "DLL MODS ENABLED FOR CHROME EDITOR CAN READ OR WRITE PROJECT FILES AND EDITOR MEMORY, AND CAN CRASH OR CORRUPT THE EDITOR SESSION. EDITOR TRUST IS APPROVED SEPARATELY."
            : "DLL MODS CAN BYPASS LUA PERMISSIONS, READ OR WRITE FILES AND MEMORY, AND CRASH OR CORRUPT THE GAME SESSION.",
        warning_text, DLUMA_ARRAY_COUNT(warning_text));
    dluma_ui_localize_text(
        "DLUMA_Mods_NativeRestartEffect",
        "Applies to the selected hosts after restarting.",
        effect_text, DLUMA_ARRAY_COUNT(effect_text));
    dluma_ui_localize_text(
        "DLUMA_Mods_NativeApprovalNote",
        "Enable this mod only if you trust its author.",
        note_text, DLUMA_ARRAY_COUNT(note_text));
    dluma_ui_native_host_state_text(
        host_flags, host_text, DLUMA_ARRAY_COUNT(host_text));
    fingerprints[0] = 0;
    if (host_flags & DLUMA_NATIVE_HOST_PLAYER)
    {
        char player_text[64];
        dluma_ui_native_host_state_text(
            DLUMA_NATIVE_HOST_PLAYER, player_text,
            DLUMA_ARRAY_COUNT(player_text));
        dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints),
                       player_text);
        dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints), ": ");
        dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints),
                       item->player_approval_fingerprint);
    }
    if (host_flags & DLUMA_NATIVE_HOST_EDITOR)
    {
        char editor_text[64];
        if (fingerprints[0])
            dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints),
                           " / ");
        dluma_ui_native_host_state_text(
            DLUMA_NATIVE_HOST_EDITOR, editor_text,
            DLUMA_ARRAY_COUNT(editor_text));
        dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints),
                       editor_text);
        dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints), ": ");
        dluma_str_append(fingerprints, DLUMA_ARRAY_COUNT(fingerprints),
                       item->editor_approval_fingerprint);
    }
    title = dluma_ui_registry_find_control(screen, "T_ApprovalTitle");
    if (title)
        dluma_ui_set_text_element_long(title, title_text);
    dluma_ui_registry_set_text_popup_field(screen, "T_ApprovalName", "DLL MOD", item->name);
    dluma_ui_registry_set_text_popup_field(screen, "T_ApprovalId", "ID", item->id);
    dluma_ui_registry_set_text_popup_field(screen, "T_ApprovalVersion", "VERSION", item->version);
    dluma_ui_registry_set_text_popup_field(screen, "T_ApprovalSource", "SOURCE", source);
    dluma_ui_registry_set_text_popup_field(screen, "T_ApprovalRisk", "RISK",
        risk_text);
    dluma_ui_registry_set_text_popup_field(screen, "T_ApprovalPermissions", "WARNING",
        warning_text);
    dluma_ui_registry_set_text_popup_field(screen, "T_ApprovalChange", "EXACT FINGERPRINT",
        fingerprints);
    dluma_ui_registry_set_text_popup_field(screen, "T_ApprovalScope", host_text,
        effect_text);
    dluma_ui_registry_set_text_popup_field(screen, "T_ApprovalNote", "RESTART REQUIRED",
        note_text);
    dluma_ui_registry_set_main_controls_visible(0);
    dluma_ui_set_element_visible(g_dluma_ui_registry_approval_popup, 1);
    if (g_dluma_set_element_can_focus) {
        g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_cancel, 1);
        g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_confirm, 1);
    }
    /* A is the native confirm action and B is the explicit cancel shortcut.
     * Focus the visible confirm button so controller confirmation cannot
     * silently activate Cancel after the player chose Enable/Review. */
    dluma_ui_focus_element(g_dluma_ui_registry_approval_confirm);
    dluma_native_mods_make_mutation_request(
        &g_dluma_ui_registry_native_approval_request, item,
        g_dluma_ui_native_mod_revision);
    g_dluma_ui_registry_native_approval_host_flags =
        (unsigned char)host_flags;
    g_dluma_ui_registry_approval_mode = 1;
    g_dluma_ui_registry_approval_kind = DLUMA_REGISTRY_ROW_KIND_NATIVE;
    return 1;
}

static int dluma_ui_registry_show_managed_approval_popup(
    void *screen, const DlumaManagedModSnapshot *item)
{
    char source[DLUMA_UI_WIDE_POPUP_CAPACITY];
    char title_text[256];
    char risk_text[256];
    char warning_text[512];
    char effect_text[256];
    char note_text[256];
    void *title;
    if (!screen || !item || !dluma_ui_registry_resolve_controls(screen) ||
        item->duplicate_id ||
        item->state == DLUMA_MANAGED_STATE_INCOMPATIBLE ||
        !dluma_ui_registry_prepare_approval_popup(screen))
        return 0;
    source[0] = 0;
    dluma_str_append(source, DLUMA_ARRAY_COUNT(source), item->source_name);
    if (item->workshop_id[0]) {
        dluma_str_append(source, DLUMA_ARRAY_COUNT(source), " (Workshop ");
        dluma_str_append(source, DLUMA_ARRAY_COUNT(source), item->workshop_id);
        dluma_str_append(source, DLUMA_ARRAY_COUNT(source), ")");
    }
    dluma_ui_localize_text(
        "DLUMA_Mods_CSharpApprovalTitle",
        "Enable C# mod",
        title_text, DLUMA_ARRAY_COUNT(title_text));
    dluma_ui_localize_text(
        "DLUMA_Mods_ManagedRisk",
        "FULL PROCESS ACCESS - MANAGED CODE IS NOT SANDBOXED",
        risk_text, DLUMA_ARRAY_COUNT(risk_text));
    dluma_ui_localize_text(
        "DLUMA_Mods_CSharpWarning",
        "C# MODS CAN BYPASS DLUMA ACCESS DECLARATIONS, READ OR WRITE FILES AND MEMORY, AND CRASH OR CORRUPT THE GAME SESSION.",
        warning_text, DLUMA_ARRAY_COUNT(warning_text));
    dluma_ui_localize_text(
        "DLUMA_Mods_CSharpRestartEffect",
        "Applies after restarting.",
        effect_text, DLUMA_ARRAY_COUNT(effect_text));
    dluma_ui_localize_text(
        "DLUMA_Mods_CSharpApprovalNote",
        "Enable this mod only if you trust its author.",
        note_text, DLUMA_ARRAY_COUNT(note_text));
    title = dluma_ui_registry_find_control(screen, "T_ApprovalTitle");
    if (title)
        dluma_ui_set_text_element_long(title, title_text);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalName", "C# MOD", item->name);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalId", "ID", item->id);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalVersion", "VERSION", item->version);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalSource", "SOURCE", source);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalRisk", "RISK", risk_text);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalPermissions", "WARNING", warning_text);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalChange", "EXACT FINGERPRINT",
        item->approval_fingerprint);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalScope", "EFFECT", effect_text);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalNote", "RESTART REQUIRED", note_text);
    dluma_ui_registry_set_main_controls_visible(0);
    dluma_ui_set_element_visible(g_dluma_ui_registry_approval_popup, 1);
    if (g_dluma_set_element_can_focus) {
        g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_cancel, 1);
        g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_confirm, 1);
    }
    dluma_ui_focus_element(g_dluma_ui_registry_approval_confirm);
    dluma_managed_mods_make_mutation_request(
        &g_dluma_ui_registry_managed_approval_request, item,
        g_dluma_ui_managed_mod_revision);
    g_dluma_ui_registry_approval_mode = 1;
    g_dluma_ui_registry_approval_kind = DLUMA_REGISTRY_ROW_KIND_MANAGED;
    return 1;
}

static int dluma_ui_registry_show_approval_popup(
    void *screen, const DlumaLuaMetadata *item)
{
    char source[DLUMA_UI_WIDE_POPUP_CAPACITY];
    char title[256];
    char note[512];
    const char *risk;
    if (!screen || !item || !dluma_ui_registry_resolve_controls(screen) ||
        !dluma_ui_registry_prepare_approval_popup(screen))
        return 0;
    dluma_ui_localize_text(
        "DLUMA_Mods_LuaApprovalTitle", "ENABLE LUA MOD",
        title, DLUMA_ARRAY_COUNT(title));
    dluma_ui_set_text_element_long(
        dluma_ui_registry_find_control(screen, "T_ApprovalTitle"), title);
    dluma_ui_localize_text(
        "DLUMA_Mods_LuaApprovalNote",
        "Allow this mod to run with the permissions listed above.",
        note, DLUMA_ARRAY_COUNT(note));
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalNote", "LUA MOD", note);
    g_dluma_ui_registry_approval_unsupported =
        (unsigned char)(dluma_lua_permission_is_unsupported(item) ? 1 : 0);
    risk = g_dluma_ui_registry_approval_unsupported ? "UNSUPPORTED / DANGEROUS" : (dluma_lua_permission_is_sensitive(item) ? "GAMEPLAY WRITE - EXPLICIT APPROVAL REQUIRED" : "STANDARD SANDBOXED PERMISSIONS");
    dluma_log_pair("INFO", "global_mod_approval_popup_opening_id", item->id);
    source[0] = 0;
    dluma_str_append(source, DLUMA_ARRAY_COUNT(source),
                   item->source_name[0] ? item->source_name : "Unknown source");
    if (item->workshop_id[0])
    {
        dluma_str_append(source, DLUMA_ARRAY_COUNT(source), " (Workshop ");
        dluma_str_append(source, DLUMA_ARRAY_COUNT(source), item->workshop_id);
        dluma_str_append(source, DLUMA_ARRAY_COUNT(source), ")");
    }
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalName", "MOD", item->name);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalId", "ID", item->id);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalVersion", "VERSION", item->version);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalSource", "SOURCE", source);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalRisk", "RISK", risk);
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalPermissions", "PERMISSIONS",
        item->normalized_permissions[0]
            ? item->normalized_permissions
            : "None declared");
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalChange", "CHANGE",
        item->change_reason[0]
            ? item->change_reason
            : "First approval for this exact fingerprint");
    dluma_ui_registry_set_text_popup_field(
        screen, "T_ApprovalScope", "APPROVAL SCOPE",
        g_dluma_ui_registry_approval_unsupported
            ? "Requested capability is unavailable; this mod remains disabled"
            : "Exact content, metadata, permissions, source, and path fingerprint");
    dluma_ui_registry_set_main_controls_visible(0);
    dluma_ui_set_element_visible(g_dluma_ui_registry_approval_popup, 1);
    if (g_dluma_set_element_can_focus)
    {
        g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_cancel, 1);
        g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_confirm,
                                    g_dluma_ui_registry_approval_unsupported ? 0 : 1);
    }
    /* Approval remains a separate, explicit second A press. The old Cancel
     * focus made that A press dismiss the dialog while its prompt said Enable. */
    dluma_ui_focus_element(g_dluma_ui_registry_approval_confirm);
    dluma_ui_make_mutation_request(&g_dluma_ui_registry_approval_request,
                                 item, g_dluma_ui_global_mod_revision);
    g_dluma_ui_registry_approval_mode = 1;
    g_dluma_ui_registry_approval_kind = DLUMA_REGISTRY_ROW_KIND_LUA;
    dluma_log_pair("INFO", "global_mod_approval_popup_opened_id", item->id);
    return 1;
}

static void dluma_ui_registry_hide_approval_popup(void)
{
    dluma_ui_set_element_visible(g_dluma_ui_registry_approval_popup, 0);
    dluma_ui_registry_set_main_controls_visible(1);
    if (g_dluma_set_element_can_focus)
    {
        if (g_dluma_ui_registry_approval_scroll)
            g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_scroll, 0);
        g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_cancel, 0);
        g_dluma_set_element_can_focus(g_dluma_ui_registry_approval_confirm, 0);
    }
    if (g_dluma_ui_registry_approval_scroll && g_dluma_process_element_inputs)
        g_dluma_process_element_inputs(g_dluma_ui_registry_approval_scroll, 0);
    g_dluma_ui_registry_approval_scroll = 0;
    dluma_ui_focus_element(g_dluma_ui_registry_list);
    memset(&g_dluma_ui_registry_approval_request, 0,
           sizeof(g_dluma_ui_registry_approval_request));
    memset(&g_dluma_ui_registry_native_approval_request, 0,
           sizeof(g_dluma_ui_registry_native_approval_request));
    g_dluma_ui_registry_native_approval_host_flags = DLUMA_NATIVE_HOST_OFF;
    memset(&g_dluma_ui_registry_managed_approval_request, 0,
           sizeof(g_dluma_ui_registry_managed_approval_request));
    g_dluma_ui_registry_approval_mode = 0;
    g_dluma_ui_registry_approval_unsupported = 0;
    g_dluma_ui_registry_approval_kind = 0;
}

static void dluma_ui_registry_populate_list(void *screen,
                                          const char *restore_id)
{
    unsigned int i;
    int selection = -1;
    int first_new_index = -1;
    char wanted_id[DLUMA_SHA256_HEX_CAPACITY];
    char category[96];
    DlumaRegistryRowMap *mapping;
    if (!screen || !dluma_ui_is_mods_registry_screen(screen) ||
        !g_dluma_list_clear || !g_dluma_list_add_item)
        return;
    if (!dluma_ui_registry_resolve_controls(screen))
        return;

    wanted_id[0] = 0;
    if (restore_id && restore_id[0])
        dluma_str_copy(wanted_id, DLUMA_ARRAY_COUNT(wanted_id), restore_id);

    g_dluma_list_clear((BYTE *)g_dluma_ui_registry_list +
                     DLUMA_UI_LIST_INTERFACE_OFFSET);
    memset(g_dluma_ui_registry_rows, 0, sizeof(g_dluma_ui_registry_rows));
    g_dluma_ui_registry_row_count = 0;
    g_dluma_ui_registry_list_item_count = 0;
    dluma_ui_registry_snapshot();

    if (g_dluma_ui_registry_initial_category_pending)
    {
        g_dluma_ui_registry_category = DLUMA_REGISTRY_CATEGORY_ALL;
        g_dluma_ui_registry_initial_category_pending = 0;
    }
    if (g_dluma_ui_registry_category >= DLUMA_REGISTRY_CATEGORY_COUNT)
        g_dluma_ui_registry_category = DLUMA_REGISTRY_CATEGORY_ALL;
    if (!wanted_id[0])
        dluma_str_copy(
            wanted_id, DLUMA_ARRAY_COUNT(wanted_id),
            g_dluma_ui_registry_selected_by_category[
                g_dluma_ui_registry_category]);

    if (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ALL)
        dluma_ui_localize_text(
            "DLUMA_Mods_AllGroup", "All Mods",
            category, DLUMA_ARRAY_COUNT(category));
    else if (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_CODE)
        dluma_ui_localize_text(
            "DLUMA_Mods_CodeGroup", "Code Mods",
            category, DLUMA_ARRAY_COUNT(category));
    else if (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_LUA)
        dluma_ui_localize_text(
            "DLUMA_Mods_LuaGroup", "Lua Mods",
            category, DLUMA_ARRAY_COUNT(category));
    else
        dluma_ui_localize_text(
            "DLUMA_Mods_AssetGroup", "Asset Mods",
            category, DLUMA_ARRAY_COUNT(category));
    dluma_ui_set_text_element_text(g_dluma_ui_registry_category_title, category);

    if (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ALL)
        dluma_ui_registry_add_group_header(
            g_dluma_ui_registry_list,
            "DLUMA_Mods_CodeHeader", "CODE MODS");
    if (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ALL ||
        g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_CODE)
    {
        for (i = 0; i < g_dluma_ui_native_mod_count; ++i)
        {
            if (!dluma_ui_registry_show_native_provider(i))
                continue;
            if (dluma_ui_registry_add_option_row(
                    g_dluma_ui_registry_list,
                    g_dluma_ui_native_mods[i].name[0]
                        ? g_dluma_ui_native_mods[i].name
                        : g_dluma_ui_native_mods[i].id,
                    0, &g_dluma_ui_native_mods[i], 0,
                    g_dluma_ui_native_mod_revision))
            {
                mapping = &g_dluma_ui_registry_rows[
                    g_dluma_ui_registry_row_count - 1U];
                if (wanted_id[0] &&
                    dluma_stricmp(
                        wanted_id,
                        g_dluma_ui_native_mods[i].registry_key) == 0)
                    selection = mapping->list_index;
            }
        }
        for (i = 0; i < g_dluma_ui_managed_mod_count; ++i)
        {
            if (!dluma_ui_registry_show_managed_provider(i))
                continue;
            if (dluma_ui_registry_add_option_row(
                    g_dluma_ui_registry_list,
                    g_dluma_ui_managed_mods[i].name[0]
                        ? g_dluma_ui_managed_mods[i].name
                        : g_dluma_ui_managed_mods[i].id,
                    0, 0, &g_dluma_ui_managed_mods[i],
                    g_dluma_ui_managed_mod_revision))
            {
                mapping = &g_dluma_ui_registry_rows[
                    g_dluma_ui_registry_row_count - 1U];
                if (wanted_id[0] &&
                    dluma_stricmp(
                        wanted_id,
                        g_dluma_ui_managed_mods[i].registry_key) == 0)
                    selection = mapping->list_index;
            }
        }
    }

    if (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ALL)
        dluma_ui_registry_add_group_header(
            g_dluma_ui_registry_list,
            "DLUMA_Mods_LuaHeader", "LUA MODS");
    if (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ALL ||
        g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_LUA)
    {
        for (i = 0; i < g_dluma_ui_global_mod_count; ++i)
        {
            if (!dluma_ui_registry_show_lua_provider(i))
                continue;
            if (dluma_ui_registry_add_option_row(
                    g_dluma_ui_registry_list,
                    g_dluma_ui_global_mods[i].name[0]
                        ? g_dluma_ui_global_mods[i].name
                        : g_dluma_ui_global_mods[i].id,
                    &g_dluma_ui_global_mods[i], 0, 0,
                    g_dluma_ui_global_mod_revision))
            {
                mapping = &g_dluma_ui_registry_rows[
                    g_dluma_ui_registry_row_count - 1U];
                if (wanted_id[0] &&
                    dluma_stricmp(wanted_id,
                                g_dluma_ui_global_mods[i].registry_key) == 0)
                    selection = mapping->list_index;
                if (first_new_index < 0 &&
                    g_dluma_ui_global_mods[i].is_new)
                    first_new_index = mapping->list_index;
            }
        }
    }

    if (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ALL)
        dluma_ui_registry_add_group_header(
            g_dluma_ui_registry_list,
            "DLUMA_Mods_AssetHeader", "ASSET MODS");
    if (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ALL ||
        g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ASSET)
    {
        dluma_ui_registry_add_group_header(
            g_dluma_ui_registry_list,
            "DLUMA_AssetMods_Header", "ASSET OVERRIDES - HIGHEST FIRST");
        dluma_ui_registry_add_asset_rows(g_dluma_ui_registry_list, wanted_id, &selection);
        dluma_ui_registry_add_group_header(
            g_dluma_ui_registry_list,
            "DLUMA_Mods_MainMenuHeader", "MAIN MENU MODS");
        dluma_ui_registry_add_main_menu_rows(
            g_dluma_ui_registry_list, wanted_id, &selection);
    }
    if (g_dluma_new_global_focus_first_new &&
        (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ALL ||
         g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_LUA) &&
        first_new_index >= 0)
        selection = first_new_index;
    else if (selection < 0 && g_dluma_ui_registry_row_count)
        selection = g_dluma_ui_registry_rows[0].list_index;

    if (g_dluma_list_set_capacity)
        (void)g_dluma_list_set_capacity(
            g_dluma_ui_registry_list,
            (int)DLUMA_UI_REGISTRY_VISIBLE_ROWS, 1);
    if (selection >= 0)
        dluma_ui_list_set_selection(g_dluma_ui_registry_list, selection);
    g_dluma_new_global_focus_first_new = 0;
    (void)dluma_ui_list_get_selection(g_dluma_ui_registry_list);
    dluma_ui_registry_update_button_labels();
    dluma_log_u64(
        "INFO", "global_mod_registry_rows_added",
        g_dluma_ui_registry_row_count);
    dluma_log_pair(
        "INFO", "global_mod_registry_category",
        g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_ALL
            ? "all"
            : (g_dluma_ui_registry_category == DLUMA_REGISTRY_CATEGORY_CODE
                   ? "code"
                   : (g_dluma_ui_registry_category ==
                              DLUMA_REGISTRY_CATEGORY_LUA
                          ? "lua" : "asset")));
    dluma_log_pair("INFO", "global_mod_registry_selected_id",
                 g_dluma_ui_registry_selected_id[0]
                     ? g_dluma_ui_registry_selected_id
                     : "<none>");
    if (g_dluma_ui_global_mod_total > g_dluma_ui_global_mod_count)
        dluma_log_u64("WARN", "global_mod_registry_rows_truncated",
                    g_dluma_ui_global_mod_total - g_dluma_ui_global_mod_count);
    if (g_dluma_ui_native_mod_total > g_dluma_ui_native_mod_count)
        dluma_log_u64("WARN", "native_mod_registry_rows_truncated",
                    g_dluma_ui_native_mod_total - g_dluma_ui_native_mod_count);
    if (g_dluma_ui_managed_mod_total > g_dluma_ui_managed_mod_count)
        dluma_log_u64("WARN", "managed_mod_registry_rows_truncated",
                    g_dluma_ui_managed_mod_total -
                        g_dluma_ui_managed_mod_count);
    if (g_dluma_ui_custom_menu_candidate_total >
        g_dluma_ui_custom_menu_candidate_count)
        dluma_log_u64(
            "WARN", "asset_menu_registry_rows_truncated",
            g_dluma_ui_custom_menu_candidate_total -
                g_dluma_ui_custom_menu_candidate_count);
}

static void dluma_ui_registry_refresh_if_needed(void *screen)
{
    ULONGLONG revision = 0;
    unsigned int total;
    const char *selected_id;
    char restore_id[128];
    if (!screen || !dluma_ui_is_mods_registry_screen(screen))
        return;
    total = dluma_lua_snapshot_globals_with_revision(0, 0, 0, &revision);
    selected_id = dluma_ui_registry_current_selected_id();
    restore_id[0] = 0;
    if (selected_id)
        dluma_str_copy(restore_id, DLUMA_ARRAY_COUNT(restore_id), selected_id);
    {
        ULONGLONG native_revision = 0;
        unsigned int native_total = dluma_native_mods_snapshot(0, 0,
                                                               &native_revision);
        if (native_revision != g_dluma_ui_native_mod_revision ||
            native_total != g_dluma_ui_native_mod_total) {
            dluma_ui_registry_populate_list(screen, restore_id);
            return;
        }
    }
    {
        ULONGLONG managed_revision = 0;
        unsigned int managed_total = dluma_managed_mods_snapshot(
            0, 0, &managed_revision);
        if (managed_revision != g_dluma_ui_managed_mod_revision ||
            managed_total != g_dluma_ui_managed_mod_total) {
            dluma_ui_registry_populate_list(screen, restore_id);
            return;
        }
    }
    if (dluma_asset_mods_desired_revision() != g_dluma_ui_asset_mod_revision ||
        dluma_asset_mods_effective_revision() != g_dluma_ui_asset_effective_revision)
    {
        dluma_ui_registry_populate_list(screen, restore_id);
        return;
    }
    if (screen != g_dluma_ui_registry_screen ||
        revision != g_dluma_ui_global_mod_revision ||
        total != g_dluma_ui_global_mod_total)
    {
        dluma_ui_registry_populate_list(screen, restore_id);
    }
    else if (dluma_stricmp(g_dluma_ui_registry_selected_id,
                         restore_id) != 0)
    {
        dluma_ui_registry_update_button_labels();
        dluma_log_pair("INFO", "global_mod_registry_selected_id",
                     g_dluma_ui_registry_selected_id[0]
                         ? g_dluma_ui_registry_selected_id
                         : "<none>");
    }
}

static const char *dluma_ui_quest_log_state_text(unsigned int state)
{
    switch (state)
    {
    case 1:
        return "DECLARED";
    case 2:
        return "ACTIVE";
    case 3:
        return "COMPLETED";
    case 4:
        return "FAILED";
    default:
        return "UNKNOWN";
    }
}

static const char *dluma_ui_quest_log_native_state_text(unsigned int state)
{
    switch (state)
    {
    case 0:
        return "LUA ONLY";
    case 1:
        return "NATIVE GATED";
    case 2:
        return "NATIVE MIRROR";
    default:
        return "NATIVE UNKNOWN";
    }
}

static unsigned int dluma_ui_quest_log_utf8_width(
    const char *text, unsigned int available)
{
    unsigned char lead;
    if (!text || !available)
        return 0;
    lead = (unsigned char)text[0];
    if (lead <= 0x7Fu)
        return 1;
    if (lead >= 0xC2u && lead <= 0xDFu)
        return available >= 2u && ((unsigned char)text[1] & 0xC0u) == 0x80u
                   ? 2u
                   : 0;
    if (lead == 0xE0u)
        return available >= 3u && (unsigned char)text[1] >= 0xA0u &&
                       (unsigned char)text[1] <= 0xBFu &&
                       ((unsigned char)text[2] & 0xC0u) == 0x80u
                   ? 3u
                   : 0;
    if ((lead >= 0xE1u && lead <= 0xECu) ||
        (lead >= 0xEEu && lead <= 0xEFu))
        return available >= 3u && ((unsigned char)text[1] & 0xC0u) == 0x80u &&
                       ((unsigned char)text[2] & 0xC0u) == 0x80u
                   ? 3u
                   : 0;
    if (lead == 0xEDu)
        return available >= 3u && (unsigned char)text[1] >= 0x80u &&
                       (unsigned char)text[1] <= 0x9Fu &&
                       ((unsigned char)text[2] & 0xC0u) == 0x80u
                   ? 3u
                   : 0;
    if (lead == 0xF0u)
        return available >= 4u && (unsigned char)text[1] >= 0x90u &&
                       (unsigned char)text[1] <= 0xBFu &&
                       ((unsigned char)text[2] & 0xC0u) == 0x80u &&
                       ((unsigned char)text[3] & 0xC0u) == 0x80u
                   ? 4u
                   : 0;
    if (lead >= 0xF1u && lead <= 0xF3u)
        return available >= 4u && ((unsigned char)text[1] & 0xC0u) == 0x80u &&
                       ((unsigned char)text[2] & 0xC0u) == 0x80u &&
                       ((unsigned char)text[3] & 0xC0u) == 0x80u
                   ? 4u
                   : 0;
    if (lead == 0xF4u)
        return available >= 4u && (unsigned char)text[1] >= 0x80u &&
                       (unsigned char)text[1] <= 0x8Fu &&
                       ((unsigned char)text[2] & 0xC0u) == 0x80u &&
                       ((unsigned char)text[3] & 0xC0u) == 0x80u
                   ? 4u
                   : 0;
    return 0;
}

/* HTML escaping expands legal user-authored objective text by up to six bytes
 * per input byte.  Give each field a rendered-byte budget, never split a
 * UTF-8 sequence or entity, and leave the enclosing markup intact. */
static void dluma_ui_quest_log_html_append_escaped(
    char *out, unsigned int capacity, const char *text,
    unsigned int rendered_limit)
{
    unsigned int used;
    unsigned int consumed = 0;
    unsigned int rendered = 0;
    int truncated = 0;
    if (!out || !capacity || !text)
        return;
    used = (unsigned int)strlen(out);
    if (used >= capacity)
    {
        out[capacity - 1u] = 0;
        return;
    }
    while (text[consumed] && consumed < DLUMA_UI_QUEST_FIELD_TEXT_LIMIT)
    {
        const char *encoded = 0;
        unsigned int encoded_length = 0;
        unsigned int source_width = 1;
        switch (text[consumed])
        {
        case '&':
            encoded = "&amp;";
            encoded_length = 5;
            break;
        case '<':
            encoded = "&lt;";
            encoded_length = 4;
            break;
        case '>':
            encoded = "&gt;";
            encoded_length = 4;
            break;
        case '"':
            encoded = "&quot;";
            encoded_length = 6;
            break;
        case '\r':
            ++consumed;
            continue;
        case '\n':
            encoded = "<br>";
            encoded_length = 4;
            break;
        default:
            source_width = dluma_ui_quest_log_utf8_width(
                text + consumed,
                DLUMA_UI_QUEST_FIELD_TEXT_LIMIT - consumed);
            if (!source_width)
            {
                truncated = 1;
                goto finished;
            }
            encoded = text + consumed;
            encoded_length = source_width;
            break;
        }
        if (rendered + encoded_length > rendered_limit ||
            used + encoded_length >= capacity)
        {
            truncated = 1;
            break;
        }
        memcpy(out + used, encoded, encoded_length);
        used += encoded_length;
        rendered += encoded_length;
        out[used] = 0;
        consumed += source_width;
    }
    if (text[consumed])
        truncated = 1;
finished:
    if (truncated && rendered + 3u <= rendered_limit && used + 3u < capacity)
    {
        memcpy(out + used, "...", 3u);
        out[used + 3u] = 0;
    }
}

static void dluma_ui_quest_log_snapshot(void)
{
    unsigned int copied;
    unsigned int total = 0;
    ULONGLONG revision = 0;
    int archived = 0;

    memset(g_dluma_ui_quests, 0, sizeof(g_dluma_ui_quests));
    copied = dluma_lua_runtime_snapshot_quests(
        g_dluma_ui_quests, DLUMA_UI_MAX_QUESTS, &total, &revision, &archived);
    if (copied > DLUMA_UI_MAX_QUESTS)
        copied = DLUMA_UI_MAX_QUESTS;
    if (total < copied)
        total = copied;
    g_dluma_ui_quest_count = copied;
    g_dluma_ui_quest_total = total;
    g_dluma_ui_quest_revision = revision;
    g_dluma_ui_quest_archive = archived ? 1 : 0;
}

static int dluma_ui_quest_log_validate_list(void *list)
{
    void *primary;
    void *secondary;
    void *expected_primary;
    void *expected_secondary;

    if (!list || !g_dluma_registry_gamedll_base ||
        !dluma_is_readable(list, sizeof(void *)) ||
        !dluma_is_readable((BYTE *)list + DLUMA_UI_LIST_INTERFACE_OFFSET,
                         sizeof(void *)))
        return 0;
    primary = *(void **)list;
    secondary = *(void **)((BYTE *)list + DLUMA_UI_LIST_INTERFACE_OFFSET);
    expected_primary = g_dluma_registry_gamedll_base +
                       DLUMA_DEVTOOLS_UI_LIST_VTABLE_RVA;
    expected_secondary = g_dluma_registry_gamedll_base +
                         DLUMA_DEVTOOLS_UI_LIST_INTERFACE_VTABLE_RVA;
    if (primary != expected_primary || secondary != expected_secondary)
    {
        dluma_log_line("WARN", "Quest Log list contract did not match the validated UIListBox layout; the loader-owned page remains inert.");
        return 0;
    }
    return 1;
}

static int dluma_ui_quest_log_resolve_controls(void *screen)
{
    void *list;

    if (!screen || !dluma_ui_is_validated_quest_log_screen(screen))
        return 0;
    g_dluma_ui_quest_log_status =
        dluma_ui_find_required_child(screen, "T_QuestLogStatus");
    list = dluma_ui_find_required_child(screen, "L_Maps");
    if (!dluma_ui_quest_log_validate_list(list))
    {
        dluma_ui_set_text_element_text(
            g_dluma_ui_quest_log_status,
            "QUEST LOG IS UNAVAILABLE ON THIS UI BUILD.");
        return 0;
    }
    g_dluma_ui_quest_log_screen = screen;
    g_dluma_ui_quest_log_list = list;
    g_dluma_ui_quest_log_refresh_button =
        dluma_ui_find_required_child(screen, "B_Start");
    g_dluma_ui_quest_log_secondary_refresh_button =
        dluma_ui_find_required_child(screen, "B_Workshop");
    g_dluma_ui_quest_log_back_button =
        dluma_ui_find_required_child(screen, "B_Back");
    if (!g_dluma_ui_quest_log_status ||
        !g_dluma_ui_quest_log_refresh_button ||
        !g_dluma_ui_quest_log_secondary_refresh_button ||
        !g_dluma_ui_quest_log_back_button)
    {
        dluma_log_line("WARN", "Quest Log XUI is missing its required loader-owned controls.");
        return 0;
    }
    return 1;
}

static void dluma_ui_quest_log_build_row(
    char *row, unsigned int capacity, const DlumaLuaQuestUiSnapshot *quest)
{
    const char *state_color;
    const char *title;
    const char *phase;

    if (!row || !capacity || !quest)
        return;
    title = quest->title[0] ? quest->title : quest->id;
    phase = quest->phase_title[0] ? quest->phase_title : quest->phase_id;
    state_color = quest->active ? "#F28C18" : (quest->state == 3 ? "#00FF00" : (quest->state == 4 ? "#FF0000" : "#949494"));
    row[0] = 0;
    dluma_str_append(row, capacity,
                   "<table width=\"100%\"><tr><td width=\"67%\"><font color=\"");
    dluma_str_append(row, capacity, state_color);
    dluma_str_append(row, capacity, "\">[ ");
    dluma_str_append(row, capacity, dluma_ui_quest_log_state_text(quest->state));
    dluma_str_append(row, capacity, " ]</font> ");
    dluma_ui_quest_log_html_append_escaped(
        row, capacity, title, DLUMA_UI_QUEST_ROW_TITLE_RENDER_LIMIT);
    dluma_str_append(row, capacity,
                   " <font color=\"#949494\" size=\"8px\">(");
    dluma_ui_quest_log_html_append_escaped(
        row, capacity, quest->id, DLUMA_UI_QUEST_ROW_IDENTIFIER_RENDER_LIMIT);
    dluma_str_append(row, capacity,
                   ")</font> <font color=\"#949494\" size=\"8px\">SCRIPT: ");
    dluma_ui_quest_log_html_append_escaped(
        row, capacity,
        quest->script_id[0] ? quest->script_id : "(UNKNOWN)",
        DLUMA_UI_QUEST_ROW_IDENTIFIER_RENDER_LIMIT);
    dluma_str_append(row, capacity,
                   "</font></td><td width=\"33%\" align=\"center\">");
    dluma_str_append(row, capacity, dluma_ui_quest_log_native_state_text(quest->native_state));
    dluma_str_append(row, capacity,
                   "</td></tr><tr><td colspan=\"2\"><font color=\"#DD8B1B\">PHASE: </font>");
    dluma_ui_quest_log_html_append_escaped(
        row, capacity, phase[0] ? phase : "(NONE)",
        DLUMA_UI_QUEST_ROW_PHASE_RENDER_LIMIT);
    if (quest->phase_id[0])
    {
        dluma_str_append(row, capacity, " <font color=\"#949494\" size=\"8px\">(");
        dluma_ui_quest_log_html_append_escaped(
            row, capacity, quest->phase_id,
            DLUMA_UI_QUEST_ROW_IDENTIFIER_RENDER_LIMIT);
        dluma_str_append(row, capacity, ")</font>");
    }
    dluma_str_append(row, capacity,
                   "</td></tr><tr><td colspan=\"2\"><font color=\"#949494\">OBJECTIVES: </font>");
    dluma_ui_quest_log_html_append_escaped(
        row, capacity,
        quest->objective_summary[0]
            ? quest->objective_summary
            : "(NO ACTIVE OBJECTIVES)",
        DLUMA_UI_QUEST_ROW_OBJECTIVES_RENDER_LIMIT);
    dluma_str_append(row, capacity, "</td></tr></table>");
}

static void dluma_ui_quest_log_build_empty_row(char *row, unsigned int capacity)
{
    if (!row || !capacity)
        return;
    row[0] = 0;
    dluma_str_append(row, capacity,
                   "<table width=\"100%\"><tr><td><font color=\"#949494\">NO LUA QUESTS ARE CURRENTLY AVAILABLE.</font></td></tr></table>");
}

static void *dluma_ui_quest_log_add_row(
    void *list, const char *text, const DlumaLuaQuestUiSnapshot *quest)
{
    WCHAR row_storage[DLUMA_UI_WIDE_ROW_CAPACITY];
    DlumaTtlWideString row_text;
    DlumaTtlString *default_template;
    DlumaQuestLogRowMap *mapping = 0;
    void *item;

    if (!list || !text || !g_dluma_list_add_item || !g_dluma_registry_gamedll_base)
        return 0;
    if (!dluma_ttl_wide_string_init_utf8(
            &row_text, row_storage, DLUMA_ARRAY_COUNT(row_storage), text))
    {
        dluma_log_line("WARN", "Quest Log row text conversion failed.");
        return 0;
    }
    default_template = (DlumaTtlString *)(g_dluma_registry_gamedll_base +
                                        DLUMA_DEVTOOLS_DEFAULT_LIST_TEMPLATE_RVA);
    if (!dluma_is_readable(default_template, sizeof(*default_template)))
        return 0;
    item = g_dluma_list_add_item(list, &row_text, 0,
                               default_template, 1, -1);
    if (item && g_dluma_set_element_can_focus)
        g_dluma_set_element_can_focus(item, 1);
    if (item && quest && g_dluma_ui_quest_row_count < DLUMA_UI_MAX_QUESTS)
    {
        mapping = &g_dluma_ui_quest_rows[g_dluma_ui_quest_row_count++];
        mapping->item = item;
        dluma_str_copy(mapping->id, DLUMA_ARRAY_COUNT(mapping->id), quest->id);
    }
    return item;
}

static void dluma_ui_quest_log_update_status(void)
{
    char status[DLUMA_UI_WIDE_LABEL_CAPACITY];
    char total[32];

    if (!g_dluma_ui_quest_total)
    {
        dluma_ui_set_text_element_text(
            g_dluma_ui_quest_log_status,
            "NO LUA QUESTS ARE CURRENTLY AVAILABLE.");
        return;
    }
    status[0] = 0;
    if (g_dluma_ui_quest_total > g_dluma_ui_quest_count)
    {
        dluma_u64_to_text(g_dluma_ui_quest_count, total, DLUMA_ARRAY_COUNT(total));
        dluma_str_append(status, DLUMA_ARRAY_COUNT(status), "SHOWING FIRST ");
        dluma_str_append(status, DLUMA_ARRAY_COUNT(status), total);
        dluma_str_append(status, DLUMA_ARRAY_COUNT(status), " QUESTS. ");
    }
    dluma_str_append(status, DLUMA_ARRAY_COUNT(status),
                   g_dluma_ui_quest_archive
                       ? "ARCHIVED LAST-MAP SNAPSHOT. READ-ONLY; NO LIVE QUEST STATE."
                       : "LIVE READ-ONLY SNAPSHOT. REFRESH TO CHECK CURRENT QUEST STATE.");
    dluma_ui_set_text_element_text(g_dluma_ui_quest_log_status, status);
}

static void dluma_ui_quest_log_populate_current_snapshot(void *screen)
{
    unsigned int i;
    unsigned int rows_added = 0;
    int selection = -1;
    char row[DLUMA_UI_WIDE_ROW_CAPACITY];

    if (!screen || !dluma_ui_is_validated_quest_log_screen(screen) ||
        !g_dluma_list_clear || !g_dluma_list_add_item ||
        !dluma_ui_quest_log_resolve_controls(screen))
        return;
    g_dluma_list_clear((BYTE *)g_dluma_ui_quest_log_list +
                     DLUMA_UI_LIST_INTERFACE_OFFSET);
    memset(g_dluma_ui_quest_rows, 0, sizeof(g_dluma_ui_quest_rows));
    g_dluma_ui_quest_row_count = 0;
    if (!g_dluma_ui_quest_count)
    {
        dluma_ui_quest_log_build_empty_row(row, DLUMA_ARRAY_COUNT(row));
        if (dluma_ui_quest_log_add_row(g_dluma_ui_quest_log_list, row, 0))
            rows_added = 1;
    }
    else
    {
        for (i = 0; i < g_dluma_ui_quest_count; ++i)
        {
            dluma_ui_quest_log_build_row(
                row, DLUMA_ARRAY_COUNT(row), &g_dluma_ui_quests[i]);
            if (dluma_ui_quest_log_add_row(
                    g_dluma_ui_quest_log_list, row, &g_dluma_ui_quests[i]))
            {
                if (g_dluma_ui_quests[i].active)
                    selection = (int)rows_added;
                ++rows_added;
            }
        }
    }
    if (selection < 0 && rows_added)
        selection = 0;
    if (selection >= 0)
        dluma_ui_list_set_selection(g_dluma_ui_quest_log_list, selection);
    dluma_ui_quest_log_update_status();
    dluma_log_u64("INFO", "quest_log_rows_added", rows_added);
    if (g_dluma_ui_quest_total > g_dluma_ui_quest_count)
        dluma_log_u64("WARN", "quest_log_rows_truncated",
                    g_dluma_ui_quest_total - g_dluma_ui_quest_count);
}

static void dluma_ui_quest_log_populate_list(void *screen)
{
    dluma_ui_quest_log_snapshot();
    dluma_ui_quest_log_populate_current_snapshot(screen);
}

static void dluma_ui_quest_log_refresh_if_needed(void *screen)
{
    unsigned int previous_total;
    unsigned int previous_count;
    ULONGLONG previous_revision;
    unsigned char previous_archive;
    ULONGLONG now;

    if (!screen || !dluma_ui_is_validated_quest_log_screen(screen))
        return;
    now = GetTickCount64();
    if (g_dluma_ui_quest_log_last_refresh_ms &&
        now - g_dluma_ui_quest_log_last_refresh_ms < DLUMA_UI_QUEST_REFRESH_MS)
        return;
    g_dluma_ui_quest_log_last_refresh_ms = now;
    previous_total = g_dluma_ui_quest_total;
    previous_count = g_dluma_ui_quest_count;
    previous_revision = g_dluma_ui_quest_revision;
    previous_archive = g_dluma_ui_quest_archive;
    dluma_ui_quest_log_snapshot();
    if (screen != g_dluma_ui_quest_log_screen ||
        previous_total != g_dluma_ui_quest_total ||
        previous_count != g_dluma_ui_quest_count ||
        previous_revision != g_dluma_ui_quest_revision ||
        previous_archive != g_dluma_ui_quest_archive)
        dluma_ui_quest_log_populate_current_snapshot(screen);
}

static int dluma_ui_workshop_validate_list(void *list)
{
    void *primary;
    void *secondary;
    if (!list || !g_dluma_registry_gamedll_base ||
        !dluma_is_readable(list, sizeof(void *)) ||
        !dluma_is_readable((BYTE *)list + DLUMA_UI_LIST_INTERFACE_OFFSET,
                         sizeof(void *)))
        return 0;
    primary = *(void **)list;
    secondary = *(void **)((BYTE *)list + DLUMA_UI_LIST_INTERFACE_OFFSET);
    return primary == g_dluma_registry_gamedll_base +
                          DLUMA_DEVTOOLS_UI_LIST_VTABLE_RVA &&
           secondary == g_dluma_registry_gamedll_base +
                            DLUMA_DEVTOOLS_UI_LIST_INTERFACE_VTABLE_RVA;
}

static int dluma_ui_workshop_list_count(void *list)
{
    void **vtable;
    int count;
    typedef int(__fastcall *DlumaListVirtualCountFn)(void *list_object);
    if (!dluma_ui_workshop_validate_list(list))
        return 0;
    vtable = *(void ***)list;
    if (!dluma_is_readable(vtable + 2352U / sizeof(void *), sizeof(void *)) ||
        !vtable[2352U / sizeof(void *)])
        return 0;
    count = ((DlumaListVirtualCountFn)vtable[2352U / sizeof(void *)])(list);
    return count >= 0 && count <= 1000 ? count : 0;
}

static void *dluma_ui_workshop_list_item(void *list, unsigned int index)
{
    void **vtable;
    typedef void *(__fastcall *DlumaListVirtualItemFn)(
        void *list_object, unsigned int item_index);
    if (!dluma_ui_workshop_validate_list(list))
        return 0;
    vtable = *(void ***)list;
    if (!dluma_is_readable(vtable + 2216U / sizeof(void *), sizeof(void *)) ||
        !vtable[2216U / sizeof(void *)])
        return 0;
    return ((DlumaListVirtualItemFn)vtable[2216U / sizeof(void *)])(
        list, index);
}

static int dluma_ui_workshop_copy_ttl_string(
    const DlumaTtlString *value, char *out, unsigned int capacity)
{
    unsigned int count;
    if (out && capacity) out[0] = 0;
    if (!value || !out || capacity < 2 ||
        !dluma_is_readable(value, sizeof(*value)) ||
        !value->data || !value->size || value->size >= capacity ||
        value->size > DLUMA_WORKSHOP_MENU_TITLE_CAPACITY - 1U ||
        !dluma_is_readable(value->data, value->size))
        return 0;
    count = value->size;
    memcpy(out, value->data, count);
    out[count] = 0;
    return 1;
}

static int dluma_ui_workshop_copy_ttl_path(
    const DlumaTtlString *value, char *out, unsigned int capacity)
{
    unsigned int index;
    if (out && capacity) out[0] = 0;
    if (!value || !out || capacity < 2U ||
        !dluma_is_readable(value, sizeof(*value)) ||
        !value->data || !value->size ||
        value->size >= capacity ||
        !dluma_is_readable(value->data, value->size))
        return 0;
    for (index = 0; index < value->size; ++index)
        if (!value->data[index])
            return 0;
    memcpy(out, value->data, value->size);
    out[value->size] = 0;
    return 1;
}

static int dluma_ui_workshop_read_row(
    void *list, unsigned int index, DlumaWorkshopMenuRowView *row)
{
    void *item;
    void *data;
    void *payload;
    if (!row)
        return 0;
    memset(row, 0, sizeof(*row));
    item = dluma_ui_workshop_list_item(list, index);
    if (!item || !dluma_is_readable((BYTE *)item + 56U, sizeof(void *)))
        return 0;
    data = *(void **)((BYTE *)item + 56U);
    if (!data || !dluma_is_readable(data, 24U) ||
        *(void **)data != g_dluma_registry_gamedll_base +
                             DLUMA_DEVTOOLS_UI_DATA_VOID_VTABLE_RVA)
        return 0;
    payload = *(void **)((BYTE *)data + 16U);
    if (!payload || !dluma_is_readable(payload, 168U))
        return 0;
    row->item = item;
    row->payload = payload;
    row->type = *(const int *)payload;
    row->divider = row->type == 0 &&
                   *(const unsigned char *)((const BYTE *)payload + 4U) != 0;
    if (row->type == 2)
    {
        row->subscribed = 1;
        row->published_id =
            *(const ULONGLONG *)((const BYTE *)payload + 160U);
    }
    else if (row->type == 1)
    {
        /* The native local-project payload embeds the copied 144-byte
         * project record at +0x10.  Its first field is the optional published
         * id and its first ttl::string at +0x18 is the exact native title. */
        row->published_id =
            *(const ULONGLONG *)((const BYTE *)payload + 16U);
        (void)dluma_ui_workshop_copy_ttl_string(
            (const DlumaTtlString *)((const BYTE *)payload + 24U),
            row->native_title, DLUMA_ARRAY_COUNT(row->native_title));
    }
    else if (!row->divider)
    {
        return 0;
    }
    if (row->published_id)
        dluma_u64_to_text(row->published_id, row->workshop_id,
                        DLUMA_ARRAY_COUNT(row->workshop_id));
    return 1;
}

static void *dluma_ui_workshop_screen_list(void *screen)
{
    void *list;
    if (!screen ||
        !dluma_is_readable((const BYTE *)screen +
                             DLUMA_DEVTOOLS_WORKSHOP_LIST_OFFSET,
                         sizeof(void *)))
        return 0;
    list = *(void **)((BYTE *)screen + DLUMA_DEVTOOLS_WORKSHOP_LIST_OFFSET);
    return dluma_ui_workshop_validate_list(list) ? list : 0;
}

static int dluma_ui_workshop_get_focus(void *list, int *focused)
{
    void **vtable;
    typedef int(__fastcall *DlumaWorkshopFocusGetFn)(void *list_object);
    if (focused) *focused = -1;
    if (!focused || !dluma_ui_workshop_validate_list(list))
        return 0;
    vtable = *(void ***)list;
    if (!dluma_is_readable(
            vtable + DLUMA_DEVTOOLS_WORKSHOP_FOCUS_GET_VTABLE_OFFSET /
                         sizeof(void *),
            sizeof(void *)) ||
        vtable[DLUMA_DEVTOOLS_WORKSHOP_FOCUS_GET_VTABLE_OFFSET /
               sizeof(void *)] !=
            g_dluma_registry_gamedll_base +
                DLUMA_DEVTOOLS_WORKSHOP_FOCUS_GET_RVA)
        return 0;
    *focused = ((DlumaWorkshopFocusGetFn)
        vtable[DLUMA_DEVTOOLS_WORKSHOP_FOCUS_GET_VTABLE_OFFSET /
               sizeof(void *)])(list);
    return 1;
}

