static int dluma_ui_workshop_row_rejected_by_game_fix(
    const DlumaWorkshopMenuRowView *row)
{
    DlumaWorkshopMenuItem metadata;
    int found;
    if (!row || row->divider ||
        (row->type != 1 && row->type != 2))
        return 0;
    found = dluma_workshop_menu_find_metadata(
        row->workshop_id, row->native_title, row->subscribed, &metadata);
    if (!found && row->native_title[0])
        found = dluma_workshop_menu_find_metadata(
            "", row->native_title, row->subscribed, &metadata);
    if (found && metadata.exact_project && metadata.project_root[0] &&
        dluma_custom_main_menu_project_marked(metadata.project_root))
        return 1;
    return g_dluma.config.hide_invalid_workshop_projects_enabled &&
           found && metadata.exact_project && !metadata.has_data_maps;
}

static unsigned int dluma_ui_workshop_filter_invalid_projects(void *list)
{
    int count;
    int i;
    unsigned int removed = 0;
    if (!g_dluma_list_remove_item || !dluma_ui_workshop_validate_list(list))
        return 0;
    count = dluma_ui_workshop_list_count(list);
    /*
     * FillMaps has finished owning every UIDataVoid payload at this point,
     * but no loader presentation pass has run. Remove rejected projects in
     * reverse order through UIListBox's exact-build remove-and-destroy API so
     * the native array, paging state, row lifetimes, and positions remain
     * authoritative and compact.
     */
    for (i = count; i > 0; --i)
    {
        DlumaWorkshopMenuRowView row;
        const int index = i - 1;
        if (!dluma_ui_workshop_read_row(
                list, (unsigned int)index, &row) ||
            !dluma_ui_workshop_row_rejected_by_game_fix(&row))
            continue;
        (void)g_dluma_list_remove_item(list, index, 1);
        ++removed;
    }
    if (removed)
        dluma_log_u64("INFO", "workshop_invalid_projects_filtered",
                    (ULONGLONG)removed);
    return removed;
}

static int dluma_ui_workshop_is_selectable_index(
    void *list, int index)
{
    DlumaWorkshopMenuRowView row;
    int count = dluma_ui_workshop_list_count(list);
    return index >= 0 && index < count &&
           dluma_ui_workshop_read_row(
               list, (unsigned int)index, &row) &&
           !row.divider;
}

static int dluma_ui_workshop_nearest_selectable_index(
    void *list, int requested)
{
    int count = dluma_ui_workshop_list_count(list);
    int distance;
    if (count <= 0)
        return -1;
    if (requested < 0)
        requested = 0;
    if (requested >= count)
        requested = count - 1;
    if (dluma_ui_workshop_is_selectable_index(list, requested))
        return requested;
    for (distance = 1; distance < count; ++distance)
    {
        int below = requested + distance;
        int above = requested - distance;
        if (below < count &&
            dluma_ui_workshop_is_selectable_index(list, below))
            return below;
        if (above >= 0 &&
            dluma_ui_workshop_is_selectable_index(list, above))
            return above;
    }
    return -1;
}

static void dluma_ui_workshop_capture_refresh_identity(
    void *list, int index, DlumaWorkshopRefreshIdentity *identity)
{
    DlumaWorkshopMenuRowView row;
    DlumaWorkshopMenuItem metadata;
    int count;
    if (!identity)
        return;
    memset(identity, 0, sizeof(*identity));
    identity->index = index;
    identity->identity_kind = DLUMA_WORKSHOP_REFRESH_IDENTITY_INDEX;
    count = dluma_ui_workshop_list_count(list);
    if (index < 0 || index >= count)
        return;
    if (!dluma_ui_workshop_read_row(
            list, (unsigned int)index, &row) || row.divider)
        return;
    identity->had_index = 1;
    identity->selectable = 1;
    if (row.published_id)
    {
        identity->published_id = row.published_id;
        identity->identity_kind =
            DLUMA_WORKSHOP_REFRESH_IDENTITY_PUBLISHED_ID;
        return;
    }
    if (row.type == 1 &&
        dluma_workshop_menu_find_metadata(
            "", row.native_title, 0, &metadata) &&
        metadata.exact_project && metadata.project_root[0])
    {
        dluma_wstr_copy(identity->project_root,
                      DLUMA_ARRAY_COUNT(identity->project_root),
                      metadata.project_root);
        identity->identity_kind =
            DLUMA_WORKSHOP_REFRESH_IDENTITY_PROJECT_ROOT;
    }
}

static int dluma_ui_workshop_row_matches_refresh(
    const DlumaWorkshopMenuRowView *row,
    const DlumaWorkshopRefreshIdentity *identity)
{
    DlumaWorkshopMenuItem metadata;
    if (!row || !identity || row->divider)
        return 0;
    if (identity->identity_kind ==
            DLUMA_WORKSHOP_REFRESH_IDENTITY_PUBLISHED_ID)
        return identity->published_id &&
               row->published_id == identity->published_id;
    if (identity->identity_kind ==
            DLUMA_WORKSHOP_REFRESH_IDENTITY_PROJECT_ROOT &&
        row->type == 1 && !row->published_id &&
        dluma_workshop_menu_find_metadata(
            "", row->native_title, 0, &metadata) &&
        metadata.exact_project && metadata.project_root[0])
        return dluma_wstricmp(metadata.project_root,
                            identity->project_root) == 0;
    return 0;
}

static int dluma_ui_workshop_restore_refresh_identity(
    void *list, const DlumaWorkshopRefreshIdentity *identity)
{
    unsigned char selectable[1000];
    unsigned char identity_matches[1000];
    int count;
    int i;
    if (!list || !identity || !identity->had_index)
        return -1;
    count = dluma_ui_workshop_list_count(list);
    memset(selectable, 0, sizeof(selectable));
    memset(identity_matches, 0, sizeof(identity_matches));
    for (i = 0; i < count; ++i)
    {
        DlumaWorkshopMenuRowView row;
        if (dluma_ui_workshop_read_row(
                list, (unsigned int)i, &row) && !row.divider)
        {
            selectable[i] = 1;
            if (identity->identity_kind !=
                    DLUMA_WORKSHOP_REFRESH_IDENTITY_INDEX &&
                dluma_ui_workshop_row_matches_refresh(&row, identity))
                identity_matches[i] = 1;
        }
    }
    return dluma_workshop_refresh_choose_index(
        selectable,
        identity->identity_kind == DLUMA_WORKSHOP_REFRESH_IDENTITY_INDEX
            ? 0 : identity_matches,
        (unsigned int)count, identity->index);
}

static int dluma_ui_workshop_active_index(void *list)
{
    int count = dluma_ui_workshop_list_count(list);
    int focused = -1;
    int selected;
    int repaired;
    (void)dluma_ui_workshop_get_focus(list, &focused);
    if (focused >= 0 && focused < count &&
        dluma_ui_workshop_is_selectable_index(list, focused))
        return focused;
    selected = dluma_ui_list_get_selection(list);
    if (selected >= 0 && selected < count &&
        dluma_ui_workshop_is_selectable_index(list, selected))
        return selected;
    repaired = dluma_ui_workshop_nearest_selectable_index(
        list, focused >= 0 ? focused : selected);
    if (repaired >= 0)
        return repaired;
    return -1;
}

static int dluma_ui_workshop_ensure_initial_focus(void *screen)
{
    void *list;
    int selected;
    int focused = -1;
    int first_visible = -1;
    int target;
    if (!screen || !g_dluma_list_set_selection ||
        !g_dluma_set_element_focus)
        return -1;
    list = dluma_ui_workshop_screen_list(screen);
    if (!list)
        return -1;
    selected = dluma_ui_list_get_selection(list);
    (void)dluma_ui_workshop_get_focus(list, &focused);
    if (dluma_ui_workshop_is_selectable_index(list, focused))
        target = focused;
    else if (dluma_ui_workshop_is_selectable_index(list, selected))
        target = selected;
    else
        target = dluma_ui_workshop_nearest_selectable_index(
            list, focused >= 0 ? focused : selected);
    if (target < 0)
        return -1;
    g_dluma_list_set_selection(
        (BYTE *)list + DLUMA_UI_LIST_INTERFACE_OFFSET, target, 0);
    (void)dluma_ui_workshop_set_focus(list, target, 1);
    if (!dluma_ui_workshop_get_first_visible(list, &first_visible) ||
        first_visible < 0 ||
        target < first_visible)
        (void)dluma_ui_workshop_set_first_visible(list, target);
    g_dluma_set_element_focus(list, 1, 0);
    g_dluma_workshop_initial_focus_index = target;
    dluma_atomic_exchange(&g_dluma_workshop_initial_focus_pending, 1);
    return target;
}

static void dluma_ui_workshop_capture_refresh_state(
    void *list, DlumaWorkshopRefreshState *state)
{
    int selected = -1;
    int focused = -1;
    int first_visible = -1;
    if (!state)
        return;
    memset(state, 0, sizeof(*state));
    state->selected.index = -1;
    state->focused.index = -1;
    state->first_visible = -1;
    state->active_index = -1;
    state->active_relative_offset = -1;
    if (!list)
        return;
    selected = dluma_ui_list_get_selection(list);
    (void)dluma_ui_workshop_get_focus(list, &focused);
    dluma_ui_workshop_capture_refresh_identity(
        list, selected, &state->selected);
    dluma_ui_workshop_capture_refresh_identity(
        list, focused, &state->focused);
    state->active_index = state->focused.selectable
                              ? state->focused.index
                              : (state->selected.selectable
                                     ? state->selected.index : -1);
    if (dluma_ui_workshop_get_first_visible(list, &first_visible) &&
        first_visible >= 0)
    {
        state->first_visible = first_visible;
        state->had_first_visible = 1;
        if (state->active_index >= first_visible)
            state->active_relative_offset =
                state->active_index - first_visible;
    }
}

static int dluma_ui_workshop_restore_refresh_state(
    void *list, const DlumaWorkshopRefreshState *state,
    int *selected_out, int *focused_out, int *first_visible_out)
{
    int selected = -1;
    int focused = -1;
    int active;
    int first_visible = -1;
    int count;
    if (selected_out) *selected_out = -1;
    if (focused_out) *focused_out = -1;
    if (first_visible_out) *first_visible_out = -1;
    if (!list || !state)
        return -1;
    count = dluma_ui_workshop_list_count(list);
    selected = dluma_ui_workshop_restore_refresh_identity(
        list, &state->selected);
    if (selected >= 0 && g_dluma_list_set_selection)
        g_dluma_list_set_selection(
            (BYTE *)list + DLUMA_UI_LIST_INTERFACE_OFFSET, selected, 0);
    focused = dluma_ui_workshop_restore_refresh_identity(
        list, &state->focused);
    if (focused >= 0)
        (void)dluma_ui_workshop_set_focus(list, focused, 0);
    active = focused >= 0 ? focused : selected;
    if (state->had_first_visible && count > 0)
    {
        first_visible = dluma_workshop_refresh_clamp_first_visible(
            state->first_visible, (unsigned int)count);
        if (first_visible >= 0)
            (void)dluma_ui_workshop_set_first_visible(
                list, first_visible);
    }
    if (first_visible < 0)
        (void)dluma_ui_workshop_get_first_visible(
            list, &first_visible);
    if (selected_out) *selected_out = selected;
    if (focused_out) *focused_out = focused;
    if (first_visible_out) *first_visible_out = first_visible;
    return active;
}

static int dluma_ui_workshop_resolve_row(
    const DlumaWorkshopMenuRowView *row,
    int request_remote,
    DlumaWorkshopMenuItem *metadata,
    int *has_metadata,
    DlumaWorkshopMenuRemoteItem *remote,
    int *has_remote)
{
    int metadata_found = 0;
    int remote_found = 0;
    const char *remote_id = "";
    if (metadata) memset(metadata, 0, sizeof(*metadata));
    if (remote) memset(remote, 0, sizeof(*remote));
    if (has_metadata) *has_metadata = 0;
    if (has_remote) *has_remote = 0;
    if (!row || row->divider || (row->type != 1 && row->type != 2))
        return 0;
    if (metadata)
    {
        metadata_found = dluma_workshop_menu_find_metadata(
            row->workshop_id, row->native_title, row->subscribed, metadata);
        if (!metadata_found && row->native_title[0])
            metadata_found = dluma_workshop_menu_find_metadata(
                "", row->native_title, row->subscribed, metadata);
    }
    if (row->subscribed && row->workshop_id[0])
        remote_id = row->workshop_id;
    else if (metadata_found && metadata && metadata->workshop_id[0])
        remote_id = metadata->workshop_id;
    if (remote_id[0])
    {
        if (request_remote)
            dluma_workshop_menu_request_remote(remote_id);
        if (remote)
            remote_found = dluma_workshop_menu_get_remote(
                remote_id, remote);
    }
    if (has_metadata) *has_metadata = metadata_found;
    if (has_remote) *has_remote = remote_found;
    return 1;
}

static const char *dluma_ui_workshop_row_title(
    const DlumaWorkshopMenuRowView *row,
    const DlumaWorkshopMenuItem *metadata,
    int has_metadata,
    const DlumaWorkshopMenuRemoteItem *remote,
    int has_remote)
{
    if (has_metadata && metadata->title_from_desc && metadata->title[0])
        return metadata->title;
    if (has_remote && remote->details_ready && remote->title[0])
        return remote->title;
    if (has_metadata && metadata->title[0])
        return metadata->title;
    if (row && row->native_title[0])
        return row->native_title;
    return "Unnamed map";
}

static const char *dluma_ui_workshop_row_id(
    const DlumaWorkshopMenuRowView *row,
    const DlumaWorkshopMenuItem *metadata,
    int has_metadata)
{
    if (row && row->subscribed && row->workshop_id[0])
        return row->workshop_id;
    if (has_metadata && metadata->workshop_id[0])
        return metadata->workshop_id;
    return "LOCAL";
}

static int dluma_ui_workshop_item_has_texture(void *item);

static int dluma_ui_workshop_bind_row_interaction_exports(void)
{
    static const BYTE process_inputs_prefix[] = {
        0x48, 0x83, 0xec, 0x28, 0x4c, 0x8b, 0x41, 0x18,
        0x4d, 0x85, 0xc0, 0x74, 0x2e, 0x41, 0x0f, 0xb6,
        0x80, 0x58, 0x02, 0x00, 0x00, 0x24, 0x01, 0x3a
    };
    static const BYTE set_can_focus_prefix[] = {
        0x48, 0x83, 0xec, 0x28, 0x48, 0x8b, 0x49, 0x18,
        0x48, 0x85, 0xc9, 0x74, 0x05, 0xe8, 0x9e, 0x1e,
        0x04, 0x00, 0x48, 0x83, 0xc4, 0x28, 0xc3, 0xcc
    };
    HMODULE engine;
    if (g_dluma_process_element_inputs && g_dluma_set_element_can_focus)
        return 1;
    if (!g_dluma.engine.ready ||
        g_dluma.engine.image_timestamp != DLUMA_DEVTOOLS_ENGINE_TIMESTAMP ||
        g_dluma.engine.image_size != DLUMA_DEVTOOLS_ENGINE_IMAGE_SIZE)
        return 0;
    engine = g_dluma.engine.engine_module;
    if (!engine)
        return 0;
    g_dluma_process_element_inputs =
        (DlumaProcessElementInputsFn)GetProcAddress(
            engine, "?ProcessInputs@IUIElementControl@@QEAAX_N@Z");
    if (!g_dluma_process_element_inputs ||
        !g_dluma_set_element_can_focus ||
        !dluma_is_readable(
            (const void *)g_dluma_process_element_inputs,
            sizeof(process_inputs_prefix)) ||
        memcmp(
            (const void *)g_dluma_process_element_inputs,
            process_inputs_prefix, sizeof(process_inputs_prefix)) != 0 ||
        !dluma_is_readable(
            (const void *)g_dluma_set_element_can_focus,
            sizeof(set_can_focus_prefix)) ||
        memcmp(
            (const void *)g_dluma_set_element_can_focus,
            set_can_focus_prefix, sizeof(set_can_focus_prefix)) != 0)
    {
        g_dluma_process_element_inputs = 0;
        return 0;
    }
    return 1;
}

static void dluma_ui_workshop_set_row_secondary(
    const DlumaWorkshopMenuRowView *row,
    const DlumaWorkshopMenuRemoteItem *remote, int has_remote)
{
    void *stock_author_label;
    int has_author;
    if (!row || !row->item)
        return;
    has_author = has_remote && remote && remote->author_ready &&
                 remote->author[0];
    stock_author_label =
        dluma_ui_find_required_child(row->item, "T_Label");
    /*
     * ListButtonCustomMapSlotV has a fixed 50-pixel stride and exactly one
     * secondary line.  Preserve that stock geometry.  A genuine
     * Title/Author/ID layout requires a separately registered taller visual;
     * enabling multiline on these children only makes adjacent rows collide.
     */
    if (has_author)
    {
        dluma_ui_set_text_element_text(stock_author_label, "AUTHOR:");
        dluma_ui_workshop_set_element_text_association(
            row->item, remote->author, 2);
        dluma_ui_set_element_visible(stock_author_label, 1);
    }
    else if (!row->subscribed)
    {
        dluma_ui_set_text_element_text(stock_author_label, "ID:");
        dluma_ui_workshop_set_element_text_association(
            row->item, "LOCAL", 2);
        dluma_ui_set_element_visible(stock_author_label, 1);
    }
    else
    {
        dluma_ui_workshop_set_element_text_association(
            row->item, "", 2);
        dluma_ui_set_element_visible(stock_author_label, 0);
    }
}

static void dluma_ui_registry_cycle_category(void *screen, int direction)
{
    const char *selected = dluma_ui_registry_current_selected_id();
    if (!screen || !dluma_ui_is_mods_registry_screen(screen) ||
        g_dluma_ui_registry_approval_mode)
        return;
    if (selected && selected[0] &&
        g_dluma_ui_registry_category < DLUMA_REGISTRY_CATEGORY_COUNT)
        dluma_str_copy(
            g_dluma_ui_registry_selected_by_category[
                g_dluma_ui_registry_category],
            DLUMA_SHA256_HEX_CAPACITY, selected);
    if (direction < 0)
        g_dluma_ui_registry_category =
            g_dluma_ui_registry_category == 0
                ? DLUMA_REGISTRY_CATEGORY_COUNT - 1U
                : g_dluma_ui_registry_category - 1U;
    else
        g_dluma_ui_registry_category =
            (g_dluma_ui_registry_category + 1U) %
            DLUMA_REGISTRY_CATEGORY_COUNT;
    g_dluma_ui_registry_selected_id[0] = 0;
    dluma_ui_registry_populate_list(screen, 0);
    dluma_ui_focus_element(g_dluma_ui_registry_list);
}

static int dluma_ui_is_mod_config_screen(void *screen)
{
    return screen && dluma_ui_object_id_equals(screen, "MenuDLUMAModConfig");
}

static int dluma_ui_is_mod_details_screen(void *screen)
{
    return screen && dluma_ui_object_id_equals(screen, "MenuDLUMAModDetails");
}

static void dluma_ui_workshop_set_row_chrome(
    const DlumaWorkshopMenuRowView *row, int visible)
{
    static const char *const standard_children[] = {
        "picture",
        "picture_foreground",
        "G_Info_23"
    };
    static const char *const focus_children[] = {
        "focus_picture",
        "antifocus_picture",
        "focus_triangle",
        "back_belt"
    };
    unsigned int i;
    if (!row || !row->item)
        return;
    if (dluma_ui_workshop_bind_row_interaction_exports())
    {
        g_dluma_set_element_can_focus(
            row->item, (unsigned char)(visible ? 1 : 0));
        g_dluma_process_element_inputs(
            row->item, (unsigned char)(visible ? 1 : 0));
    }
    for (i = 0; i < DLUMA_ARRAY_COUNT(standard_children); ++i)
        dluma_ui_set_element_visible(
            dluma_ui_find_required_child(
                row->item, standard_children[i]),
            visible);
    /* Native row timelines own focus/antifocus visibility for real items.
     * Only the divider needs those presenters suppressed permanently. */
    if (!visible)
        for (i = 0; i < DLUMA_ARRAY_COUNT(focus_children); ++i)
            dluma_ui_set_element_visible(
                dluma_ui_find_required_child(
                    row->item, focus_children[i]), 0);
    if (visible)
    {
        if (g_dluma_workshop_set_element_texture &&
            !dluma_ui_workshop_item_has_texture(row->item))
        {
            DlumaTtlString fallback;
            dluma_ttl_string_init(&fallback, "playgame_slot_icon_empty");
            (void)g_dluma_workshop_set_element_texture(
                row->item, &fallback, 0);
        }
    }
}

static void dluma_ui_workshop_enable_selector_row(
    const DlumaWorkshopMenuRowView *row)
{
    if (!row || !row->item)
        return;
    dluma_ui_set_element_disabled(row->item, 0);
    dluma_ui_workshop_set_row_chrome(row, 1);
    dluma_ui_set_element_visible(
        dluma_ui_find_required_child(row->item, "txt_info_1"), 1);
}

static int dluma_ui_bind_normalized_scroll_view(void *scroll_view)
{
    static const BYTE expected_prefix[] = {
        0x48, 0x83, 0xec, 0x48, 0x0f, 0x29, 0x74, 0x24,
        0x30, 0x0f, 0x28, 0xf1, 0x48, 0x89, 0x5c, 0x24
    };
    BYTE *target;
    if (!scroll_view ||
        !dluma_is_readable(scroll_view, 0x98U))
        return 0;
    if (g_dluma_workshop_set_normalized_viewport)
        return 1;
    if (!g_dluma_registry_gamedll_base)
        return 0;
    target = g_dluma_registry_gamedll_base +
             DLUMA_DEVTOOLS_WORKSHOP_SET_NORMALIZED_VIEWPORT_RVA;
    if (!dluma_is_readable(target, sizeof(expected_prefix)) ||
        memcmp(target, expected_prefix, sizeof(expected_prefix)) != 0)
        return 0;
    g_dluma_workshop_set_normalized_viewport =
        (DlumaWorkshopSetNormalizedViewportFn)target;
    return 1;
}

static void dluma_ui_reset_validated_scroll_view(void *scroll_view)
{
    if (scroll_view &&
        dluma_ui_bind_normalized_scroll_view(scroll_view))
        g_dluma_workshop_set_normalized_viewport(
            scroll_view, 0.0f);
}

static int dluma_ui_workshop_bind_description_scroll(void)
{
    return dluma_ui_bind_normalized_scroll_view(
        g_dluma_workshop_menu_description_scroll);
}

static void dluma_ui_workshop_reset_description_scroll(void)
{
    if (dluma_ui_workshop_bind_description_scroll())
        g_dluma_workshop_set_normalized_viewport(
            g_dluma_workshop_menu_description_scroll, 0.0f);
}

static int dluma_ui_workshop_resolve_controls(void *screen)
{
    void *list;
    if (!screen || !dluma_ui_is_stock_workshop_screen(screen))
        return 0;
    list = dluma_ui_find_required_child(screen, "L_Maps");
    if (!dluma_ui_workshop_validate_list(list))
    {
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_custom_layout_unresolved_log_once,
                1, 0) == 0)
            dluma_log_pair("WARN", "workshop_menu_custom_layout_unresolved",
                         "native_map_list_unavailable");
        return 0;
    }
    g_dluma_workshop_menu_screen = screen;
    g_dluma_workshop_menu_list = list;
    g_dluma_workshop_menu_title =
        dluma_ui_find_required_child(screen, "T_MapName");
    g_dluma_workshop_menu_author_group =
        dluma_ui_find_required_child(screen, "G_Author");
    g_dluma_workshop_menu_author =
        dluma_ui_find_required_child(screen, "T_AuthorValue");
    g_dluma_workshop_menu_id_group =
        dluma_ui_find_required_child(screen, "G_WorkshopId");
    g_dluma_workshop_menu_id =
        dluma_ui_find_required_child(screen, "T_WorkshopIdValue");
    g_dluma_workshop_menu_compact_id_group =
        dluma_ui_find_required_child(screen, "G_WorkshopIdCompact");
    g_dluma_workshop_menu_compact_id =
        dluma_ui_find_required_child(screen, "T_WorkshopIdCompactValue");
    g_dluma_workshop_menu_description =
        dluma_ui_find_required_child(screen, "T_Description");
    g_dluma_workshop_menu_description_scroll =
        dluma_ui_find_required_child(screen, "G_DescriptionScroll");
    g_dluma_workshop_menu_description_scrollbar =
        dluma_ui_find_required_child(screen, "LBScrollBar");
    g_dluma_workshop_description_active_item = 0;
    if (!g_dluma_workshop_menu_title || !g_dluma_workshop_menu_author_group ||
        !g_dluma_workshop_menu_author || !g_dluma_workshop_menu_id_group ||
        !g_dluma_workshop_menu_id ||
        !g_dluma_workshop_menu_compact_id_group ||
        !g_dluma_workshop_menu_compact_id ||
        !g_dluma_workshop_menu_description ||
        !g_dluma_workshop_menu_description_scroll ||
        !g_dluma_workshop_menu_description_scrollbar)
    {
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_custom_layout_unresolved_log_once,
                1, 0) == 0)
            dluma_log_pair("WARN", "workshop_menu_custom_layout_unresolved",
                         "required_detail_controls_missing");
        return 0;
    }
    if (g_dluma_get_object_level)
        g_dluma_workshop_menu_level = g_dluma_get_object_level(screen);
    if (g_dluma.engine.get_screen_id)
        g_dluma_workshop_menu_screen_id = g_dluma.engine.get_screen_id(screen);
    if (!g_dluma_workshop_menu_level || g_dluma_workshop_menu_screen_id < 0)
    {
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_custom_layout_unresolved_log_once,
                1, 0) == 0)
            dluma_log_pair("WARN", "workshop_menu_custom_layout_unresolved",
                         "screen_identity_unavailable");
        return 0;
    }
    if (dluma_atomic_compare_exchange(
            &g_dluma_workshop_custom_layout_validated_log_once, 1, 0) == 0)
        dluma_log_pair("INFO", "workshop_menu_custom_layout_validated",
                     "required_controls_resolved");
    return 1;
}

static void dluma_ui_workshop_present(void *screen)
{
    int count;
    int active;
    int i;
    DlumaWorkshopMenuRowView active_row;
    int active_valid = 0;
    if ((!g_dluma_workshop_menu_screen ||
         g_dluma_workshop_menu_screen != screen ||
         !g_dluma_workshop_menu_list) &&
        !dluma_ui_workshop_resolve_controls(screen))
        return;
    count = dluma_ui_workshop_list_count(g_dluma_workshop_menu_list);
    active = dluma_ui_workshop_active_index(g_dluma_workshop_menu_list);
    memset(&active_row, 0, sizeof(active_row));
    for (i = 0; i < count; ++i)
    {
        DlumaWorkshopMenuRowView row;
        DlumaWorkshopMenuItem metadata;
        DlumaWorkshopMenuRemoteItem remote;
        int has_metadata;
        int has_remote;
        int in_window = active >= 0 &&
                        i >= active - DLUMA_WORKSHOP_TEXTURE_WINDOW_RADIUS &&
                        i <= active + DLUMA_WORKSHOP_TEXTURE_WINDOW_RADIUS;
        if (!dluma_ui_workshop_read_row(
                g_dluma_workshop_menu_list, (unsigned int)i, &row))
            continue;
        if (row.divider)
        {
            dluma_ui_workshop_set_element_text_association(
                row.item, "LOCAL PROJECTS", 1);
            dluma_ui_workshop_set_element_text_association(row.item, "", 2);
            dluma_ui_workshop_set_row_chrome(&row, 0);
        }
        else if (dluma_ui_workshop_resolve_row(
                     &row, in_window, &metadata, &has_metadata,
                     &remote, &has_remote))
        {
            dluma_ui_workshop_set_element_text_association(
                row.item,
                dluma_ui_workshop_row_title(
                    &row, &metadata, has_metadata, &remote, has_remote),
                1);
            dluma_ui_workshop_set_row_secondary(
                &row,
                &remote, has_remote);
            dluma_ui_workshop_enable_selector_row(&row);
        }
        if (i == active)
        {
            active_row = row;
            active_valid = 1;
        }
    }
    if (!active_valid || active_row.divider)
    {
        dluma_ui_set_text_element_long(
            g_dluma_workshop_menu_title,
            active_valid ? "LOCAL PROJECTS" : "SELECT A MAP");
        dluma_ui_set_element_visible(g_dluma_workshop_menu_author_group, 0);
        dluma_ui_set_element_visible(g_dluma_workshop_menu_id_group, 0);
        dluma_ui_set_element_visible(
            g_dluma_workshop_menu_compact_id_group, 1);
        dluma_ui_set_text_element_long(
            g_dluma_workshop_menu_compact_id,
            active_valid ? "" : "LOCAL PROJECT");
        dluma_ui_set_text_element_long(
            g_dluma_workshop_menu_description,
            active_valid ? "LOCAL PROJECTS INSTALLED WITH DEVELOPER TOOLS."
                         : "No description provided.");
    }
    else
    {
        DlumaWorkshopMenuItem metadata;
        DlumaWorkshopMenuRemoteItem remote;
        int has_metadata;
        int has_remote;
        (void)dluma_ui_workshop_resolve_row(
            &active_row, 1, &metadata, &has_metadata,
            &remote, &has_remote);
        dluma_ui_set_text_element_long(
            g_dluma_workshop_menu_title,
            dluma_ui_workshop_row_title(
                &active_row, &metadata, has_metadata,
                &remote, has_remote));
        {
            const char *detail_id = dluma_ui_workshop_row_id(
                &active_row, &metadata, has_metadata);
            dluma_ui_set_text_element_long(
                g_dluma_workshop_menu_id, detail_id);
            dluma_ui_set_text_element_long(
                g_dluma_workshop_menu_compact_id, detail_id);
        }
        dluma_ui_set_text_element_long(
            g_dluma_workshop_menu_description,
            has_metadata && metadata.description[0]
                ? metadata.description
                : "No description provided.");
        if (has_remote && remote.author_ready && remote.author[0])
        {
            dluma_ui_set_text_element_long(
                g_dluma_workshop_menu_author, remote.author);
            dluma_ui_set_element_visible(
                g_dluma_workshop_menu_author_group, 1);
            dluma_ui_set_element_visible(
                g_dluma_workshop_menu_id_group, 1);
            dluma_ui_set_element_visible(
                g_dluma_workshop_menu_compact_id_group, 0);
        }
        else
        {
            dluma_ui_set_element_visible(
                g_dluma_workshop_menu_author_group, 0);
            dluma_ui_set_element_visible(
                g_dluma_workshop_menu_id_group, 0);
            dluma_ui_set_element_visible(
                g_dluma_workshop_menu_compact_id_group, 1);
        }
    }
    {
        void *active_item = active_valid && !active_row.divider
                                ? active_row.item : 0;
        if (g_dluma_workshop_description_active_item != active_item)
        {
            g_dluma_workshop_description_active_item = active_item;
            dluma_ui_workshop_reset_description_scroll();
        }
    }
}

