static int dluma_ui_workshop_set_picture(void *item, const char *alias)
{
    void *picture;
    DlumaTtlString name;
    unsigned char result;
    if (!item || !alias || !alias[0] ||
        !g_dluma_workshop_set_element_texture)
        return 0;
    picture = dluma_ui_find_required_child(item, "picture");
    if (!picture)
        return 0;
    dluma_ttl_string_init(&name, alias);
    result = g_dluma_workshop_set_element_texture(
        item, &name, 0);
    if (result && g_dluma_workshop_force_sync_frame_data)
    {
        g_dluma_workshop_force_sync_frame_data(item);
        g_dluma_workshop_force_sync_frame_data(picture);
    }
    return result != 0;
}

static ULONGLONG dluma_ui_workshop_texture_hash(
    const WCHAR *path, ULONGLONG published_id)
{
    ULONGLONG hash = 1469598103934665603ULL ^ published_id;
    unsigned int i;
    for (i = 0; path && path[i]; ++i)
    {
        hash ^= (ULONGLONG)dluma_wascii_lower(path[i]);
        hash *= 1099511628211ULL;
    }
    return hash;
}

