static void dluma_ui_workshop_detach_row_texture_bindings(void)
{
    unsigned int i;
    for (i = 0;
         i < DLUMA_WORKSHOP_ROW_TEXTURE_BINDING_COUNT; ++i)
        dluma_workshop_texture_detach_row_binding(
            (DlumaWorkshopRowTextureBindingCore *)
                &g_dluma_workshop_row_texture_bindings[i]);
}

static void dluma_ui_workshop_unload_texture_asset(
    DlumaWorkshopTextureAsset *asset, void *current_level)
{
    unsigned int i;
    if (!asset)
        return;
    for (i = 0;
         i < DLUMA_WORKSHOP_ROW_TEXTURE_BINDING_COUNT; ++i)
        if (g_dluma_workshop_row_texture_bindings[i].asset == asset)
            memset(
                &g_dluma_workshop_row_texture_bindings[i], 0,
                sizeof(g_dluma_workshop_row_texture_bindings[i]));
    if (asset->definition_requested &&
        asset->level && asset->level == current_level &&
        asset->alias[0])
    {
        DlumaTtlString alias;
        dluma_ttl_string_init(&alias, asset->alias);
        if (asset->progress.precached &&
            g_dluma_workshop_release_precached_ui_texture)
            g_dluma_workshop_release_precached_ui_texture(
                asset->level, &alias);
        if (g_dluma_workshop_unload_ui_texture)
            (void)g_dluma_workshop_unload_ui_texture(
                asset->level, &alias);
    }
    memset(asset, 0, sizeof(*asset));
}

static void dluma_ui_workshop_release_textures(void *current_level)
{
    unsigned int i;
    dluma_ui_workshop_detach_row_texture_bindings();
    for (i = 0; i < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT; ++i)
        dluma_ui_workshop_unload_texture_asset(
            &g_dluma_workshop_texture_assets[i], current_level);
}

static DlumaWorkshopTextureAsset *
dluma_ui_workshop_find_texture_asset(
    void *level, const char *virtual_filename)
{
    unsigned int i;
    for (i = 0; i < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT; ++i)
    {
        DlumaWorkshopTextureAsset *asset =
            &g_dluma_workshop_texture_assets[i];
        if (asset->level == level &&
            asset->virtual_filename[0] &&
            dluma_stricmp(
                asset->virtual_filename, virtual_filename) == 0)
            return asset;
    }
    return 0;
}

static DlumaWorkshopTextureAsset *
dluma_ui_workshop_allocate_texture_asset(
    void *level, unsigned int generation, ULONGLONG now_ms)
{
    DlumaWorkshopTextureAsset *candidate = 0;
    unsigned int i;
    for (i = 0; i < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT; ++i)
        if (!g_dluma_workshop_texture_assets[i].
                virtual_filename[0])
            return &g_dluma_workshop_texture_assets[i];
    for (i = 0; i < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT; ++i)
    {
        DlumaWorkshopTextureAsset *asset =
            &g_dluma_workshop_texture_assets[i];
        int pending_before_deadline =
            (asset->progress.state ==
                 DLUMA_WS_ASSET_IMAGELIB_DECODED ||
             asset->progress.state ==
                 DLUMA_WS_ASSET_FILE_BACKING_PENDING) &&
            now_ms < asset->progress.backing_deadline_ms;
        if (asset->progress.generation == generation ||
            pending_before_deadline ||
            asset->progress.state == DLUMA_WS_ASSET_READY)
            continue;
        if (!candidate ||
            asset->progress.last_wanted_ms <
                candidate->progress.last_wanted_ms)
            candidate = asset;
    }
    if (!candidate)
        for (i = 0; i < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT; ++i)
        {
            DlumaWorkshopTextureAsset *asset =
                &g_dluma_workshop_texture_assets[i];
            if (asset->progress.generation == generation ||
                asset->progress.state != DLUMA_WS_ASSET_READY)
                continue;
            if (!candidate ||
                asset->progress.last_wanted_ms <
                    candidate->progress.last_wanted_ms)
                candidate = asset;
        }
    if (candidate)
        dluma_ui_workshop_unload_texture_asset(candidate, level);
    return candidate;
}

static DlumaWorkshopTextureAsset *
dluma_ui_workshop_get_texture_asset(
    void *level, const WCHAR *file_path,
    const char *virtual_filename, ULONGLONG identity_hash,
    unsigned int generation, ULONGLONG now_ms)
{
    DlumaWorkshopTextureAsset *asset;
    DlumaTtlString file;
    int visible = 0;
    asset = dluma_ui_workshop_find_texture_asset(
        level, virtual_filename);
    if (asset)
    {
        dluma_workshop_texture_asset_mark_wanted(
            &asset->progress, generation, now_ms);
        return asset;
    }
    asset = dluma_ui_workshop_allocate_texture_asset(
        level, generation, now_ms);
    if (!asset)
        return 0;
    memset(asset, 0, sizeof(*asset));
    asset->level = level;
    dluma_wstr_copy(
        asset->file_path, DLUMA_ARRAY_COUNT(asset->file_path),
        file_path);
    dluma_str_copy(
        asset->virtual_filename,
        DLUMA_ARRAY_COUNT(asset->virtual_filename),
        virtual_filename);
    dluma_str_copy(
        asset->alias, DLUMA_ARRAY_COUNT(asset->alias),
        "dluma_ws_");
    {
        char hash_text[32];
        dluma_u64_to_text(
            identity_hash, hash_text,
            DLUMA_ARRAY_COUNT(hash_text));
        dluma_str_append(
            asset->alias, DLUMA_ARRAY_COUNT(asset->alias),
            hash_text);
    }
    (void)dluma_workshop_texture_asset_set_identity(
        &asset->progress, identity_hash,
        DLUMA_WORKSHOP_PREVIEW_DDS_GENERATION);
    dluma_workshop_texture_asset_mark_wanted(
        &asset->progress, generation, now_ms);
    dluma_ttl_string_init(&file, virtual_filename);
    visible =
        g_dluma_workshop_does_texture_file_exist(level, &file) != 0;
    if (!visible)
    {
        int refreshed =
            dluma_workshop_preview_cache_refresh_for_visibility_retry();
        visible = refreshed &&
            g_dluma_workshop_does_texture_file_exist(level, &file);
        if (!visible)
        {
            if (dluma_atomic_compare_exchange(
                    &g_dluma_workshop_vfs_still_missing_log_once,
                    1, 0) == 0)
            {
                dluma_log_pair(
                    "WARN", "workshop_preview_vfs_visibility",
                    "still_missing_after_refresh");
                dluma_log_pair(
                    "INFO", "workshop_preview_virtual_filename",
                    virtual_filename);
            }
            memset(asset, 0, sizeof(*asset));
            return 0;
        }
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_vfs_visible_after_refresh_log_once,
                1, 0) == 0)
        {
            dluma_log_pair(
                "INFO", "workshop_preview_vfs_visibility",
                "visible_after_refresh");
            dluma_log_pair(
                "INFO", "workshop_preview_virtual_filename",
                virtual_filename);
        }
    }
    else if (dluma_atomic_compare_exchange(
                 &g_dluma_workshop_vfs_visible_without_refresh_log_once,
                 1, 0) == 0)
    {
        dluma_log_pair(
            "INFO", "workshop_preview_vfs_visibility",
            "visible_without_refresh");
        dluma_log_pair(
            "INFO", "workshop_preview_virtual_filename",
            virtual_filename);
    }
    dluma_workshop_texture_asset_mark_vfs_visible(
        &asset->progress, now_ms);
    return asset;
}

static DlumaWorkshopTextureLoadResult
dluma_ui_workshop_update_texture_asset(
    DlumaWorkshopTextureAsset *asset, ULONGLONG now_ms)
{
    DlumaWorkshopTextureAssetState state;
    DlumaTtlString alias;
    void *ui_manager;
    if (!asset || !asset->level ||
        !asset->virtual_filename[0])
        return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
    state = dluma_workshop_texture_asset_tick_file_proof(
        &asset->progress, asset->virtual_filename,
        now_ms, dluma_ui_workshop_probe_backing_control_once(),
        0, dluma_ui_workshop_imagelib_probe_callback,
        dluma_ui_workshop_backing_probe_callback);
    asset->decode_logged = asset->progress.imagelib_probed;
    if (state == DLUMA_WS_ASSET_TERMINAL_DECODE_FAILURE)
        return DLUMA_WORKSHOP_TEXTURE_LOAD_MISSING_FALLBACK;
    if (state == DLUMA_WS_ASSET_VFS_VISIBLE)
        return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
    if (state == DLUMA_WS_ASSET_FILE_BACKING_PENDING)
    {
        if (!asset->backing_pending_logged)
        {
            asset->backing_pending_logged = 1;
            dluma_log_pair(
                "INFO", "workshop_preview_file_backing",
                "pending");
            dluma_log_u64(
                "INFO",
                "workshop_preview_file_backing_elapsed_ms",
                dluma_workshop_texture_asset_backing_elapsed_ms(
                    &asset->progress, now_ms));
            dluma_log_pair(
                "INFO", "workshop_preview_virtual_filename",
                asset->virtual_filename);
        }
        return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
    }
    if (state == DLUMA_WS_ASSET_IMAGELIB_DECODED)
        return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
    if (state == DLUMA_WS_ASSET_TERMINAL_TIMEOUT)
    {
        if (!asset->terminal_logged &&
            dluma_atomic_increment(
                &g_dluma_workshop_backing_probe_log_count) <=
            DLUMA_WORKSHOP_PRESENTATION_DIAGNOSTIC_LOG_LIMIT)
        {
            asset->terminal_logged = 1;
            dluma_log_pair(
                "WARN", "workshop_preview_file_backing",
                "terminal_timeout");
            dluma_log_u64(
                "WARN",
                "workshop_preview_file_backing_elapsed_ms",
                dluma_workshop_texture_asset_backing_elapsed_ms(
                    &asset->progress, now_ms));
            dluma_log_pair(
                "INFO", "workshop_preview_virtual_filename",
                asset->virtual_filename);
        }
        return DLUMA_WORKSHOP_TEXTURE_LOAD_MISSING_FALLBACK;
    }
    if (state == DLUMA_WS_ASSET_FILE_BACKING_REAL &&
        !asset->backing_real_logged)
    {
        asset->backing_real_logged = 1;
        dluma_log_pair(
            "INFO", "workshop_preview_file_backing",
            "real_texture");
        dluma_log_u64(
            "INFO", "workshop_preview_file_backing_elapsed_ms",
            dluma_workshop_texture_asset_backing_elapsed_ms(
                &asset->progress, now_ms));
        dluma_log_pair(
            "INFO", "workshop_preview_virtual_filename",
            asset->virtual_filename);
    }
    state = (DlumaWorkshopTextureAssetState)
        asset->progress.state;
    if (state == DLUMA_WS_ASSET_TERMINAL_DECODE_FAILURE ||
        state == DLUMA_WS_ASSET_TERMINAL_TIMEOUT)
        return DLUMA_WORKSHOP_TEXTURE_LOAD_MISSING_FALLBACK;
    if (state == DLUMA_WS_ASSET_FILE_BACKING_REAL &&
        !asset->definition_requested)
    {
        DlumaTtlString file;
        DlumaTtlString material;
        dluma_ttl_string_init(&alias, asset->alias);
        dluma_ttl_string_init(
            &file, asset->virtual_filename);
        memset(&material, 0, sizeof(material));
        g_dluma_workshop_load_ui_texture(
            asset->level, &alias, &file,
            512, 512, 0, 0, 512, 512,
            0, 0, 0, &material);
        asset->definition_requested = 1;
    }
    dluma_ttl_string_init(&alias, asset->alias);
    if (!asset->progress.ui_definition_registered)
    {
        if (!asset->definition_requested ||
            !g_dluma_workshop_is_ui_texture_loaded(
                asset->level, &alias))
            return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
        dluma_workshop_texture_asset_mark_ui_definition(
            &asset->progress);
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_texture_definition_log_once,
                1, 0) == 0)
            dluma_log_pair(
                "INFO", "workshop_preview_texture_stage",
                "ui_definition_registered_after_real_backing");
    }
    ui_manager = g_dluma_workshop_get_ui_manager(
        asset->level);
    if (!ui_manager)
        return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
    if (!asset->progress.precached)
    {
        g_dluma_workshop_precache_ui_texture(
            asset->level, &alias);
        asset->progress.precached = 1;
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_texture_precache_log_once,
                1, 0) == 0)
            dluma_log_pair(
                "INFO", "workshop_preview_texture_stage",
                "level_precache_retained");
    }
    if (!asset->progress.prefetch_requested)
    {
        g_dluma_workshop_request_texture_prefetch(
            ui_manager, &alias);
        asset->progress.prefetch_requested = 1;
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_texture_prefetch_log_once,
                1, 0) == 0)
            dluma_log_pair(
                "INFO", "workshop_preview_texture_prefetch",
                "requested");
        return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
    }
    if (!g_dluma_workshop_is_streaming_texture_loaded(
            ui_manager, &alias))
    {
        if (!asset->streaming_pending_logged)
        {
            asset->streaming_pending_logged = 1;
            dluma_log_pair(
                "INFO", "workshop_preview_texture_streaming",
                "pending_fallback_retained");
        }
        return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
    }
    if (!asset->progress.ready)
        dluma_workshop_texture_asset_mark_ready(
            &asset->progress);
    return DLUMA_WORKSHOP_TEXTURE_LOAD_READY;
}

static DlumaWorkshopRowTextureBinding *
dluma_ui_workshop_get_row_texture_binding(
    void *item, DlumaWorkshopTextureAsset *asset,
    unsigned int generation)
{
    DlumaWorkshopRowTextureBinding *binding =
        dluma_ui_workshop_find_row_texture_binding(item);
    unsigned int i;
    if (binding && binding->asset != asset)
    {
        memset(binding, 0, sizeof(*binding));
        binding = 0;
    }
    if (!binding)
        for (i = 0;
             i < DLUMA_WORKSHOP_ROW_TEXTURE_BINDING_COUNT; ++i)
            if (!g_dluma_workshop_row_texture_bindings[i].item)
            {
                binding =
                    &g_dluma_workshop_row_texture_bindings[i];
                break;
            }
    if (!binding)
        return 0;
    if (!binding->item)
    {
        binding->item = item;
        binding->asset = asset;
        binding->custom_alias_bound = 0;
    }
    binding->generation = generation;
    return binding;
}

static DlumaWorkshopTextureLoadResult
dluma_ui_workshop_load_row_texture_asset(
    void *level, const DlumaWorkshopMenuRowView *row,
    const WCHAR *file_path, unsigned int generation,
    ULONGLONG now_ms)
{
    const WCHAR *file_name = file_path;
    const WCHAR *cursor = file_path;
    char virtual_filename[DLUMA_MAX_WPATH * 3U];
    ULONGLONG identity_hash;
    DlumaWorkshopTextureAsset *asset;
    DlumaWorkshopRowTextureBinding *binding;
    DlumaWorkshopTextureLoadResult result;
    if (!level || !row || !row->item ||
        !file_path || !file_path[0] ||
        !dluma_ui_workshop_bind_texture_exports())
        return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
    while (*cursor)
    {
        if (*cursor == L'\\' || *cursor == L'/')
            file_name = cursor + 1;
        ++cursor;
    }
    if (!file_name[0] ||
        !dluma_wide_to_utf8(
            file_name, virtual_filename,
            DLUMA_ARRAY_COUNT(virtual_filename)))
        return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
    identity_hash =
        dluma_ui_workshop_texture_hash(file_path, 0);
    asset = dluma_ui_workshop_get_texture_asset(
        level, file_path, virtual_filename,
        identity_hash, generation, now_ms);
    if (!asset)
        return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
    result = dluma_ui_workshop_update_texture_asset(
        asset, now_ms);
    binding = dluma_ui_workshop_get_row_texture_binding(
        row->item, asset, generation);
    if (!binding)
        return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
    if (result == DLUMA_WORKSHOP_TEXTURE_LOAD_READY &&
        dluma_workshop_texture_asset_can_bind(
            &asset->progress))
    {
        if (!binding->custom_alias_bound)
        {
            if (!dluma_ui_workshop_set_picture(
                    row->item, asset->alias))
                return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
            binding->custom_alias_bound = 1;
            if (dluma_atomic_compare_exchange(
                    &g_dluma_workshop_texture_bind_log_once,
                    1, 0) == 0)
                dluma_log_pair(
                    "INFO",
                    "workshop_preview_texture_stage",
                    "row_texture_association_0_bound");
            if (dluma_atomic_compare_exchange(
                    &g_dluma_workshop_texture_ready_log_once,
                    1, 0) == 0)
                dluma_log_pair(
                    "INFO",
                    "workshop_preview_texture_streaming",
                    "ready_bound_and_synced");
        }
        return DLUMA_WORKSHOP_TEXTURE_LOAD_READY;
    }
    if (!binding->custom_alias_bound)
        (void)dluma_ui_workshop_set_picture(
            row->item, "playgame_slot_icon_empty");
    return result;
}

static void dluma_ui_workshop_texture_asset_tick(
    void *level, int frontend)
{
    int count;
    int active;
    int begin;
    int end;
    int i;
    unsigned int binding_index;
    unsigned int asset_index;
    unsigned int generation;
    ULONGLONG now_ms = GetTickCount64();
    if (!frontend || !level ||
        !g_dluma_workshop_menu_screen ||
        !g_dluma_workshop_menu_list ||
        g_dluma_workshop_menu_level != level ||
        g_dluma_workshop_menu_screen_id < 0 ||
        !g_dluma.engine.is_ui_screen_visible ||
        !g_dluma.engine.is_ui_screen_visible(
            level, g_dluma_workshop_menu_screen_id))
    {
        dluma_ui_workshop_release_textures(level);
        return;
    }
    if (!dluma_ui_workshop_bind_texture_exports())
        return;
    count = dluma_ui_workshop_list_count(
        g_dluma_workshop_menu_list);
    active = dluma_ui_workshop_active_index(
        g_dluma_workshop_menu_list);
    if (count <= 0 || active < 0 || active >= count)
    {
        dluma_ui_workshop_release_textures(level);
        return;
    }
    generation = ++g_dluma_workshop_texture_generation;
    if (!generation)
        generation = ++g_dluma_workshop_texture_generation;
    begin = active - DLUMA_WORKSHOP_TEXTURE_WINDOW_RADIUS;
    end = active + DLUMA_WORKSHOP_TEXTURE_WINDOW_RADIUS;
    if (begin < 0) begin = 0;
    if (end >= count) end = count - 1;
    for (i = begin; i <= end; ++i)
    {
        DlumaWorkshopMenuRowView row;
        DlumaWorkshopMenuItem metadata;
        DlumaWorkshopMenuRemoteItem remote;
        const WCHAR *preview_path = 0;
        DlumaWorkshopTextureLoadResult result =
            DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
        int has_metadata;
        int has_remote;
        if (!dluma_ui_workshop_read_row(
                g_dluma_workshop_menu_list,
                (unsigned int)i, &row) ||
            row.divider)
            continue;
        (void)dluma_ui_workshop_resolve_row(
            &row, 1, &metadata, &has_metadata,
            &remote, &has_remote);
        if (!row.subscribed && has_metadata &&
            metadata.preview_available &&
            metadata.preview_path[0])
            preview_path = metadata.preview_path;
        else if (row.subscribed && has_remote &&
                 remote.preview_ready &&
                 remote.preview_path[0])
            preview_path = remote.preview_path;
        if (preview_path)
            result = dluma_ui_workshop_load_row_texture_asset(
                level, &row, preview_path,
                generation, now_ms);
        if (result == DLUMA_WORKSHOP_TEXTURE_LOAD_READY)
        {
            if (dluma_atomic_compare_exchange(
                    &g_dluma_workshop_texture_success_log_once,
                    1, 0) == 0)
                dluma_log_pair(
                    "INFO",
                    "workshop_preview_texture_load",
                    "streaming_ready_success");
        }
        else
        {
            if (preview_path &&
                (result ==
                     DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED ||
                 result ==
                     DLUMA_WORKSHOP_TEXTURE_LOAD_MISSING_FALLBACK) &&
                dluma_atomic_compare_exchange(
                    &g_dluma_workshop_texture_failure_log_once,
                    1, 0) == 0)
                dluma_log_pair(
                    "WARN",
                    "workshop_preview_texture_load",
                    "failed_using_fallback");
            if (!dluma_ui_workshop_item_has_texture(row.item))
                (void)dluma_ui_workshop_set_picture(
                    row.item,
                    "playgame_slot_icon_empty");
        }
    }
    /*
     * Continue immutable pending assets even while their transient rows are
     * outside the active window.  The row binding is disposable; the asset's
     * start time, alias, ImageLib verdict, and queued backing request are not.
     */
    for (asset_index = 0;
         asset_index < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT;
         ++asset_index)
    {
        DlumaWorkshopTextureAsset *asset =
            &g_dluma_workshop_texture_assets[asset_index];
        if (!asset->virtual_filename[0] ||
            asset->progress.generation == generation ||
            asset->progress.state == DLUMA_WS_ASSET_READY ||
            asset->progress.state ==
                DLUMA_WS_ASSET_TERMINAL_DECODE_FAILURE ||
            asset->progress.state ==
                DLUMA_WS_ASSET_TERMINAL_TIMEOUT)
            continue;
        (void)dluma_ui_workshop_update_texture_asset(
            asset, now_ms);
    }
    for (binding_index = 0;
         binding_index <
             DLUMA_WORKSHOP_ROW_TEXTURE_BINDING_COUNT;
         ++binding_index)
        if (g_dluma_workshop_row_texture_bindings[
                binding_index].item &&
            g_dluma_workshop_row_texture_bindings[
                binding_index].generation != generation)
            memset(
                &g_dluma_workshop_row_texture_bindings[
                    binding_index],
                0,
                sizeof(g_dluma_workshop_row_texture_bindings[
                    binding_index]));
}

#endif

static DlumaWorkshopRowTextureBinding *
dluma_ui_workshop_find_row_texture_binding(void *item)
{
    unsigned int i;
    for (i = 0; i < DLUMA_WORKSHOP_ROW_TEXTURE_BINDING_COUNT; ++i)
        if (g_dluma_workshop_row_texture_bindings[i].item == item)
            return &g_dluma_workshop_row_texture_bindings[i];
    return 0;
}

static int dluma_ui_workshop_item_has_texture(void *item)
{
    DlumaWorkshopRowTextureBinding *binding =
        dluma_ui_workshop_find_row_texture_binding(item);
    return binding && binding->custom_alias_bound;
}

static void dluma_ui_workshop_detach_row_texture_bindings(void)
{
    memset(g_dluma_workshop_row_texture_bindings, 0,
           sizeof(g_dluma_workshop_row_texture_bindings));
}

static int dluma_ui_workshop_asset_is_bound(
    const DlumaWorkshopTextureAsset *asset)
{
    unsigned int i;
    for (i = 0; i < DLUMA_WORKSHOP_ROW_TEXTURE_BINDING_COUNT; ++i)
        if (g_dluma_workshop_row_texture_bindings[i].asset == asset)
            return 1;
    return 0;
}

static void dluma_ui_workshop_destroy_texture_backing(
    DlumaWorkshopTextureAsset *asset)
{
    if (!asset || asset->loading_pin_count)
        return;
    if (asset->texture && g_dluma_workshop_force_unload_texture &&
        !g_dluma.stop_requested)
        (void)g_dluma_workshop_force_unload_texture(0, asset->texture);
    asset->texture = 0;
    asset->gpu_uploaded = 0;
    asset->ready = 0;
    asset->actual_texture_name[0] = 0;
}

static int dluma_ui_workshop_release_frontend_texture_alias(
    DlumaWorkshopTextureAsset *asset, void *current_level)
{
    DlumaTtlString alias;
    if (!asset || !asset->level)
        return 1;
    if (asset->level != current_level || !asset->alias[0])
        return 0;
    dluma_ttl_string_init(&alias, asset->alias);
    if (asset->precached && g_dluma_workshop_release_precached_ui_texture)
        g_dluma_workshop_release_precached_ui_texture(asset->level, &alias);
    if (asset->ui_definition_registered && g_dluma_workshop_unload_ui_texture)
        (void)g_dluma_workshop_unload_ui_texture(asset->level, &alias);
    asset->level = 0;
    asset->ui_definition_registered = 0;
    asset->precached = 0;
    return 1;
}

static void dluma_ui_workshop_unload_texture_asset(
    DlumaWorkshopTextureAsset *asset, void *current_level)
{
    unsigned int i;
    if (!asset)
        return;
    for (i = 0; i < DLUMA_WORKSHOP_ROW_TEXTURE_BINDING_COUNT; ++i)
        if (g_dluma_workshop_row_texture_bindings[i].asset == asset)
        {
            if (g_dluma_workshop_row_texture_bindings[i].item)
                (void)dluma_ui_workshop_set_picture(
                    g_dluma_workshop_row_texture_bindings[i].item,
                    "playgame_slot_icon_empty");
            memset(&g_dluma_workshop_row_texture_bindings[i], 0,
                   sizeof(g_dluma_workshop_row_texture_bindings[i]));
        }
    if (!dluma_ui_workshop_release_frontend_texture_alias(
            asset, current_level))
        return;
    if (asset->loading_pin_count)
        return;
    dluma_ui_workshop_destroy_texture_backing(asset);
    memset(asset, 0, sizeof(*asset));
}

static void dluma_ui_workshop_release_textures(void *current_level)
{
    unsigned int i;
    dluma_ui_workshop_detach_row_texture_bindings();
    /* After renderer teardown, ownership is deliberately left to process exit. */
    if (!current_level || g_dluma.stop_requested)
        return;
    for (i = 0; i < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT; ++i)
        dluma_ui_workshop_unload_texture_asset(
            &g_dluma_workshop_texture_assets[i], current_level);
}

static DlumaWorkshopTextureAsset *
dluma_ui_workshop_find_texture_asset(
    void *level, const WCHAR *preview_path, ULONGLONG key)
{
    unsigned int i;
    for (i = 0; i < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT; ++i)
    {
        DlumaWorkshopTextureAsset *asset = &g_dluma_workshop_texture_assets[i];
        if ((asset->level == level ||
             (!asset->level && asset->loading_pin_count)) &&
            asset->asset_key == key && asset->preview_path[0] &&
            preview_path &&
            dluma_wstricmp(asset->preview_path, preview_path) == 0)
            return asset;
    }
    return 0;
}

static DlumaWorkshopTextureAsset *
dluma_ui_workshop_allocate_texture_asset(void *level, unsigned int generation)
{
    DlumaWorkshopTextureAsset *candidate = 0;
    unsigned int i;
    for (i = 0; i < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT; ++i)
        if (!g_dluma_workshop_texture_assets[i].preview_path[0])
            return &g_dluma_workshop_texture_assets[i];
    for (i = 0; i < DLUMA_WORKSHOP_TEXTURE_ASSET_COUNT; ++i)
    {
        DlumaWorkshopTextureAsset *asset = &g_dluma_workshop_texture_assets[i];
        if (asset->last_used_generation == generation ||
            asset->loading_pin_count ||
            dluma_ui_workshop_asset_is_bound(asset))
            continue;
        if (!candidate || asset->last_used_generation <
                              candidate->last_used_generation)
            candidate = asset;
    }
    if (candidate)
    {
        dluma_ui_workshop_unload_texture_asset(candidate, level);
        if (candidate->preview_path[0])
            candidate = 0;
    }
    return candidate;
}

static DlumaWorkshopTextureAsset *
dluma_ui_workshop_get_texture_asset(
    void *level, const WCHAR *preview_path, ULONGLONG asset_key,
    unsigned int generation)
{
    DlumaWorkshopTextureAsset *asset =
        dluma_ui_workshop_find_texture_asset(
            level, preview_path, asset_key);
    char key_text[32];
    if (asset)
    {
        if (!asset->level)
        {
            asset->level = level;
            asset->ui_definition_registered = 0;
            asset->precached = 0;
        }
        asset->last_used_generation = generation;
        return asset;
    }
    asset = dluma_ui_workshop_allocate_texture_asset(level, generation);
    if (!asset)
        return 0;
    memset(asset, 0, sizeof(*asset));
    asset->level = level;
    asset->asset_key = asset_key;
    asset->last_used_generation = generation;
    dluma_wstr_copy(asset->preview_path, DLUMA_ARRAY_COUNT(asset->preview_path),
                  preview_path);
    dluma_u64_to_text(asset_key, key_text, DLUMA_ARRAY_COUNT(key_text));
    dluma_str_copy(asset->dynamic_base_name,
                 DLUMA_ARRAY_COUNT(asset->dynamic_base_name), "dluma_ws_dyn_");
    dluma_str_append(asset->dynamic_base_name,
                   DLUMA_ARRAY_COUNT(asset->dynamic_base_name), key_text);
    dluma_str_copy(asset->alias, DLUMA_ARRAY_COUNT(asset->alias), "dluma_ws_ui_");
    dluma_str_append(asset->alias, DLUMA_ARRAY_COUNT(asset->alias), key_text);
    return asset;
}

static int dluma_ui_workshop_copy_dynamic_name(
    void *texture, const char *expected_prefix,
    char *out, unsigned int capacity)
{
    const char *name;
    unsigned int i;
    unsigned int prefix_len = 0;
    if (!texture || !expected_prefix || !out || !capacity ||
        !dluma_is_readable(texture, DLUMA_CTEXTURE_OBJECT_BYTES) ||
        !*(void **)((BYTE *)texture + DLUMA_CTEXTURE_RENDER_HANDLE_OFFSET))
        return 0;
    name = *(const char **)((BYTE *)texture + DLUMA_CTEXTURE_ACTUAL_NAME_OFFSET);
    if (!name || !dluma_is_readable(name, 1))
        return 0;
    while (expected_prefix[prefix_len]) ++prefix_len;
    for (i = 0; i + 1U < capacity; ++i)
    {
        if (!dluma_is_readable(name + i, 1))
            return 0;
        out[i] = name[i];
        if (!out[i])
            break;
    }
    if (i == 0 || i + 1U >= capacity || out[i] ||
        i < prefix_len || memcmp(out, expected_prefix, prefix_len) != 0)
        return 0;
    return 1;
}

static DlumaWorkshopTextureLoadResult
dluma_ui_workshop_update_texture_asset(DlumaWorkshopTextureAsset *asset)
{
    BYTE *pixels = 0;
    unsigned int width = 0;
    unsigned int height = 0;
    unsigned int stride = 0;
    DlumaTtlString name;
    DlumaTtlString alias;
    DlumaTtlString material;
    void *probe;
    if (!asset || !asset->level || !asset->preview_path[0] || asset->failed)
        return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
    if (!asset->gpu_uploaded)
    {
        if (!asset->pixel_job_requested)
        {
            if (!dluma_workshop_menu_request_preview_pixels(
                    asset->asset_key, asset->preview_path))
                return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
            asset->pixel_job_requested = 1;
            dluma_log_pair("INFO", "workshop_preview_pixel_job", "requested");
        }
        if (!dluma_workshop_menu_take_preview_pixels(
                asset->asset_key, asset->preview_path, &pixels, &width,
                &height, &stride))
            return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
        if (!pixels || width != 512U || height != 512U || stride != 2048U)
        {
            if (pixels) dluma_free(pixels);
            asset->failed = 1;
            return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
        }
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_color_contract_log_once, 1, 0) == 0)
            dluma_log_pair("INFO", "workshop_preview_color_contract",
                         "a8r8g8b8_bgra_cache_to_rgba_dynamic_upload");
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_rgba_ready_log_once, 1, 0) == 0)
            dluma_log_pair("INFO", "workshop_preview_pixel_job", "rgba_ready");
        dluma_ttl_string_init(&name, asset->dynamic_base_name);
        asset->texture = g_dluma_workshop_create_dynamic_texture(
            0, &name, 512, 512, 1U, 0, 2U);
        if (!asset->texture || !dluma_ui_workshop_copy_dynamic_name(
                asset->texture, "dluma_ws_dyn_", asset->actual_texture_name,
                DLUMA_ARRAY_COUNT(asset->actual_texture_name)))
        {
            if (asset->texture)
                (void)g_dluma_workshop_force_unload_texture(0, asset->texture);
            asset->texture = 0;
            dluma_free(pixels);
            asset->failed = 1;
            return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
        }
        dluma_log_pair("INFO", "workshop_preview_dynamic_texture", "created");
        dluma_log_pair("INFO", "workshop_preview_dynamic_texture_name",
                     asset->actual_texture_name);
        dluma_log_pair("INFO", "workshop_preview_dynamic_texture_handle", "nonzero");
        g_dluma_workshop_update_dynamic_texture(
            0, asset->texture, pixels, 0, 0, 0, 0, 512, 512, 2048, 32);
        dluma_free(pixels);
        asset->gpu_uploaded = 1;
        dluma_log_pair("INFO", "workshop_preview_dynamic_texture_upload",
                     "rgba8_complete");
        dluma_ttl_string_init(&name, asset->actual_texture_name);
        probe = g_dluma_workshop_force_load_texture(0, &name, 5);
        if (!probe || probe != asset->texture)
        {
            if (probe) (void)g_dluma_workshop_force_unload_texture(0, probe);
            asset->failed = 1;
            return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
        }
        (void)g_dluma_workshop_force_unload_texture(0, probe);
        dluma_log_pair("INFO", "workshop_preview_dynamic_texture_registry_probe",
                     "same_pointer");
    }
    dluma_ttl_string_init(&alias, asset->alias);
    if (!asset->ui_definition_registered)
    {
        dluma_ttl_string_init(&name, asset->actual_texture_name);
        memset(&material, 0, sizeof(material));
        /*
         * Generation 4 keeps a centered 16:9 image in a square backing so
         * loading screens can lease the same texture.  The Workshop row is
         * already 16:9, so expose only that embedded content rectangle here.
         * Binding the complete square would scale its letterbox into the row
         * and visibly squash the image.  LoadUITexture takes Rect edges
         * (left, top, right, bottom), not an origin plus width and height.
         */
        g_dluma_workshop_load_ui_texture(
            asset->level, &alias, &name,
            (int)DLUMA_WORKSHOP_PREVIEW_EDGE,
            (int)DLUMA_WORKSHOP_PREVIEW_EDGE,
            0, (int)DLUMA_WORKSHOP_PREVIEW_CONTENT_TOP,
            (int)DLUMA_WORKSHOP_PREVIEW_CONTENT_WIDTH,
            (int)DLUMA_WORKSHOP_PREVIEW_CONTENT_BOTTOM,
            0, 0, 0, &material);
        if (!g_dluma_workshop_is_ui_texture_loaded(asset->level, &alias))
            return DLUMA_WORKSHOP_TEXTURE_LOAD_PENDING;
        asset->ui_definition_registered = 1;
        dluma_log_pair("INFO", "workshop_preview_ui_definition",
                     "registered_dynamic_backing");
    }
    if (!asset->precached)
    {
        g_dluma_workshop_precache_ui_texture(asset->level, &alias);
        asset->precached = 1;
    }
    asset->ready = 1;
    return DLUMA_WORKSHOP_TEXTURE_LOAD_READY;
}

static DlumaWorkshopTextureAsset *dluma_ui_loading_pin_preview_asset(
    void *frontend_level, const WCHAR *preview_path,
    ULONGLONG launch_generation)
{
    DlumaWorkshopTextureAsset *asset;
    DlumaWorkshopTextureLoadResult result;
    ULONGLONG key;
    unsigned int generation =
        (unsigned int)(launch_generation & 0xFFFFFFFFULL);
    if (!generation)
        generation = 1U;
    if (!frontend_level || !preview_path || !preview_path[0] ||
        !dluma_ui_workshop_bind_texture_exports())
        return 0;
    key = dluma_ui_workshop_texture_hash(preview_path, 0);
    asset = dluma_ui_workshop_get_texture_asset(
        frontend_level, preview_path, key, generation);
    if (!asset)
        return 0;
    result = dluma_ui_workshop_update_texture_asset(asset);
    if (result != DLUMA_WORKSHOP_TEXTURE_LOAD_READY ||
        !asset->ready || !asset->gpu_uploaded || !asset->texture ||
        !asset->actual_texture_name[0] ||
        asset->loading_pin_count == 0xFFFFFFFFUL)
        return 0;
    ++asset->loading_pin_count;
    dluma_log_pair(
        "INFO", "custom_map_loading_preview_lease", "acquired");
    return asset;
}

static void dluma_ui_loading_release_preview_lease(
    DlumaCustomMapLoadingPresentation *presentation)
{
    DlumaWorkshopTextureAsset *asset;
    DlumaTtlString alias;
    if (!presentation)
        return;
    if (presentation->loading_level &&
        presentation->generated_alias[0] &&
        !g_dluma.stop_requested)
    {
        dluma_ttl_string_init(&alias, presentation->generated_alias);
        if (presentation->preview_precached &&
            g_dluma_workshop_release_precached_ui_texture)
            g_dluma_workshop_release_precached_ui_texture(
                presentation->loading_level, &alias);
        if (presentation->preview_alias_registered &&
            g_dluma_workshop_unload_ui_texture)
            (void)g_dluma_workshop_unload_ui_texture(
                presentation->loading_level, &alias);
    }
    presentation->preview_precached = 0;
    presentation->preview_alias_registered = 0;
    asset = presentation->preview_asset;
    presentation->preview_asset = 0;
    if (!asset || !asset->loading_pin_count)
        return;
    --asset->loading_pin_count;
    if (!asset->loading_pin_count && !asset->level)
    {
        dluma_ui_workshop_destroy_texture_backing(asset);
        memset(asset, 0, sizeof(*asset));
    }
    dluma_log_pair(
        "INFO", "custom_map_loading_preview_lease", "released");
}

static DlumaWorkshopRowTextureBinding *
dluma_ui_workshop_get_row_texture_binding(
    void *item, DlumaWorkshopTextureAsset *asset, unsigned int generation)
{
    DlumaWorkshopRowTextureBinding *binding =
        dluma_ui_workshop_find_row_texture_binding(item);
    unsigned int i;
    if (binding && binding->asset != asset)
    {
        memset(binding, 0, sizeof(*binding));
        binding = 0;
    }
    if (!binding)
        for (i = 0; i < DLUMA_WORKSHOP_ROW_TEXTURE_BINDING_COUNT; ++i)
            if (!g_dluma_workshop_row_texture_bindings[i].item)
            {
                binding = &g_dluma_workshop_row_texture_bindings[i];
                break;
            }
    if (!binding) return 0;
    binding->item = item;
    binding->asset = asset;
    binding->generation = generation;
    return binding;
}

static DlumaWorkshopTextureLoadResult
dluma_ui_workshop_load_row_texture_asset(
    void *level, const DlumaWorkshopMenuRowView *row,
    const WCHAR *preview_path, unsigned int generation)
{
    DlumaWorkshopTextureAsset *asset;
    DlumaWorkshopRowTextureBinding *binding;
    DlumaWorkshopTextureLoadResult result;
    ULONGLONG key;
    if (!level || !row || !row->item || !preview_path || !preview_path[0] ||
        !dluma_ui_workshop_bind_texture_exports())
        return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
    key = dluma_ui_workshop_texture_hash(preview_path, 0);
    asset = dluma_ui_workshop_get_texture_asset(level, preview_path, key, generation);
    if (!asset) return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
    result = dluma_ui_workshop_update_texture_asset(asset);
    binding = dluma_ui_workshop_get_row_texture_binding(row->item, asset, generation);
    if (!binding) return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
    if (result == DLUMA_WORKSHOP_TEXTURE_LOAD_READY && asset->ready)
    {
        if (!binding->custom_alias_bound)
        {
            if (!dluma_ui_workshop_set_picture(row->item, asset->alias))
                return DLUMA_WORKSHOP_TEXTURE_LOAD_FAILED;
            binding->custom_alias_bound = 1;
            dluma_log_pair("INFO", "workshop_preview_texture_stage",
                         "row_texture_association_0_bound");
            dluma_log_pair("INFO", "workshop_preview_texture_load",
                         "dynamic_ready_success");
        }
        return DLUMA_WORKSHOP_TEXTURE_LOAD_READY;
    }
    if (!binding->custom_alias_bound)
        (void)dluma_ui_workshop_set_picture(row->item, "playgame_slot_icon_empty");
    return result;
}

static void dluma_ui_workshop_texture_asset_tick(void *level, int frontend)
{
    int count, active, begin, end, i;
    unsigned int generation;
    if (!frontend || !level || !g_dluma_workshop_menu_screen ||
        !g_dluma_workshop_menu_list || g_dluma_workshop_menu_level != level ||
        g_dluma_workshop_menu_screen_id < 0 || !g_dluma.engine.is_ui_screen_visible ||
        !g_dluma.engine.is_ui_screen_visible(level, g_dluma_workshop_menu_screen_id))
    {
        dluma_ui_workshop_release_textures(level);
        return;
    }
    if (!dluma_ui_workshop_bind_texture_exports()) return;
    count = dluma_ui_workshop_list_count(g_dluma_workshop_menu_list);
    active = dluma_ui_workshop_active_index(g_dluma_workshop_menu_list);
    if (count <= 0 || active < 0 || active >= count) return;
    generation = ++g_dluma_workshop_texture_generation;
    if (!generation) generation = ++g_dluma_workshop_texture_generation;
    begin = active - DLUMA_WORKSHOP_TEXTURE_WINDOW_RADIUS;
    end = active + DLUMA_WORKSHOP_TEXTURE_WINDOW_RADIUS;
    if (begin < 0) begin = 0;
    if (end >= count) end = count - 1;
    for (i = begin; i <= end; ++i)
    {
        DlumaWorkshopMenuRowView row;
        DlumaWorkshopMenuItem metadata;
        DlumaWorkshopMenuRemoteItem remote;
        const WCHAR *preview_path = 0;
        int has_metadata = 0, has_remote = 0;
        if (!dluma_ui_workshop_read_row(g_dluma_workshop_menu_list, (unsigned int)i,
                                      &row) || row.divider)
            continue;
        (void)dluma_ui_workshop_resolve_row(&row, 1, &metadata, &has_metadata,
                                          &remote, &has_remote);
        if (!row.subscribed && has_metadata && metadata.preview_available &&
            metadata.preview_path[0])
            preview_path = metadata.preview_path;
        else if (row.subscribed && has_remote && remote.preview_ready &&
                 remote.preview_path[0])
            preview_path = remote.preview_path;
        if (preview_path)
            (void)dluma_ui_workshop_load_row_texture_asset(
                level, &row, preview_path, generation);
        else if (!dluma_ui_workshop_item_has_texture(row.item))
            (void)dluma_ui_workshop_set_picture(row.item, "playgame_slot_icon_empty");
    }
}

static void dluma_ui_workshop_refresh_now(
    void *screen, DlumaWorkshopFillMapsFn original)
{
    DlumaWorkshopRefreshState state;
    const DlumaWorkshopRefreshIdentity *active_identity;
    void *list;
    int restored_selected = -1;
    int restored_focused = -1;
    int restored_first_visible = -1;
    int restored_active = -1;
    if (!screen || !original ||
        dluma_atomic_increment(&g_dluma_workshop_refresh_depth) != 1)
    {
        dluma_atomic_decrement(&g_dluma_workshop_refresh_depth);
        return;
    }
    list = dluma_ui_workshop_screen_list(screen);
    dluma_ui_workshop_capture_refresh_state(list, &state);
    /*
     * FillMaps destroys and recreates row objects.  Detach only the ephemeral
     * row bindings before native invalidation; immutable content-hashed assets
     * keep their ImageLib/backing/UI state and are reused by matching rebuilt
     * rows.
     */
    dluma_ui_workshop_detach_row_texture_bindings();
    if (original)
        original(screen);

    list = dluma_ui_workshop_screen_list(screen);
    if (list)
    {
        g_dluma_workshop_menu_list = list;
        (void)dluma_ui_workshop_filter_invalid_projects(list);
        restored_active = dluma_ui_workshop_restore_refresh_state(
            list, &state, &restored_selected, &restored_focused,
            &restored_first_visible);
        dluma_ui_workshop_present(screen);
        if (!dluma_ui_workshop_is_selectable_index(
                list, restored_active))
            restored_active =
                dluma_ui_workshop_ensure_initial_focus(screen);
    }
    active_identity = state.focused.selectable
                          ? &state.focused : &state.selected;
    g_dluma_workshop_refresh_selected_before = state.selected.index;
    g_dluma_workshop_refresh_selected_after = restored_selected;
    g_dluma_workshop_refresh_focused_before = state.focused.index;
    g_dluma_workshop_refresh_focused_after = restored_focused;
    g_dluma_workshop_refresh_active_before = state.active_index;
    g_dluma_workshop_refresh_active_after = restored_active;
    g_dluma_workshop_refresh_first_visible_before = state.first_visible;
    g_dluma_workshop_refresh_first_visible_after = restored_first_visible;
    g_dluma_workshop_refresh_identity_kind =
        active_identity->identity_kind;
    g_dluma_workshop_refresh_published_id =
        active_identity->published_id;
    dluma_atomic_exchange(&g_dluma_workshop_refresh_diagnostic_pending, 1);
    dluma_atomic_decrement(&g_dluma_workshop_refresh_depth);
}

static void __fastcall dluma_ui_workshop_fill_maps_hook(void *screen)
{
    DlumaWorkshopFillMapsFn original;
    dluma_atomic_increment(&g_dluma_registry_active_calls);
    original = g_dluma_workshop_fill_maps_original;
    if (dluma_ui_is_value_editor_screen(screen))
    {
        /* The value editor has no Workshop map list. */
    }
    else if (!g_dluma_registry_hooks_stopping &&
        !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
        dluma_ui_is_stock_workshop_screen(screen))
    {
        /* ShowScreen performs a direct native fill before it schedules this
         * five-second CRTTI callback.  Suppress only the scheduled callback;
         * explicit refreshes invoke the captured original from post-update. */
        dluma_atomic_increment(
            &g_dluma_workshop_periodic_refresh_suppressed);
    }
    else if (original)
    {
        original(screen);
    }
    dluma_atomic_decrement(&g_dluma_registry_active_calls);
}

static void dluma_ui_workshop_drain_refresh_diagnostic(void)
{
    const char *identity = "none";
    LONG kind;
    if (dluma_atomic_exchange(&g_dluma_workshop_rail_diagnostic_pending, 0))
    {
        dluma_log_pair(
            "INFO", "workshop_menu_uses_background_screen_name", "enabled");
        dluma_log_line(
            "INFO",
            "MenuSteamWorkshop enabled the stock MenuBackgroundDL previous/current screen rail for its exact root.");
    }
    if (dluma_atomic_exchange(
            &g_dluma_workshop_periodic_refresh_suppressed, 0) > 0 &&
        dluma_atomic_compare_exchange(
            &g_dluma_workshop_periodic_refresh_log_once, 1, 0) == 0)
        dluma_log_pair("INFO", "workshop_periodic_refresh",
                     "suppressed_visible_rebuild");
    {
        LONG manual_refreshes = dluma_atomic_exchange(
            &g_dluma_workshop_manual_refresh_count, 0);
        if (manual_refreshes > 0)
            dluma_log_pair("INFO", "workshop_manual_refresh",
                         "completed_once");
        else if (manual_refreshes < 0)
            dluma_log_pair("WARN", "workshop_manual_refresh",
                         "optional_fillmaps_unavailable");
    }
    if (dluma_atomic_exchange(
            &g_dluma_workshop_initial_focus_pending, 0) &&
        dluma_atomic_compare_exchange(
            &g_dluma_workshop_initial_focus_log_once, 1, 0) == 0)
    {
        dluma_log_pair(
            "INFO", "workshop_menu_initial_focus",
            "first_selectable_row_focused");
        dluma_log_u64(
            "INFO", "workshop_menu_initial_focus_index",
            (ULONGLONG)(unsigned int)g_dluma_workshop_initial_focus_index);
    }
    if (!dluma_atomic_exchange(
            &g_dluma_workshop_refresh_diagnostic_pending, 0))
        return;
    if (dluma_atomic_increment(
            &g_dluma_workshop_refresh_diagnostic_log_count) >
        DLUMA_WORKSHOP_REFRESH_DIAGNOSTIC_LOG_LIMIT)
        return;
    kind = g_dluma_workshop_refresh_identity_kind;
    if (kind == DLUMA_WORKSHOP_REFRESH_IDENTITY_PUBLISHED_ID)
        identity = "published_id";
    else if (kind == DLUMA_WORKSHOP_REFRESH_IDENTITY_PROJECT_ROOT)
        identity = "project_root";
    else if (kind == DLUMA_WORKSHOP_REFRESH_IDENTITY_INDEX)
        identity = "index_fallback";
    dluma_log_pair("INFO", "workshop_menu_list_restore_identity", identity);
    dluma_log_u64("INFO", "workshop_menu_list_selected_before",
                (ULONGLONG)(unsigned int)g_dluma_workshop_refresh_selected_before);
    dluma_log_u64("INFO", "workshop_menu_list_selected_after",
                (ULONGLONG)(unsigned int)g_dluma_workshop_refresh_selected_after);
    dluma_log_u64("INFO", "workshop_menu_list_focused_before",
                (ULONGLONG)(unsigned int)g_dluma_workshop_refresh_focused_before);
    dluma_log_u64("INFO", "workshop_menu_list_focused_after",
                (ULONGLONG)(unsigned int)g_dluma_workshop_refresh_focused_after);
    dluma_log_u64("INFO", "workshop_menu_list_active_before",
                (ULONGLONG)(unsigned int)g_dluma_workshop_refresh_active_before);
    dluma_log_u64("INFO", "workshop_menu_list_active_after",
                (ULONGLONG)(unsigned int)g_dluma_workshop_refresh_active_after);
    dluma_log_u64("INFO", "workshop_menu_list_first_visible_before",
                (ULONGLONG)(unsigned int)
                    g_dluma_workshop_refresh_first_visible_before);
    dluma_log_u64("INFO", "workshop_menu_list_first_visible_after",
                (ULONGLONG)(unsigned int)
                    g_dluma_workshop_refresh_first_visible_after);
    if (g_dluma_workshop_refresh_published_id)
        dluma_log_u64("INFO", "workshop_menu_list_restore_published_id",
                    g_dluma_workshop_refresh_published_id);
}

static void __fastcall dluma_ui_workshop_post_hook(void *screen)
{
    DlumaWorkshopPostUpdateFn original;
    int log_first = 0;
    dluma_atomic_increment(&g_dluma_registry_active_calls);
    original = g_dluma_workshop_post_original;
    if (!g_dluma_registry_hooks_stopping &&
        !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
        dluma_ui_is_value_editor_screen(screen) && g_dluma_base_main_menu_post)
    {
        g_dluma_base_main_menu_post(screen);
        dluma_ui_value_editor_post(screen);
    }
    else if (!g_dluma_registry_hooks_stopping &&
        !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
        dluma_ui_is_mods_registry_screen(screen) &&
        g_dluma_base_main_menu_post)
    {
        log_first = dluma_atomic_compare_exchange(
                        &g_dluma_registry_post_log_once, 1, 0) == 0;
        if (log_first)
            dluma_log_line("INFO", "MenuDLUMAMods first generic post-update entered.");
        g_dluma_base_main_menu_post(screen);
        /* List population remains deferred until the first completed generic
         * post-update so the inherited controller has finished binding the
         * ListBoxOptionsV presenters and its native option rows. */
        if (dluma_atomic_exchange(&g_dluma_registry_deferred_populate, 0))
        {
            dluma_ui_registry_populate_list(screen, 0);
            dluma_log_line("INFO", "global_mod_registry_deferred_population_completed");
        }
        else if (dluma_atomic_exchange(
                     &g_dluma_registry_option_refresh_pending, 0))
        {
            char restore_key[DLUMA_SHA256_HEX_CAPACITY];
            dluma_str_copy(
                restore_key, DLUMA_ARRAY_COUNT(restore_key),
                g_dluma_ui_registry_option_refresh_key);
            g_dluma_ui_registry_option_refresh_key[0] = 0;
            dluma_ui_registry_populate_list(screen, restore_key);
            dluma_log_line(
                "INFO",
                "MODS native option row refreshed after selection.");
        }
        else
        {
            dluma_ui_registry_refresh_if_needed(screen);
        }
        ++g_dluma_ui_registry_post_generation;
        if (log_first)
            dluma_log_line("INFO", "MenuDLUMAMods first generic post-update completed.");
    }
    else if (!g_dluma_registry_hooks_stopping &&
             !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
             dluma_ui_is_logs_screen(screen) &&
             g_dluma_base_main_menu_post)
    {
        g_dluma_base_main_menu_post(screen);
        if (dluma_atomic_exchange(&g_dluma_logs_deferred_populate, 0))
            dluma_ui_logs_populate_list(screen);
        else
            dluma_ui_logs_refresh_if_needed(screen);
    }
    else if (!g_dluma_registry_hooks_stopping &&
             !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
             dluma_ui_is_validated_quest_log_screen(screen) &&
             g_dluma_base_main_menu_post)
    {
        g_dluma_base_main_menu_post(screen);
        if (dluma_atomic_exchange(&g_dluma_quest_log_deferred_populate, 0))
        {
            dluma_ui_quest_log_populate_list(screen);
            dluma_log_line("INFO", "Quest Log deferred population completed.");
        }
        else
        {
            dluma_ui_quest_log_refresh_if_needed(screen);
        }
    }
    else if (!g_dluma_registry_hooks_stopping &&
             !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
             dluma_ui_is_mod_details_screen(screen) &&
             g_dluma_base_main_menu_post)
    {
        ULONGLONG revision = 0;
        g_dluma_base_main_menu_post(screen);
        if (dluma_atomic_exchange(
                &g_dluma_mod_details_deferred_populate, 0))
            dluma_ui_mod_details_populate_list(screen);
        else if (g_dluma_ui_mod_details_staged &&
                 !g_dluma_ui_mod_details_stale)
        {
            if (g_dluma_ui_mod_details_kind == DLUMA_REGISTRY_ROW_KIND_ASSET &&
                g_dluma_ui_mod_details_asset_row.asset_kind == DLUMA_ASSET_MOD_KIND_OVERRIDE)
            {
                if (dluma_asset_mods_desired_revision() != g_dluma_ui_mod_details_asset.desired_revision ||
                    dluma_asset_mods_effective_revision() != g_dluma_ui_mod_details_asset.effective_revision)
                    dluma_ui_mod_details_populate_list(screen);
            }
            else if (g_dluma_ui_mod_details_kind ==
                DLUMA_REGISTRY_ROW_KIND_ASSET)
                revision = 0;
            else if (g_dluma_ui_mod_details_kind ==
                DLUMA_REGISTRY_ROW_KIND_NATIVE)
                (void)dluma_native_mods_snapshot(0, 0, &revision);
            else if (g_dluma_ui_mod_details_kind ==
                     DLUMA_REGISTRY_ROW_KIND_MANAGED)
                (void)dluma_managed_mods_snapshot(0, 0, &revision);
            else
                (void)dluma_lua_snapshot_globals_with_revision(
                    0, 0, 0, &revision);
            if (g_dluma_ui_mod_details_kind !=
                    DLUMA_REGISTRY_ROW_KIND_ASSET &&
                revision !=
                (g_dluma_ui_mod_details_kind ==
                         DLUMA_REGISTRY_ROW_KIND_NATIVE
                     ? g_dluma_ui_mod_details_native_request
                           .registry_revision
                     : (g_dluma_ui_mod_details_kind ==
                                DLUMA_REGISTRY_ROW_KIND_MANAGED
                            ? g_dluma_ui_mod_details_managed_request
                                  .registry_revision
                            : g_dluma_ui_mod_details_request
                                  .registry_revision)))
                dluma_ui_mod_details_populate_list(screen);
        }
        {
            int selected =
                dluma_ui_list_get_selection(g_dluma_ui_mod_details_list);
            int focused =
                dluma_ui_list_get_focused_index(
                    g_dluma_ui_mod_details_list);
            int active = selected >= 0 ? selected : focused;
            if (active >= 0 &&
                active < (int)g_dluma_ui_mod_details_row_count &&
                (unsigned int)active !=
                    g_dluma_ui_mod_details_selected_row)
                dluma_ui_mod_details_update_for_row(
                    (unsigned int)active);
        }
        dluma_ui_mod_details_confirm_visible(screen);
    }
    else if (!g_dluma_registry_hooks_stopping &&
             !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
             dluma_ui_is_mod_config_screen(screen) &&
             g_dluma_base_main_menu_post)
    {
        ULONGLONG revision = 0;
        g_dluma_base_main_menu_post(screen);
        if (dluma_atomic_exchange(
                &g_dluma_mod_config_deferred_populate, 0))
            dluma_ui_mod_config_populate_list(screen);
        else if (dluma_atomic_exchange(
                     &g_dluma_mod_config_option_refresh_pending, 0))
        {
            LONG setting_index = dluma_atomic_exchange(
                &g_dluma_mod_config_option_refresh_index, -1);
            dluma_ui_mod_config_populate_list(screen);
            if (setting_index >= 0)
                dluma_ui_mod_config_select_setting(
                    (unsigned int)setting_index);
            dluma_ui_mod_config_set_status(
                "DLUMA_ModConfig_Saved", "SAVED.");
        }
        if (g_dluma_ui_mod_config_owner_kind ==
            DLUMA_MOD_CONFIG_OWNER_NATIVE)
            (void)dluma_native_mods_snapshot(0, 0, &revision);
        else if (g_dluma_ui_mod_config_owner_kind ==
                 DLUMA_MOD_CONFIG_OWNER_CSHARP)
            (void)dluma_managed_mods_snapshot(0, 0, &revision);
        else
            (void)dluma_lua_snapshot_globals_with_revision(
                0, 0, 0, &revision);
        if (g_dluma_ui_mod_config_staged &&
            revision !=
                (g_dluma_ui_mod_config_owner_kind ==
                         DLUMA_MOD_CONFIG_OWNER_NATIVE
                     ? g_dluma_ui_mod_config_native_request
                           .registry_revision
                     : (g_dluma_ui_mod_config_owner_kind ==
                                DLUMA_MOD_CONFIG_OWNER_CSHARP
                            ? g_dluma_ui_mod_config_managed_request
                                  .registry_revision
                            : g_dluma_ui_mod_config_request
                                  .registry_revision)) &&
            !g_dluma_ui_mod_config_stale)
        {
            if (g_dluma_ui_mod_config_edit_mode)
                dluma_ui_mod_config_close_editor(0);
            dluma_ui_mod_config_populate_list(screen);
        }
        {
            int selected =
                dluma_ui_list_get_selection(g_dluma_ui_mod_config_list);
            int focused =
                dluma_ui_list_get_focused_index(
                    g_dluma_ui_mod_config_list);
            int active = selected >= 0 ? selected : focused;
            if (active >= 0 &&
                active < (int)g_dluma_ui_mod_config_row_count &&
                (unsigned int)active !=
                    g_dluma_ui_mod_config_selected_row)
                dluma_ui_mod_config_update_for_row(
                    (unsigned int)active);
        }
    }
    else if (!g_dluma_registry_hooks_stopping &&
             !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
             dluma_ui_is_custom_menu_screen(screen) &&
             g_dluma_base_main_menu_post)
    {
        g_dluma_base_main_menu_post(screen);
        if (dluma_atomic_exchange(
                &g_dluma_custom_menu_deferred_populate, 0))
        {
            char saved_status[DLUMA_UI_WIDE_ROW_CAPACITY];
            dluma_ui_custom_menu_populate_list(screen);
            if (dluma_atomic_exchange(
                    &g_dluma_custom_menu_saved_status_pending, 0))
            {
                dluma_ui_localize_text(
                    "DLUMA_CustomMenu_SavedRestart",
                    "SAVED. THE SELECTED MAIN MENU WILL APPLY ON THE NEXT LAUNCH.",
                    saved_status, DLUMA_ARRAY_COUNT(saved_status));
                dluma_ui_set_text_element_text(
                    g_dluma_ui_custom_menu_status, saved_status);
            }
            dluma_log_line(
                "INFO",
                "Custom Main Menu selector deferred population completed.");
        }
        else
        {
            int selected = dluma_ui_list_get_selection(
                g_dluma_ui_custom_menu_list);
            int focused = dluma_ui_list_get_focused_index(
                g_dluma_ui_custom_menu_list);
            int active = selected >= 0 ? selected : focused;
            if (active >= 0 &&
                active < (int)g_dluma_ui_custom_menu_row_count &&
                (unsigned int)active !=
                    g_dluma_ui_custom_menu_selected_row)
                dluma_ui_custom_menu_update_for_row(
                    (unsigned int)active);
        }
        ++g_dluma_ui_custom_menu_post_generation;
    }
    else if (!g_dluma_registry_hooks_stopping &&
             !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
             dluma_ui_is_loader_settings_screen(screen) &&
             g_dluma_base_main_menu_post)
    {
        ++g_dluma_ui_settings_post_generation;
        g_dluma_base_main_menu_post(screen);
        if (dluma_atomic_exchange(&g_dluma_settings_deferred_populate, 0))
        {
            dluma_ui_settings_populate_list(screen);
            dluma_log_line("INFO", "Loader settings deferred population completed.");
        }
        else if (dluma_atomic_exchange(
                     &g_dluma_settings_option_refresh_pending, 0))
        {
            int kept_off = (int)dluma_atomic_exchange(
                &g_dluma_settings_option_refresh_kept_off, 0);
            LONG setting_index = dluma_atomic_exchange(
                &g_dluma_settings_option_refresh_index, -1);
            dluma_ui_settings_populate_list(screen);
            if (setting_index >= 0 &&
                (unsigned int)setting_index <
                    DLUMA_ARRAY_COUNT(g_dluma_loader_settings))
                dluma_ui_settings_select_setting((unsigned int)setting_index);
            if (kept_off)
            {
                dluma_ui_settings_set_experimental_warning_status(
                    "DLUMA_Settings_GameFixes_CustomMapAssetIsolation_ExperimentalUnavailable",
                    "EXPERIMENTAL CONFIRMATION IS UNAVAILABLE. THE SETTING REMAINS OFF.");
            }
            else
            {
                dluma_ui_set_text_element_text(
                    g_dluma_ui_settings_status,
                    "SAVED. THE NEW VALUE WILL APPLY AFTER RESTARTING THE LOADER.");
            }
            dluma_log_line(
                "INFO", "Loader settings native option row refreshed after selection.");
        }
        {
            int selected = dluma_ui_list_get_selection(g_dluma_ui_settings_list);
            int focused = dluma_ui_list_get_focused_index(
                g_dluma_ui_settings_list);
            int active = -1;
            if ((g_dluma_ui_settings_selection_pending ||
                 selected != g_dluma_ui_settings_observed_selection) &&
                selected >= 0 && selected < (int)g_dluma_ui_settings_row_count)
                active = selected;
            else if (focused != g_dluma_ui_settings_observed_focus &&
                     focused >= 0 && focused < (int)g_dluma_ui_settings_row_count)
                active = focused;
            else if (g_dluma_ui_settings_selected_row >=
                     g_dluma_ui_settings_row_count)
                active = selected >= 0 ? selected : focused;
            g_dluma_ui_settings_observed_selection = selected;
            g_dluma_ui_settings_observed_focus = focused;
            g_dluma_ui_settings_selection_pending = 0;
            if (!g_dluma_ui_settings_edit_mode &&
                !g_dluma_ui_settings_experimental_warning_mode &&
                active >= 0 && active < (int)g_dluma_ui_settings_row_count &&
                (unsigned int)active != g_dluma_ui_settings_selected_row)
                dluma_ui_settings_update_for_row((unsigned int)active);
        }
    }
    else if (!g_dluma_registry_hooks_stopping &&
             !g_dluma_registry_runtime_disabled && !g_dluma.stop_requested &&
             dluma_ui_is_stock_workshop_screen(screen) && original)
    {
        int refreshed = 0;
        original(screen);
        if (dluma_atomic_exchange(
                &g_dluma_workshop_manual_refresh_pending, 0))
        {
            if (g_dluma_workshop_fill_maps_original)
            {
                dluma_ui_workshop_refresh_now(
                    screen, g_dluma_workshop_fill_maps_original);
                dluma_atomic_increment(
                    &g_dluma_workshop_manual_refresh_count);
                refreshed = 1;
            }
            else
            {
                dluma_atomic_exchange(
                    &g_dluma_workshop_manual_refresh_count, -1);
            }
        }
        if (!refreshed)
            dluma_ui_workshop_present(screen);
        /*
         * The validated stock Workshop post-update is the authoritative
         * frontend/game thread while this screen is visible.  Remote IDs are
         * queued by presentation above; advance registered Steam call
         * results here so authors, HTTP previews, cache jobs, and textures do
         * not depend on an OnFrame callback that may stop before menu entry.
         */
        dluma_workshop_menu_game_thread_tick();
        {
            ULONGLONG revision =
                dluma_workshop_menu_presentation_revision();
            if (revision !=
                    g_dluma_workshop_last_presentation_revision)
            {
                g_dluma_workshop_last_presentation_revision = revision;
                dluma_ui_workshop_present(screen);
                if (dluma_atomic_increment(
                        &g_dluma_workshop_presentation_diagnostic_log_count) <=
                    DLUMA_WORKSHOP_PRESENTATION_DIAGNOSTIC_LOG_LIMIT)
                    dluma_log_u64(
                        "INFO",
                        "workshop_menu_presentation_revision",
                        revision);
            }
        }
        dluma_ui_workshop_texture_asset_tick(
            g_dluma_workshop_menu_level, 1);
        if (dluma_atomic_compare_exchange(
                &g_dluma_workshop_enrichment_post_log_once, 1, 0) == 0)
            dluma_log_pair(
                "INFO", "workshop_enrichment_tick_source",
                "workshop_post_update");
    }
    else if (original)
    {
        original(screen);
    }
    dluma_ui_value_editor_restore_parent(screen);
    dluma_atomic_decrement(&g_dluma_registry_active_calls);
}

