    if (g_dluma_set_element_text_color && g_dluma_set_text_element_color)
        dluma_log_line(
            "INFO",
            "Logs severity colors use exported IUIElementControl/IUIText text-color APIs.");
    else
        dluma_log_line(
            "WARN",
            "Logs severity color exports are unavailable; readable default XUI colors remain enabled.");

    g_dluma_workshop_post_original = (DlumaWorkshopPostUpdateFn)expected[0];
    g_dluma_workshop_init_original = (DlumaWorkshopOnInitFn)expected[1];
    g_dluma_workshop_show_original = (DlumaWorkshopShowScreenFn)expected[2];
    g_dluma_workshop_selection_original = (DlumaWorkshopSelectionFn)expected[3];
    g_dluma_workshop_option_selected_original =
        (DlumaWorkshopOptionSelectedFn)expected[4];
    g_dluma_workshop_button_original = (DlumaWorkshopButtonFn)expected[5];
    g_dluma_workshop_double_original = (DlumaWorkshopDoubleClickFn)expected[6];
    g_dluma_workshop_uses_3d_rotation_original =
        (DlumaWorkshopUses3dRotationFn)expected[7];
    g_dluma_workshop_get_3d_position_original =
        (DlumaWorkshopGet3dPositionNameFn)expected[8];
    g_dluma_workshop_uses_background_screen_name_original =
        (DlumaWorkshopUsesBackgroundScreenNameFn)expected[9];
    g_dluma_base_main_menu_post =
        (DlumaWorkshopPostUpdateFn)(base + DLUMA_DEVTOOLS_BASE_MAIN_MENU_POST_RVA);
    g_dluma_base_main_menu_init =
        (DlumaWorkshopOnInitFn)(base + DLUMA_DEVTOOLS_BASE_MAIN_MENU_INIT_RVA);
    g_dluma_base_main_menu_show =
        (DlumaWorkshopShowScreenFn)(base + DLUMA_DEVTOOLS_BASE_MAIN_MENU_SHOW_RVA);
    g_dluma_base_main_menu_selection =
        (DlumaWorkshopSelectionFn)(base + DLUMA_DEVTOOLS_BASE_MAIN_MENU_SELECTION_RVA);
    g_dluma_base_main_menu_button =
        (DlumaWorkshopButtonFn)(base + DLUMA_DEVTOOLS_BASE_MAIN_MENU_BUTTON_RVA);
    g_dluma_list_add_item =
        (DlumaListAddItemFn)(base + DLUMA_DEVTOOLS_LIST_ADD_ITEM_RVA);
    g_dluma_list_clear =
        (DlumaListClearFn)(base + DLUMA_DEVTOOLS_LIST_CLEAR_RVA);
    g_dluma_list_remove_item =
        (DlumaListRemoveItemFn)(base + DLUMA_DEVTOOLS_LIST_REMOVE_ITEM_RVA);
    g_dluma_list_get_selection =
        (DlumaListGetSelectionFn)(base + DLUMA_DEVTOOLS_LIST_GET_SELECTION_RVA);
    g_dluma_list_get_selected_item =
        (DlumaListGetSelectedItemFn)(base + DLUMA_DEVTOOLS_LIST_GET_SELECTED_ITEM_RVA);
    g_dluma_list_set_selection =
        (DlumaListSetSelectionFn)(base + DLUMA_DEVTOOLS_LIST_SET_SELECTION_RVA);
    g_dluma_list_set_capacity =
        (DlumaListSetCapacityFn)(base + DLUMA_DEVTOOLS_LIST_SET_CAPACITY_RVA);
    g_dluma_option_add_explicit =
        (DlumaOptionAddExplicitFn)(base + DLUMA_DEVTOOLS_OPTION_ADD_EXPLICIT_RVA);
    g_dluma_option_set_selection =
        (DlumaOptionSetSelectionFn)(base + DLUMA_DEVTOOLS_OPTION_SET_SELECTION_RVA);
    g_dluma_set_element_text =
        (DlumaSetElementTextFn)(base + DLUMA_DEVTOOLS_ELEMENT_SET_TEXT_RVA);
    g_dluma_registry_gamedll_base = base;
    g_dluma_workshop_post_vtable_slot = slots[0];
    g_dluma_workshop_init_vtable_slot = slots[1];
    g_dluma_workshop_show_vtable_slot = slots[2];
    g_dluma_workshop_selection_vtable_slot = slots[3];
    g_dluma_workshop_option_selected_vtable_slot = slots[4];
    g_dluma_workshop_button_vtable_slot = slots[5];
    g_dluma_workshop_double_vtable_slot = slots[6];
    g_dluma_workshop_uses_3d_rotation_vtable_slot = slots[7];
    g_dluma_workshop_get_3d_position_vtable_slot = slots[8];
    g_dluma_workshop_uses_background_screen_name_vtable_slot = slots[9];
    dluma_atomic_exchange(&g_dluma_registry_hooks_stopping, 1);
    for (i = 0; i < DLUMA_ARRAY_COUNT(slots); ++i)
    {
        if (!dluma_ui_registry_patch_slot(slots[i], expected[i], hooks[i]))
        {
            unsigned int j;
            int rollback_ok = 1;
            dluma_ui_registry_log_validation_failure(
                "vtable_patch", slots[i] ? *slots[i] : 0, expected[i]);
            for (j = patched; j > 0; --j)
                rollback_ok &= dluma_ui_registry_restore_slot(
                    slots[j - 1U], hooks[j - 1U], expected[j - 1U]);
            if (!rollback_ok)
            {
                /* A route that could not be restored must retain all callback
                 * dependencies in pass-through mode until orderly shutdown. */
                g_dluma_registry_hooks_installed = 1;
                g_dluma_registry_hooks_detached = 0;
                g_dluma_registry_runtime_disabled = 1;
                dluma_log_pair("ERROR", "global_mod_registry_failure_stage",
                             "transaction_rollback_failed_retained");
            }
            else
            {
                g_dluma_registry_hooks_installed = 0;
                g_dluma_registry_hooks_detached = 1;
                dluma_atomic_exchange(&g_dluma_registry_hooks_stopping, 0);
            }
            return 0;
        }
        ++patched;
    }
    g_dluma_registry_active_calls = 0;
    g_dluma_registry_post_log_once = 0;
    g_dluma_registry_selection_log_once = 0;
    g_dluma_settings_uses_3d_rotation_log_once = 0;
    g_dluma_settings_3d_position_log_once = 0;
    g_dluma_settings_uses_background_screen_name_log_once = 0;
