    g_dluma_workshop_uses_background_screen_name_vtable_slot = 0;
    g_dluma_workshop_fill_maps_callback_slot = 0;
    g_dluma_workshop_fill_maps_hook_installed = 0;
    g_dluma_workshop_fill_maps_hook_owned = 0;
    g_dluma_workshop_fill_maps_hook_detached = 1;
    g_dluma_workshop_post_original = 0;
    g_dluma_workshop_init_original = 0;
    g_dluma_workshop_show_original = 0;
    g_dluma_workshop_selection_original = 0;
