static int dluma_ui_stock_popup_visible(void *root)
{
    static const char *dialog_ids[] = {
        "G_MsgGroup", "G_YesNoPopup", "G_YesNo", "G_YesNoDialog"};
    unsigned int i;
    if (!root)
        return 1;
    for (i = 0; i < DLUMA_ARRAY_COUNT(dialog_ids); ++i)
    {
        void *control = dluma_ui_find_required_child(
            root, dialog_ids[i]);
        if (control && dluma_ui_is_element_visible(control))
            return 1;
    }
    return 0;
}

static void dluma_ui_first_launch_clear_controls(void)
{
    g_dluma_first_launch_root = 0;
    g_dluma_first_launch_popup = 0;
    g_dluma_first_launch_yes = 0;
    g_dluma_first_launch_no = 0;
    g_dluma_first_launch_stable_since = 0;
    g_dluma_first_launch_visible = 0;
}

static void dluma_ui_first_launch_hide(void)
{
    void *mods_button = g_dluma_first_launch_root
        ? dluma_ui_find_required_child(g_dluma_first_launch_root, "B_Mods") : 0;
    dluma_ui_set_element_visible(g_dluma_first_launch_popup, 0);
    if (g_dluma_set_element_can_focus)
    {
        if (g_dluma_first_launch_yes)
            g_dluma_set_element_can_focus(g_dluma_first_launch_yes, 0);
        if (g_dluma_first_launch_no)
            g_dluma_set_element_can_focus(g_dluma_first_launch_no, 0);
    }
    g_dluma_first_launch_visible = 0;
    if (mods_button)
        dluma_ui_focus_element(mods_button);
}

static void dluma_ui_first_launch_defer(const char *reason, ULONGLONG now)
{
    if (dluma_stricmp(g_dluma_first_launch_deferred_reason, reason) != 0 ||
        !g_dluma_first_launch_deferred_ms ||
        now - g_dluma_first_launch_deferred_ms >= 5000U)
    {
        dluma_str_copy(g_dluma_first_launch_deferred_reason,
                       DLUMA_ARRAY_COUNT(g_dluma_first_launch_deferred_reason),
                       reason);
        g_dluma_first_launch_deferred_ms = now;
        dluma_log_pair("INFO", "first_launch_notice_deferred", reason);
    }
}

static int dluma_ui_first_launch_tick(void *root, ULONGLONG now)
{
    void *title;
    void *body;
    char text[1024];
    char label[64];
    if (!dluma_first_launch_is_pending())
        return 0;
    if (g_dluma_first_launch_declined)
        return 1;
    if (!g_dluma_set_element_can_focus || !g_dluma_set_element_focus ||
        !g_dluma_set_element_visible || !g_dluma_get_element_visible)
    {
        dluma_ui_first_launch_defer("dialog_controls_unavailable", now);
        return 0;
    }
    if (!root || !dluma_is_readable(root, sizeof(void *)) ||
        !dluma_ui_is_element_visible(root))
    {
        dluma_ui_first_launch_defer("main_menu_hidden", now);
        return 0;
    }
    if (g_dluma_first_launch_root != root)
    {
        dluma_ui_first_launch_clear_controls();
        g_dluma_first_launch_root = root;
        g_dluma_first_launch_stable_since = now;
    }
    g_dluma_first_launch_popup = dluma_ui_find_required_child(
        g_dluma_first_launch_root, "G_DLUMAFirstLaunchPopup");
    g_dluma_first_launch_yes = dluma_ui_find_required_child(
        g_dluma_first_launch_root, "B_FirstLaunchYes");
    g_dluma_first_launch_no = dluma_ui_find_required_child(
        g_dluma_first_launch_root, "B_FirstLaunchNo");
    title = dluma_ui_find_required_child(
        g_dluma_first_launch_root, "T_FirstLaunchTitle");
    body = dluma_ui_find_required_child(
        g_dluma_first_launch_root, "T_FirstLaunchBody");
    if (!g_dluma_first_launch_popup || !g_dluma_first_launch_yes ||
        !g_dluma_first_launch_no || !title || !body)
    {
        dluma_ui_first_launch_defer("first_launch_controls_missing", now);
        return 0;
    }
    if (g_dluma_first_launch_visible &&
        dluma_ui_is_element_visible(g_dluma_first_launch_popup))
        return 1;
    if (now - g_dluma_first_launch_stable_since < 1200U ||
        g_dluma_mods_transition_screen_id >= 0 ||
        g_dluma_mods_native_visible_logged ||
        dluma_ui_stock_popup_visible(g_dluma_first_launch_root))
    {
        dluma_ui_first_launch_defer("main_menu_not_ready_for_dialog", now);
        return 0;
    }
    dluma_ui_localize_text(
        "DLUMA_FirstLaunch_Title", "Welcome to DLUMA",
        text, DLUMA_ARRAY_COUNT(text));
    dluma_ui_set_text_element_long(title, text);
    dluma_ui_localize_text(
        "DLUMA_FirstLaunch_Body",
        "DLUMA is very early work in progress. Bugs, crashes, and unfinished features are to be expected. Some issues may also come from Dying Light itself or other installed mods.\n\nWould you like to continue?",
        text, DLUMA_ARRAY_COUNT(text));
    dluma_ui_set_text_element_long(body, text);
    dluma_ui_localize_text(
        "DLUMA_FirstLaunch_Yes", "Yes", label, DLUMA_ARRAY_COUNT(label));
    dluma_ui_set_element_text(g_dluma_first_launch_yes, label);
    dluma_ui_localize_text(
        "DLUMA_FirstLaunch_No", "No", label, DLUMA_ARRAY_COUNT(label));
    dluma_ui_set_element_text(g_dluma_first_launch_no, label);
    g_dluma_set_element_can_focus(g_dluma_first_launch_yes, 1);
    g_dluma_set_element_can_focus(g_dluma_first_launch_no, 1);
    dluma_ui_set_element_visible(g_dluma_first_launch_popup, 1);
    dluma_ui_focus_element(g_dluma_first_launch_yes);
    g_dluma_first_launch_visible = 1;
    dluma_log_line("INFO", "first_launch_notice_opened");
    return 1;
}

void dluma_ui_first_launch_main_menu_post(void *menu_main)
{
    if (g_dluma_ui_stopping || !g_dluma.started || g_dluma.stop_requested)
        return;
    (void)dluma_ui_first_launch_tick(menu_main, GetTickCount64());
}

static int dluma_ui_first_launch_handle_button(void *button)
{
    if (!g_dluma_first_launch_visible)
        return g_dluma_first_launch_declined != 0;
    if (dluma_ui_object_id_equals(button, "B_FirstLaunchYes"))
    {
        (void)dluma_first_launch_accept();
        dluma_ui_first_launch_hide();
        dluma_log_line("INFO", "first_launch_notice_accepted");
    }
    else if (dluma_ui_object_id_equals(button, "B_FirstLaunchNo") ||
             dluma_ui_object_id_equals(button, "B_Back") ||
             dluma_ui_object_id_equals(button, "ButtonBack") ||
             dluma_ui_object_id_equals(button, "ID_BACK"))
    {
        g_dluma_first_launch_declined = (unsigned char)
            dluma_shutdown_schedule_orderly_close_ex(
                DLUMA_CLOSE_ORIGIN_FIRST_LAUNCH_DECLINED,
                "First-launch notice declined", 0);
        if (!g_dluma_first_launch_declined)
            dluma_log_line("WARN", "first_launch_orderly_close_unavailable");
    }
    return 1;
}

static void dluma_ui_new_global_copy_safe_name(
    char *out, unsigned int capacity, const char *source)
{
    unsigned int i = 0;
    if (!out || !capacity)
        return;
    out[0] = 0;
    while (source && source[i] && i + 1U < capacity && i < 96U)
    {
        unsigned char c = (unsigned char)source[i];
        out[i] = (c < 32U || c == 127U) ? ' ' : (char)c;
        ++i;
    }
    out[i] = 0;
}

static void dluma_ui_new_global_hide_popup(void)
{
    void *mods_button = g_dluma_new_global_main_root
                            ? dluma_ui_find_required_child(g_dluma_new_global_main_root, "B_Mods")
                            : 0;
    dluma_ui_set_element_visible(g_dluma_new_global_popup, 0);
    if (g_dluma_set_element_can_focus)
    {
        if (g_dluma_new_global_review)
            g_dluma_set_element_can_focus(g_dluma_new_global_review, 0);
        if (g_dluma_new_global_later)
            g_dluma_set_element_can_focus(g_dluma_new_global_later, 0);
    }
    if (mods_button)
        dluma_ui_focus_element(mods_button);
    g_dluma_new_global_waiting_visibility = 0;
    g_dluma_new_global_popup_visible = 0;
    memset(&g_dluma_new_global_pending_batch, 0,
           sizeof(g_dluma_new_global_pending_batch));
}

static void dluma_ui_new_global_tick(void *level, ULONGLONG now)
{
    DlumaGlobalUnseenBatch batch;
    char count[32];
    char safe_name[100];
    char message[512];
    if (!dluma_lua_snapshot_unseen_batch(&batch) || !batch.should_prompt)
    {
        if (!g_dluma_new_global_popup_visible &&
            !g_dluma_new_global_waiting_visibility)
            g_dluma_new_global_frontend_stable_since = 0;
        return;
    }
    if (!g_dluma_get_element_visible || !g_dluma_set_element_visible ||
        !g_dluma_set_element_focus || !g_dluma_set_element_can_focus)
    {
        dluma_ui_new_global_defer("required visible/focus capability unavailable", now);
        return;
    }
    if (!dluma_ui_new_global_resolve_main(level))
    {
        dluma_ui_new_global_defer("loader-owned MenuMain is not loaded and visible", now);
        return;
    }
    if (g_dluma_new_global_waiting_visibility)
    {
        if (!dluma_ui_is_element_visible(g_dluma_new_global_popup))
        {
            dluma_ui_new_global_defer("loader popup visibility not confirmed", now);
            return;
        }
        if (now - g_dluma_new_global_last_persist_attempt_ms < 1000)
            return;
        g_dluma_new_global_last_persist_attempt_ms = now;
        if (!dluma_lua_mark_unseen_batch_prompted(
                g_dluma_new_global_pending_batch.batch_fingerprint,
                g_dluma_new_global_pending_batch.registry_revision))
        {
            dluma_ui_new_global_defer("prompted-batch persistence failed or snapshot became stale", now);
            return;
        }
        g_dluma_new_global_waiting_visibility = 0;
        g_dluma_new_global_popup_visible = 1;
        dluma_log_pair("INFO", "new_global_popup_shown",
                     g_dluma_new_global_pending_batch.batch_fingerprint);
        return;
    }
    if (g_dluma_new_global_popup_visible ||
        dluma_ui_is_element_visible(g_dluma_new_global_popup))
        return;
    if (!g_dluma_new_global_frontend_stable_since ||
        now - g_dluma_new_global_frontend_stable_since < 1200)
    {
        dluma_ui_new_global_defer("frontend is not yet stable", now);
        return;
    }
    if (g_dluma_mods_transition_screen_id >= 0 ||
        g_dluma_mods_native_visible_logged)
    {
        dluma_ui_new_global_defer("screen transition is active", now);
        return;
    }
    if (dluma_ui_stock_popup_visible(g_dluma_new_global_main_root))
    {
        dluma_ui_new_global_defer("stock news or Yes/No popup is visible", now);
        return;
    }
    dluma_u64_to_text(batch.unseen_count, count, DLUMA_ARRAY_COUNT(count));
    dluma_ui_new_global_copy_safe_name(
        safe_name, DLUMA_ARRAY_COUNT(safe_name), batch.first_name);
    message[0] = 0;
    if (batch.unseen_count == 1U)
    {
        dluma_str_append(message, DLUMA_ARRAY_COUNT(message),
                       "A new global Lua mod was found: ");
        dluma_ui_html_append_escaped(message, DLUMA_ARRAY_COUNT(message),
                                   safe_name, "aggregate_mod_name");
        dluma_str_append(message, DLUMA_ARRAY_COUNT(message),
                       ".<br><br>It is disabled. Open MODS to review its details and permissions before enabling it.");
    }
    else
    {
        dluma_str_append(message, DLUMA_ARRAY_COUNT(message), count);
        dluma_str_append(message, DLUMA_ARRAY_COUNT(message),
                       " new global Lua mods were found.<br><br>They are disabled. Open MODS to review their details and permissions before enabling them.");
    }
    /* The XUI owns the static title/button labels. T_DLUMANewGlobalModsText is
     * an HTML UIButton presenter, so SetTextExplicit is supported; calling the
     * same helper on UISmartText/MyText presenters dispatches an invalid -1
     * vtable slot on this engine build. */
    dluma_ui_set_element_popup_text(g_dluma_new_global_text, message);
    g_dluma_set_element_can_focus(g_dluma_new_global_review, 1);
    g_dluma_set_element_can_focus(g_dluma_new_global_later, 1);
    dluma_ui_set_element_visible(g_dluma_new_global_popup, 1);
    /* Dismissing the notice is the safe default. Review enters another screen,
     * while Later performs no approval or runtime mutation. */
    dluma_ui_focus_element(g_dluma_new_global_later);
    g_dluma_new_global_pending_batch = batch;
    g_dluma_new_global_waiting_visibility = 1;
    g_dluma_new_global_last_persist_attempt_ms = 0;
}

static int dluma_ui_new_global_handle_button(
    void *menu_main, void *button, unsigned int event_code,
    DlumaMenuMainButtonFn original)
{
    int is_review;
    int is_later;
    void *mods_button;
    if (!g_dluma_new_global_popup_visible &&
        !dluma_ui_is_element_visible(g_dluma_new_global_popup))
        return 0;
    is_review = dluma_ui_object_id_equals(button, "B_DLUMAReviewMods");
    is_later = dluma_ui_object_id_equals(button, "B_DLUMALater") ||
               dluma_ui_object_id_equals(button, "B_Back") ||
               dluma_ui_object_id_equals(button, "ButtonBack") ||
               dluma_ui_object_id_equals(button, "ID_BACK");
    if (is_review)
    {
        mods_button = g_dluma_new_global_main_root
                          ? dluma_ui_find_required_child(g_dluma_new_global_main_root, "B_Mods")
                          : 0;
        dluma_ui_new_global_hide_popup();
        g_dluma_new_global_focus_first_new = 1;
        dluma_log_line("INFO", "new_global_popup_review_selected");
        if (mods_button &&
            dluma_ui_route_mods_button_by_id(menu_main, mods_button))
        {
            dluma_log_line(
                "INFO",
                "Review Mods entered the B_Mods ID-driven ShowNextUI route.");
        }
        else if (mods_button && original)
        {
            original(menu_main, mods_button, event_code);
            dluma_log_line(
                "WARN",
                "Review Mods fell back to the packaged B_Mods PressPath route.");
        }
        else
        {
            g_dluma_new_global_focus_first_new = 0;
            dluma_log_line(
                "WARN",
                "Review Mods could not enter either validated B_Mods navigation route.");
        }
        return 1;
    }
    if (is_later)
    {
        dluma_ui_new_global_hide_popup();
        dluma_log_line("INFO", "new_global_popup_later_selected");
        return 1;
    }
    /* Trap every other MenuMain button event while the loader popup owns focus. */
    return 1;
}

static void dluma_ui_fail_safe_restore_main_menu(void)
{
    void *level = g_dluma_mods_transition_level ? g_dluma_mods_transition_level : g_dluma_mods_active_level;
    int main_id = g_dluma_mods_transition_main_screen_id >= 0 ? g_dluma_mods_transition_main_screen_id : g_dluma_mods_active_main_screen_id;
    int mods_id = g_dluma_mods_transition_screen_id >= 0 ? g_dluma_mods_transition_screen_id : g_dluma_mods_active_screen_id;

    if (!level || main_id < 0 || !g_dluma.engine.show_ui_screen)
        return;
    if (mods_id >= 0 && g_dluma.engine.hide_ui_screen)
        g_dluma.engine.hide_ui_screen(level, mods_id);
    g_dluma.engine.show_ui_screen(level, main_id, 0);
    dluma_log_u64("WARN", "mods_screen_fail_safe_main_restored_id",
                (ULONGLONG)(unsigned int)main_id);
    dluma_ui_clear_active_mods_screen();
}

static int dluma_ui_commit_pending_mods_transition(void)
{
    DlumaSwitchMenuScreenFn switch_next;
    void *menu_main = g_dluma_mods_transition_menu;
    void **vtable;
    BYTE *gamedll_base;
    DWORD timestamp;
    DWORD image_size;

    if (!menu_main || !dluma_is_readable(menu_main, sizeof(void *)) ||
        !g_dluma_mods_preflight_ready ||
        !dluma_ui_validate_mods_instance(g_dluma_mods_transition_level,
                                       g_dluma_mods_transition_screen_id, 0))
        return 0;
    vtable = *(void ***)menu_main;
    if (!vtable ||
        !dluma_is_readable((BYTE *)vtable + DLUMA_MENU_SWITCH_NEXT_VTABLE_BYTE_OFFSET,
                         sizeof(void *)))
        return 0;
    switch_next = *(DlumaSwitchMenuScreenFn *)((BYTE *)vtable +
                                             DLUMA_MENU_SWITCH_NEXT_VTABLE_BYTE_OFFSET);
    if (!switch_next || !g_dluma_menu_gamedll ||
        !dluma_ui_get_pe_identity(g_dluma_menu_gamedll, &timestamp, &image_size) ||
        timestamp != DLUMA_DEVTOOLS_GAMEDLL_TIMESTAMP ||
        image_size != DLUMA_DEVTOOLS_GAMEDLL_IMAGE_SIZE)
        return 0;
    gamedll_base = (BYTE *)g_dluma_menu_gamedll;
    if ((BYTE *)switch_next < gamedll_base ||
        (BYTE *)switch_next >= gamedll_base + image_size ||
        !dluma_is_readable((const void *)switch_next, 1))
        return 0;

    /* ShowNextUI has already recorded the destination and previous screen.
     * This virtual performs the same native commit normally reached from the
     * main screen's named-frame callback, preserving ShowPreviousUI/Back. */
    switch_next(menu_main);
    return 1;
}

static void dluma_ui_monitor_mods_transition(ULONGLONG now)
{
    int screen_id = g_dluma_mods_transition_screen_id;
    void *level = g_dluma_mods_transition_level;
    ULONGLONG elapsed;

    if (screen_id < 0)
        return;
    if (!level || !dluma_is_readable(level, sizeof(void *)))
    {
        dluma_log_line("WARN", "MODS transition was cancelled because its frontend level is no longer readable.");
        dluma_ui_clear_mods_transition();
        return;
    }
    if (g_dluma.engine.is_ui_screen_visible &&
        g_dluma.engine.is_ui_screen_visible(level, screen_id))
    {
        void *element = 0;
        void *owner_screen = 0;
        if (!dluma_ui_validate_mods_instance(level, screen_id, 1))
        {
            dluma_log_line("WARN", "MODS destination became visible without a valid MenuSteamWorkshop controller; restoring the main menu.");
            dluma_ui_fail_safe_restore_main_menu();
            dluma_ui_clear_mods_transition();
            return;
        }
        g_dluma_mods_active_level = level;
        g_dluma_mods_active_screen_id = screen_id;
        g_dluma_mods_active_main_screen_id = g_dluma_mods_transition_main_screen_id;
        dluma_log_u64("INFO", "mods_screen_native_transition_visible_id",
                    (ULONGLONG)(unsigned int)screen_id);

        /* Do not call ILevel::LoadUIScreen here.  Once the screen is visible,
         * FindUIScreen/GetOwnerScreen can inspect the existing instance without
         * constructing another controller or entering the XUI loader again. */
        if (g_dluma.engine.find_ui_screen && g_dluma.engine.get_owner_screen)
        {
            element = g_dluma.engine.find_ui_screen(level, screen_id);
            if (element)
                owner_screen = g_dluma.engine.get_owner_screen(element);
            if (owner_screen)
                dluma_ui_log_screen_script(owner_screen);
        }
        dluma_ui_clear_mods_transition();
        return;
    }
    if (!g_dluma_mods_transition_requested_ms)
        return;
    elapsed = now - g_dluma_mods_transition_requested_ms;
    if (!g_dluma_mods_transition_commit_attempted &&
        elapsed >= DLUMA_MODS_TRANSITION_COMMIT_DELAY_MS)
    {
        g_dluma_mods_transition_commit_attempted = 1;
        if (dluma_ui_commit_pending_mods_transition())
        {
            dluma_log_u64("WARN", "mods_screen_named_frame_commit_recovered_id",
                        (ULONGLONG)(unsigned int)screen_id);
        }
        else
        {
            dluma_log_u64("WARN", "mods_screen_native_commit_unavailable_id",
                        (ULONGLONG)(unsigned int)screen_id);
        }
        return;
    }
    if (elapsed >= DLUMA_MODS_TRANSITION_TIMEOUT_MS)
    {
        /* ShowNextUI first plays the current screen's TransOut timeline. A
         * same-frame visibility test is invalid, but a three-second timeout
         * is useful diagnostics. Never force the destination through
         * ILevel::ShowUIScreen: that bypasses UIMainMenuScreen's history and
         * produces an orphan page with no working Back action. */
        dluma_log_u64("WARN", "mods_screen_native_transition_timed_out_id",
                    (ULONGLONG)(unsigned int)screen_id);
        dluma_ui_fail_safe_restore_main_menu();
        dluma_ui_clear_mods_transition();
    }
}

static void __fastcall dluma_ui_menu_button_hook(
    void *menu_main, void *button, unsigned int event_code)
{
    DlumaMenuMainButtonFn original;
    int handled = 0;

    dluma_atomic_increment(&g_dluma_menu_button_active_calls);
    original = g_dluma_menu_button_original;
    dluma_ui_note_live_frontend_screen(menu_main);
    if (!g_dluma_menu_button_stopping && !g_dluma.stop_requested)
        handled = dluma_ui_first_launch_handle_button(button);
    if (!handled && !g_dluma_menu_button_stopping && !g_dluma.stop_requested)
        handled = dluma_ui_new_global_handle_button(
            menu_main, button, event_code, original);
    if (!handled && !g_dluma_menu_button_stopping &&
        !g_dluma.stop_requested &&
        dluma_ui_object_id_equals(button, "B_Mods"))
    {
        if (dluma_atomic_compare_exchange(&g_dluma_mods_button_log_once, 1, 0) == 0)
            dluma_log_line("INFO", "MenuMainDI received the first B_Mods button event.");
        handled = dluma_ui_route_mods_button_by_id(menu_main, button);
    }
    /* On the supported build B_Mods is ID-driven, matching MenuMainDI's stock
     * button routes without requiring the authored control to derive from
     * UINaviButton. If any exact-build validation fails, the original handler
     * still gets the same event so the packaged XuiNavButton PressPath remains
     * a fail-soft fallback. */
    if (!handled && original) original(menu_main, button, event_code);
    dluma_atomic_decrement(&g_dluma_menu_button_active_calls);
}

static int dluma_ui_install_mods_button_hook(void)
{
    static const char get_id_export[] =
        "?GetId@IObject@gui@@QEBAAEBV?$string_base@D@ttl@@XZ";
    static const char get_level_export[] =
        "?GetLevel@IObject@gui@@QEBAPEAVILevel@@XZ";
    static const char get_screen_id_export[] =
        "?GetUIScreenIdByScriptName@ILevel@@QEAAHAEBV?$string_base@D@ttl@@@Z";
    static const char register_screen_export[] =
        "?RegisterUIScreen@ILevel@@QEAAHAEBV?$string_base@D@ttl@@HH_N0H@Z";
    HMODULE gamedll;
    HMODULE engine_module;
    BYTE *base;
    void **slot;
    void *expected;
    DWORD timestamp;
    DWORD image_size;
    DWORD old_protect;
    DWORD restored_protect;

    if (g_dluma_menu_button_vtable_slot &&
        g_dluma_menu_button_original)
        return 1;
    gamedll = GetModuleHandleW(L"gamedll_x64_rwdi.dll");
    if (!gamedll ||
        !dluma_ui_get_pe_identity(gamedll, &timestamp, &image_size) ||
        timestamp != DLUMA_DEVTOOLS_GAMEDLL_TIMESTAMP ||
        image_size != DLUMA_DEVTOOLS_GAMEDLL_IMAGE_SIZE)
        return 0;

    base = (BYTE *)gamedll;
    slot = (void **)(base + DLUMA_DEVTOOLS_MENU_BUTTON_VTABLE_SLOT_RVA);
    expected = base + DLUMA_DEVTOOLS_MENU_BUTTON_FN_RVA;
    if (!dluma_is_readable(slot, sizeof(*slot)) || *slot != expected ||
        !dluma_is_readable(expected, 16))
    {
        dluma_log_line("WARN", "MenuMainDI B_Mods hook validation failed; stock button routing remains unchanged.");
        return 0;
    }
    engine_module = g_dluma.engine.engine_module ? g_dluma.engine.engine_module : GetModuleHandleW(L"engine_x64_rwdi.dll");
    if (!engine_module)
    {
        dluma_log_line("WARN", "engine_x64_rwdi.dll is unavailable; the native MODS registration bridge cannot start yet.");
        return 0;
    }
    g_dluma_get_object_id = (DlumaGetObjectIdFn)GetProcAddress(
        engine_module, get_id_export);
    g_dluma_get_object_level = (DlumaGetObjectLevelFn)GetProcAddress(
        engine_module, get_level_export);
    g_dluma_bridge_get_ui_screen_id = (DlumaGetUIScreenIdFn)GetProcAddress(
        engine_module, get_screen_id_export);
    g_dluma_bridge_register_ui_screen = (DlumaRegisterUIScreenFn)GetProcAddress(
        engine_module, register_screen_export);
    if (!g_dluma_get_object_id || !g_dluma_get_object_level ||
        !g_dluma_bridge_get_ui_screen_id || !g_dluma_bridge_register_ui_screen)
    {
        dluma_log_line("WARN", "Required gui::IObject/ILevel exports are unavailable; the native MODS registration bridge is disabled.");
        return 0;
    }
    if (!VirtualProtect(slot, sizeof(*slot), PAGE_READWRITE, &old_protect))
    {
        dluma_log_hex("WARN", "VirtualProtect failed for MenuMainDI vtable slot",
                    GetLastError());
        return 0;
    }
    g_dluma_menu_button_original = (DlumaMenuMainButtonFn)*slot;
    g_dluma_menu_button_vtable_slot = slot;
    g_dluma_menu_button_stopping = 0;
    g_dluma_menu_button_active_calls = 0;
    *slot = (void *)dluma_ui_menu_button_hook;
    VirtualProtect(slot, sizeof(*slot), old_protect, &restored_protect);
    FlushInstructionCache(GetCurrentProcess(), slot, sizeof(*slot));
    dluma_log_line("INFO", "Native MODS registration bridge hook installed before frontend level discovery.");
    if (!dluma_ui_install_registry_hooks())
        dluma_log_line("WARN", "Global mod registry UI hooks were not ready; the game-thread pump will retry.");
    return 1;
}

static int dluma_ui_restore_mods_button_hook_now(void)
{
    DWORD old_protect;
    DWORD restored_protect;
    int slot_restored = 0;

    dluma_atomic_exchange(&g_dluma_menu_button_stopping, 1);
    if (!g_dluma_menu_button_vtable_slot)
    {
        slot_restored = 1;
    }
    else if (dluma_is_readable(g_dluma_menu_button_vtable_slot, sizeof(void *)))
    {
        if (*g_dluma_menu_button_vtable_slot ==
            (void *)g_dluma_menu_button_original)
        {
            slot_restored = 1;
        }
        else if (*g_dluma_menu_button_vtable_slot !=
                 (void *)dluma_ui_menu_button_hook)
        {
            /* A later owner may chain through us. Keep pass-through state. */
            dluma_log_line("WARN", "MenuMainDI button slot changed ownership; loader callback state is retained in pass-through mode.");
        }
        else if (VirtualProtect(g_dluma_menu_button_vtable_slot, sizeof(void *),
                                PAGE_READWRITE, &old_protect))
        {
            *g_dluma_menu_button_vtable_slot = (void *)g_dluma_menu_button_original;
            VirtualProtect(g_dluma_menu_button_vtable_slot, sizeof(void *),
                           old_protect, &restored_protect);
            FlushInstructionCache(GetCurrentProcess(),
                                  g_dluma_menu_button_vtable_slot, sizeof(void *));
            slot_restored = 1;
            dluma_log_line("INFO", "MenuMainDI B_Mods vtable hook restored.");
        }
        else
        {
            dluma_log_hex("WARN", "VirtualProtect failed while restoring MenuMainDI B_Mods hook",
                        GetLastError());
        }
    }

    return slot_restored;
}

static void dluma_ui_uninstall_mods_button_hook(void)
{
    ULONGLONG started;
    int slot_restored = dluma_ui_restore_mods_button_hook_now();

    started = GetTickCount64();
    while (dluma_atomic_compare_exchange(
               &g_dluma_menu_button_active_calls, 0, 0) != 0 &&
           GetTickCount64() - started < 1000)
    {
        Sleep(1);
    }
    if (dluma_atomic_compare_exchange(
            &g_dluma_menu_button_active_calls, 0, 0) != 0)
    {
        dluma_log_line("WARN", "Timed out draining MenuMainDI button callbacks; original callback pointer is retained.");
        dluma_atomic_exchange(&g_dluma_ui_teardown_failed, 1);
        return;
    }
    else if (!slot_restored)
    {
        dluma_log_line("WARN", "MenuMainDI hook was not restored; original callback pointer is retained.");
        dluma_atomic_exchange(&g_dluma_ui_teardown_failed, 1);
        return;
    }

    g_dluma_menu_button_original = 0;
    g_dluma_menu_button_vtable_slot = 0;
    /* A callback that entered before the stop flag will not call GetId after
     * the flag becomes visible, so this can be cleared once routing stops. */
    g_dluma_get_object_id = 0;
    g_dluma_get_object_level = 0;
    g_dluma_bridge_get_ui_screen_id = 0;
    g_dluma_bridge_register_ui_screen = 0;
}

static void __fastcall dluma_ui_extras_button_hook(
    void *menu_extras, void *button, unsigned int event_code)
{
    DlumaMenuMainButtonFn original;
    int handled = 0;

    dluma_atomic_increment(&g_dluma_extras_button_active_calls);
    original = g_dluma_extras_button_original;
    dluma_ui_note_live_frontend_screen(menu_extras);
    if (!g_dluma_extras_button_stopping && !g_dluma.stop_requested &&
        dluma_ui_object_id_equals(button, "B_DLUMALogs"))
    {
        if (dluma_atomic_compare_exchange(
                &g_dluma_extras_button_log_once, 1, 0) == 0)
            dluma_log_line(
                "INFO", "MenuExtras received the first B_DLUMALogs button event.");
        handled = dluma_ui_route_logs_button_by_id(menu_extras, button);
    }
    if (!handled && original)
        original(menu_extras, button, event_code);
    dluma_atomic_decrement(&g_dluma_extras_button_active_calls);
}

