static void __fastcall dluma_ui_options_button_hook(
    void *menu_options, void *button, unsigned int event_code)
{
    DlumaMenuMainButtonFn original;

    dluma_atomic_increment(&g_dluma_options_button_active_calls);
    original = g_dluma_options_button_original;
    dluma_ui_note_live_frontend_screen(menu_options);
    if (!g_dluma_options_button_stopping && !g_dluma.stop_requested &&
        dluma_ui_object_id_equals(button, "B_DLUMALoaderSettings"))
    {
        void *level = 0;
        int screen_id = -1;
        if (dluma_atomic_compare_exchange(
                &g_dluma_options_button_log_once, 1, 0) == 0)
            dluma_log_line(
                "INFO", "MenuOptions received the first B_DLUMALoaderSettings button event.");
        if (g_dluma_get_object_level)
        {
            level = g_dluma_get_object_level(button);
            if (!level)
                level = g_dluma_get_object_level(menu_options);
        }
        if (level)
        {
            dluma_log_u64("INFO", "loader_settings_registration_bridge_level",
                        (ULONGLONG)(ULONG_PTR)level);
            screen_id = dluma_ui_register_settings_screen(&g_dluma.engine, level);
            if (screen_id >= 0)
            {
                dluma_log_u64(
                    "INFO", "loader_settings_registration_bridge_id",
                    (ULONGLONG)(unsigned int)g_dluma_settings_screen_id);
                dluma_log_u64(
                    "INFO", "loader_settings_registration_bridge_presspath_id",
                    (ULONGLONG)(unsigned int)screen_id);
            }
            else
            {
                dluma_log_line(
                    "WARN", "B_DLUMALoaderSettings registration bridge could not make MenuDLUMALoaderSettings.xui resolvable; the original handler still receives the event.");
            }
        }
        else
        {
            dluma_log_line(
                "WARN", "gui::IObject::GetLevel returned null for B_DLUMALoaderSettings and MenuOptions; the original handler still receives the event.");
        }
        dluma_log_line(
            "INFO", "Delegating B_DLUMALoaderSettings to original MenuOptions/UIMainMenuScreen PressPath route.");
    }
    /* MenuOptions delegates unknown buttons to UIMainMenuScreen. Register
     * against the clicked object's exact live ILevel, then let the original
     * path own PressPath lookup, history, frames, and Back navigation. */
    if (original)
        original(menu_options, button, event_code);
    dluma_atomic_decrement(&g_dluma_options_button_active_calls);
}

