int dluma_ui_stop_succeeded(void)
{
    return dluma_atomic_compare_exchange(&g_dluma_ui_stop_ok, 0, 0) != 0;
}

static void dluma_ui_quiesce_impl(unsigned int observed_exit_owner_calls)
{
    const LONG finalize_state = dluma_atomic_compare_exchange(
        &g_dluma_ui_content_finalize_state, 1, 0);
    if (finalize_state == 0)
    {
        const int finalized = observed_exit_owner_calls
            ? dluma_custom_map_asset_trace_game_thread_finalize_from_exit_game_owner(
                  observed_exit_owner_calls)
            : dluma_custom_map_asset_trace_game_thread_finalize();
        if (finalized)
            dluma_atomic_exchange(&g_dluma_ui_content_finalize_state, 2);
        else
        {
            dluma_atomic_exchange(&g_dluma_ui_content_finalize_state, 0);
            dluma_atomic_exchange(&g_dluma_ui_teardown_failed, 1);
            dluma_log_line(
                "WARN", "Authoritative game-thread content report finalization failed; loader state is retained for process-exit safety.");
        }
    }
    else if (finalize_state != 2)
    {
        dluma_atomic_exchange(&g_dluma_ui_teardown_failed, 1);
        dluma_log_line(
            "WARN", "Authoritative content report finalization is still active; loader state is retained for process-exit safety.");
    }
    dluma_atomic_exchange(&g_dluma_ui_stopping, 1);
    dluma_atomic_exchange(&g_dluma_registry_hooks_stopping, 1);
    dluma_atomic_exchange(&g_dluma_menu_button_stopping, 1);
    dluma_atomic_exchange(&g_dluma_extras_button_stopping, 1);
    dluma_atomic_exchange(&g_dluma_options_button_stopping, 1);
    if (g_dluma.ui_timer_id)
    {
        KillTimer(0, g_dluma.ui_timer_id);
        g_dluma.ui_timer_id = 0;
        dluma_log_line("INFO", "Game-thread UI registration timer cancelled.");
    }
    dluma_ui_restore_registry_hooks_now();
    (void)dluma_ui_restore_extras_button_hook_now();
    (void)dluma_ui_restore_options_button_hook_now();
    (void)dluma_ui_restore_mods_button_hook_now();
}

void dluma_ui_quiesce(void)
{
    dluma_ui_quiesce_impl(0);
}

void dluma_ui_quiesce_from_exit_game_owner(
    unsigned int observed_exit_owner_calls)
{
    dluma_ui_quiesce_impl(observed_exit_owner_calls);
}
